/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20200309-3","meetingId":"r02-c-budget","date":"2020年3月9日","dateIso":"2020-03-09","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５７分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を180件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"湯澤委員","kind":"質問","question":"私からは、２１３ページ、認知症高齢者支援事業、それから２２３ページ、障害者訓練等給付事務について質問します。認知症高齢者支援事業につきまして、現在、区内の認知症の方は１万２,０００人程度と認識しておりますが、これは何を基準にカウントした数でしょうか。そこには軽度認知症も含まれているのでしょうか。実際にはもっと多くの方が認知症でいらっしゃるとお考えでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"それから品川区としての認知症の方への取り組みですけれども、大きく分けて３点ございまして、１つは認知症を正しく理解していただくための普及啓発、それから早期に発見できる見守りの仕組み、それから予防。","id":"exchange-001"},{"speaker":"湯澤委員","kind":"意見","question":"認知症がどんなものかを地域で認識して、また考えること、そして介護する側のサポートを充実させることも大変重要だと思います。そこで、区では介護者や、これから介護するかもしれないといった方々に対してどんな取り組みをされているかもお答えいただければと思います。","respondent":"寺嶋高齢者福祉課長","answer":"介護者、ご家族の方が中心になろうかと思いますけれども、こういった方への支援ということでは、先ほどと一部重複しますが、認知症サポーター養成講座というのは、もちろん広く一般の方もご受講いただいていますけれども。","id":"exchange-002"},{"speaker":"湯澤委員","kind":"質問・要望","question":"ただ、冊子の中ほどに自立度別サービス一覧表というものがありまして、そこだけがちょっと見づらいかなと思ったところがありまして、関係者の方からもちょっとそんな声を伺いました。せっかくいい冊子なので、誰が見てもわかりやすいような、さらによいものにしていただければなということを要望しまして、次の質問に移らせていただきます。","respondent":"松山障害者福祉課長","answer":"今、国の一律給付という制度の中で行っておりますけれども、当事者の状況を就労移行支援事業所と連携してお声を聞きながら、何か支援策はないか検討していきたいと考えています。","id":"exchange-003"},{"speaker":"湯澤委員","kind":"意見","question":"東京都では障害者手帳の所有者に都営鉄道や都営バスの全路線を無料で使用できるような支援を行っております。そこで、区内にある障害支援事業所を利用する場合に限るなどして範囲を限定した全ての公共交通費を助成することも検討されてはいかがかと考えますが、区のご見解をお知らせください。","respondent":"松山障害者福祉課長","answer":"就労移行支援事業所に通っていただきたいということと、ご本人の持つ負担ということになると思うのですけれども、どの程度の負担感なのか、あるいはそれぞれの収入に応じて異なるものですので、まずは移行支援事業所を通じて実態の把握に努めたいと考えています。","id":"exchange-004"},{"speaker":"湯澤委員","kind":"意見","question":"ぜひ自立に対して強い意志を持つ障害者の方に対しまして、こういった軽減策の検討を、今後よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"せお委員","kind":"質問","question":"私からは、２３１ページ、障害児者総合支援施設運営費、障害者福祉事務費、２４５ページ、区立保育園費、２１７ページ、高齢者社会参加促進事業、２５９ページ、私立幼稚園振興費等補助金、お時間があれば２１３ページ、紙おむつ支給についてお伺いします。ですから、並行通園が基本だと思います。そこで、今お話ししたような児童発達支援のあり方について区はどのようにお考えか、まずお聞かせください。","respondent":"築山障害者施策推進担当課長","answer":"療育といたしましては一律ではなく、その方に合った支援が提供できるようにするものと考えています。児童発達支援センターにおける療育のあり方については、指定管理者と協議しながら検証を進めてまいります。","id":"exchange-006"},{"speaker":"せお委員","kind":"確認","question":"その際ですが、先ほども申しましたように保育園、幼稚園の受け入れ体制も整っていなくてはなりません。確認となりますが、現在、区立保育園、幼稚園において障害を持ったお子さんの受け入れはどのようになっているのか、来年度予算の中に特別支援保育の予算も計上されていますが、今年度とどのように変わってくるのか、お聞かせください。","respondent":"佐藤保育課長","answer":"特別支援保育の充実に関しましては平成３０年度に体制を見直しまして、今後も積極的に充実に努めてまいります。","id":"exchange-007"},{"speaker":"せお委員","kind":"質問・要望","question":"一般質問でお聞きしましたが情報ネットワークシステムをできるだけ早く構築していただき、障害者福祉課、相談支援事業所、子ども未来部、あとはご本人とご家族で連携のとれた情報共有をして、支援計画を立てていただいて、それぞれの子に合った支援を提供できるよう、品川児童学園の方向性も含めて検討していただきたいと思います。現在、そちらの２施設の活用方法は検討されていますでしょうか。","respondent":"築山障害者施策推進担当課長、松山障害者福祉課長","answer":"私からは、こみゅにてぃぷらざ八潮の現在の状況についてご説明いたします。こちらの施設については、当初から工事期間中の仮移転先として活用するものとしていたものです。戸越ルームに関しましては、障害者福祉課の所管のものです。医療的ケアの必要なお子さんのご家族が抱える不安等を解消するため、医療的ケアに関する相談業務を実施したいと考えております。","id":"exchange-008"},{"speaker":"せお委員","kind":"質問・要望","question":"医療的ケア児の施設というか、相談業務をする場所ということで、医療的ケア児の施設は本当に一番少なかったので待ち望んでおりました。医療的ケア児の相談業務の施設ということですが、ニーズを把握しながら事業内容なども検討していただきたいと思っています。そちらの検討会とかは当事者も加わったような何か会議とかになりますでしょうか。お伝えできる範囲で教えてください。","respondent":"松山障害者福祉課長","answer":"引き続きその会議の中で検討していきたいと考えています。","id":"exchange-009"},{"speaker":"せお委員","kind":"質問・要望","question":"この運用は、国や公共交通機関の事業者の判断となるわけですが、国土交通省は昨年、利用の際に障害者手帳等を提示するという規定を削除して、これと並行して交通事業者に対し、障害者手帳の確認方法の見直しについて理解と協力を求める文書を出しています。款が違うところはお答えいただかなくて結構ですが、お答えできる範囲で品川区のこちらの考えをお聞きかせください。","respondent":"松山障害者福祉課長","answer":"障害者にとって利便性のある情報につきましては、今後区のホームページに上げていきたいと考えています。","id":"exchange-010"},{"speaker":"せお委員","kind":"確認","question":"事業者へのサポートも行いながら、事業者や品川区内でも連携し合って進めていってほしいと思っています。区立保育園費に移ります。例えば来月、４月に初めてお子さんを保育園に入園させるという方からは、この状況では不安なので５月や６月に入園を延期させたいというお声も聞かれました。品川区においては、このような取り扱いでよろしいでしょうか。確認になりますが、お聞かせください。","respondent":"佐藤保育課長","answer":"委員ご指摘のとおり、これまでは４月末までに保護者が職場に復帰してもらうことが必須でございましたが、今、委員ご紹介のとおり先週の金曜日、３月６日の夕方に国から通知がございまして。","id":"exchange-011"},{"speaker":"せお委員","kind":"意見","question":"高齢者社会参加促進事業です。６５歳以上のひとり暮らしの方は男女ともに増加傾向にあって、６５歳以上人口に占める割合は男性が１３.３％、女性は２１.１％となっています。そこで心配になるものの１つが食の問題で、高齢者の孤食はコミュニケーション不足と栄養問題にまで及びます。このようなＮＰＯ法人と連携して交流する事業も必要かと考えますが、見解をお聞かせください。","respondent":"宮尾高齢者地域支援課長","answer":"現在、例えば一般会計予算では高齢者の外出習慣化事業といいまして、おひとり暮らしの自宅に引きこもりがちな方を対象として、ＮＰＯの協力をいただきながら、まさに文字どおり外出を習慣化していただこうという事業を行っているほか。","id":"exchange-012"},{"speaker":"せお委員","kind":"質問","question":"ひとり暮らしの高齢者が増加することに伴って必ず孤食というのは課題になりますので、ぜひご検討をお願いしたいと思っています。次に、私立幼稚園振興費等補助金です。こちらはどのような補助金でしょうか。お聞かせください。","respondent":"大澤保育支援課長","answer":"お尋ねの補助金ですが、運営費の助成のほかに教員の研修費、園児の教材費、児童の健康管理費、そして心身障害児教育事業費補助金、防災安全対策費補助金というふうに項目が分かれてあります。","id":"exchange-013"},{"speaker":"せお委員","kind":"質問・要望","question":"品川区としては、私立幼稚園に関してもこのような補助金を含めて支援していますので、このことをご存じない園などに積極的に周知をお願いしたいと思っています。こちらは要望で終わります。確認なのですが、社協でのこのサービスでは、紙おむつは不足していませんでしょうか。発注も大変かと思うのですが、確認でお聞きかせください。","respondent":"寺嶋高齢者福祉課長","answer":"社会福祉協議会のほうから事業者に確認をとったところ、今の段階で特段の不足等の状態は生じていないというような回答を得たと聞いております。","id":"exchange-014"},{"speaker":"つる委員","kind":"提案","question":"２３２ページ、児童福祉費は在宅子育て支援に関連して伺います。２３８ページは子ども家庭支援センター、これは保育ソーシャルワーク、歳入のときに伺った件を聞いていきたいと思います。それから２２０ページ、障害者福祉費については手話言語条例について、２３７ページ、入退室システム運用経費、これはすまっぴについて確認していきたいと思います。","respondent":"廣田子ども育成課長","answer":"一番大事なのは総合的に子育て支援を俯瞰できるような形、仕組みづくりが必要と認識していますけれども、いろいろな補助金等の関係から一気に１つのところにということはかなり難しいかなと考えていますが。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問・要望","question":"お子さんに恵まれて出産されたご家庭から毎回相談を受ける中の１つとして、いろいろな所管課にまたいでいるとか複雑だという声はいただくところでありますので、今後また引き続きわかりやすい組織づくりをご検討いただきたいと思います。次に、子ども家庭支援センターに関連して、保育ソーシャルワークについて伺っていきたいと思います。これは歳入のところでもお聞きしました。","respondent":"崎村児童相談担当課長","answer":"ただ、先ほど委員からありましたように、保育園の中での運営の部分ではどうしても保育士不足ということもありますので、円滑に運営していくという中でこういった地域連携推進員を設置したいという保育園がもしあるようでしたら、我々としても。","id":"exchange-016"},{"speaker":"つる委員","kind":"質問・要望","question":"改めて別の機会でも求めていきたいと思います。先日もろうあの方の家族の方からお話を伺ったときに、やはり家族間では日本手話であるし、また親が聞こえなくて、聞こえる健聴の子ども、コーダさんたちは日本手話、いわゆるバイリンガルができる、そういうさまざまな課題があるわけでありますが、今現在の品川区の手話言語条例に対する考え方、方向性を教えてください。","respondent":"松山障害者福祉課長","answer":"引き続き行ってまいりますが、全日本ろうあ連盟のほうから手話言語に関する見解というものが公表されておりまして、その中におきましては日本手話、日本語対応手話を分けて、そのことにより聞こえない人、聞こえにくい人。","id":"exchange-017"},{"speaker":"おくの委員","kind":"質問","question":"私からは２１３ページの特別養護老人ホーム運営費に関わって、特養ホームについて質問いたします。今年２月末締め切りの特養ホーム入所申込み申請者数をお教えください。","respondent":"寺嶋高齢者福祉課長","answer":"２月末日で今回の特養ホームの入所調整の申し込みを締め切りまして、今現在は申請書の内容点検、それからシステムへの入力作業をしておりますので、正確な数字は今の段階では申し上げることができませんが、受け取ったときの感触というか、紙ベースのイメージとしましては前回。","id":"exchange-018"},{"speaker":"おくの委員","kind":"質問","question":"７４歳になる男性で、要介護４です。さて、特養ホームの入所申込み申請者に対しては、入所調整会議で入所者を決めるために点数をつけますけれども、その点数は要介護度、年齢、介護認定期間、そして介護状況、この４つの観点から点数がつけられることになっていて、特養ホームに入れる点数はおおよそ７０点だと伺っています。この認識でおおむねよろしいでしょうか、いかがでしょう。","respondent":"寺嶋高齢者福祉課長","answer":"例えばそのときの申込み者の方の点数が上のほうの点数の方が少なければ、当然ですが６５点、６０点という方が入っているといった事例もあります。平均すると、７０点までしか入れないということは、今までは特に起きていないと認識しています。","id":"exchange-019"},{"speaker":"おくの委員","kind":"質問","question":"おおむね６０点から７０点程度というふうに認識しておいてよろしいですか、伺います。","respondent":"寺嶋高齢者福祉課長","answer":"先ほど申し上げたとおり、何点だから入るというものではなくて、そのときの点数で決まってくるので、高い点数の方が少なければ、もちろん空きがあればの話ですけれども、ご希望の方がいて空きっぱなしにしていくということは基本的にはありませんので。","id":"exchange-020"},{"speaker":"おくの委員","kind":"質問","question":"それで、この方にも年齢の観点から点数は１点もつきません。有料老人ホームですから月３０万円かかって、今も入っています。いつまで払い続けられるかわからないという例です。特養ホームは、まさにこういう方のためにある制度ではないでしょうか。そこで伺います。今、４８歳ですから、もう何十年もその生活を続けざるを得ません。これは明らかに不当な結論ではないでしょうか。この点をお伺いいたします。","respondent":"寺嶋高齢者福祉課長","answer":"特養ホームではなく、ご本人にとってももっとふさわしいサービスというものも多々ありますので、そういったものをきちんとご説明した上でご理解、ご判断いただくというところが重要だと考えております。","id":"exchange-021"},{"speaker":"おくの委員","kind":"質問","question":"多々ご説明いただきましたけれども、私が伺っているのはこの方のことです。まだ５０歳にもならないこの方が特養ホームに入ることを希望しながら有料老人ホームに入らざるを得ない。このままだともう何十年も有料老人ホームの生活を続けざるを得ないというのは不当なことではないかとお考えにはなりませんかと、そういうふうにお伺いしたのです。いかがでしょうか。お答え願いたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"先ほど申し上げたとおりですけれども、１点補足しますと、まず有料老人ホームからでも特養ホームへの入所申し込みは可能です。","id":"exchange-022"},{"speaker":"おくの委員","kind":"質問","question":"７５歳以上でなければ点数は上がらないわけです。だから年齢要件のために阻まれているわけです。この状態は不当ではないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問・要望","question":"２４３ページ、子どもの未来応援事業から、これはふるさと納税を活用したガバメントクラウドファンディングだと思うのですけれども、改めて寄附金額、寄附者数、区内・区外の内訳を教えていただきたいのと、プレス発表にも出ていますけれども、来年度はどういう形になっていくのか、教えてください。","respondent":"三ッ橋子ども家庭支援課長","answer":"５５７万３,０７３円の内訳ですが、区内は１５７万３,０００円、区外は４００万７３円となっております。プレス発表いたしましたけれども、今年度は目標金額３００万円といたしておりましたが、来年度につきましては５００万円と寄附金額の目標を上げしています。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問・要望","question":"こういうふうに応援してくださる方がいて、すばらしい事業だと思うのですけれども、これを継続していっていただきたいと考えています。この事業は子ども家庭支援課から子育て応援課にかわるのですか。子育て応援課というのは聞いたことはないですけれども、事業はこの子育て応援課に継承していっていただけるのですか。","respondent":"三ッ橋子ども家庭支援課長","answer":"そちらの業務内容につきましては一切変わりませんので、今回のガバメントクラウドファンディング、ふるさと納税を活用した食の支援は子育て応援課が引き続き実施してまいります。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"頑張ってください。なぜかというと、プレス発表もしているし、たまっていなければいいのですが、封筒でも何でも印刷物、名刺、そういうものも全部廃棄しなければならない。そういうことを思うと、変えないで済むならば課の名前は変えるべきではないと私は思っております。この辺も、課の名前はなるべく変えないで済むなら変えないほうがいいと思っているのですが、その辺についてはいかがでしょうか。","respondent":"三ッ橋子ども家庭支援課長","answer":"こちらにつきましてはさまざまな状況がありますので、子ども家庭支援課から子育て応援課に課名変更となっております。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"私は成年後見制度について毎回、トラブルはありませんね、事故はありませんねと担当課長に伺ってきて、その答えは「ありません」「しっかりきちんとやっています」ということなのですが、なぜ今になって基本計画を策定していかないといけないのでしょうか。このまましっかりやっていけば、私は何の問題もないと思うのですけれども、経費を使ってそれをする理由を教えてください。","respondent":"大串福祉計画課長","answer":"この法の趣旨は、基本的にやはり成年後見制度がなかなか利用されてない状況を踏まえて、各区市町村で利用促進を図るように計画を進めろというところで、国からの要請を受けて策定するものです。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問・要望","question":"成年後見については、国を引っ張るぐらいの施策を品川区はしていたわけです。これは日本の国の中で評価も高いことだし、評価も高い自治体だと考えていますが、今、伺って、やらなければしようがないからやっていくという思いもあるとは思うのですけれども、今まで何の事故もトラブルもないわけですから、引き続きこの施策はやっていっていただきたいと考えています。教えてください。","respondent":"寺嶋高齢者福祉課長","answer":"その辺も加味しまして、品川区としてはまだ外国人材の受け入れを進めているところがほとんどありません。それに対して、他の自治体ではかなり先進的にやっているところも多くあります。この辺の情報を今年度収集しまして、来年度の予算案として計上させていただいたところです。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"賛成できない。あの仕事の内容に対して、介護士がどれだけ大変で、どれだけ精神的にも追い詰められて、そのときにいろいろ考えていく中で、やはり賃金というのは大事ではないですか。民間の平均の給料は４００万円台ではないですか。介護士の方たちの夫婦のお給料で品川区におうちを１軒持てないではないですか。課長、バサッと保険ですからと切らないで、ぜひ前向きな答弁をいただきたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"勤続年数とか年齢によってそれぞれ給料の金額が違いますので、一概に高い、安いというのをこの場で申し上げるのは大変難しいのですけれども、仕事の内容としてとても大変な仕事をやっていただいているということに関しましては、心底そのように思っております。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"処遇改善のお話が出ましたが、本当に処遇改善のシステムというのは複雑なのです。単純ではないのです。金額を出すのは本当に複雑。それだったら人が集まらないわけがないではないですか。そして本当に一生懸命やってくれている、そこに応えていくというのは、行政の仕事ではないですか。やっています、ありますではなくて、そういう意味も含めてもう一回、ぜひ答弁していただきたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"それで、先ほど申し上げたのは、そういうことを踏まえた上で各施設、法人に対していろいろな形で支援費等をお出しして、それで結果的に処遇の向上に努めていただくように全面的にできる範囲での支援をさせていただいていると、こういう状況ですので。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"私の一般質問で再質問をしたときに、福祉部長から、給料だけではなくて総合的に上げていきますという答弁をいただいたと思っています。これからも、この件に関して私はずっと、議員でいるうちは追っていきたいと考えていますので、どうにか喜んでいただける職場環境に一緒にしていきましょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問","question":"障害者のほうは２３１ページの障害児者の福祉計画に関わると思うのですが、高齢者福祉にはちょっと見つからなかったのですが、ケア者支援のことを伺いたいと思います。それで、２４３ページからは未来を拓く学習支援と学習支援ボランティア事業、同じページで子ども食堂開設・運営支援等について、時間があるところまで伺います。最初にマスクのことです。","respondent":"立川総務課長、松山障害者福祉課長、廣田子ども育成課長、寺嶋高齢者福祉課長","answer":"マスクの東京都への要請ですが、区としましては都に要請はしておりませんが、都のほうから既に東京都の備蓄分を放出ということで。障害者福祉課所管分につきましては、東京都から２３区全体で８万枚、１事業所当たり約９０枚ということで。すまいるスクールには東京マラソンで使用しなかったマスクと消毒液を学童用にということで一部提供を受けているところです。ただ、そこから先については不足が生じるという見込みの報告を受けておりまして、これは数字を把握しまして、区の庁内会議に報告させていただいて。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。その中から３点伺いたいと思います。私の読み違いでなければ、次年度は民間事業者を１事業者増やす予算だと読み取れるのですが、今年度行ってきた事業をどのように評価して次年度につなげようとしているのか、伺いたいと思います。障害児者の包括的な相談支援体制の強化と書いてあるのですが、障害児の相談支援体制につながっているのか、その辺の実績も伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"今年度ですけれども、在宅介護支援センターに併設する高齢障害の方、あるいは高齢になる手前の障害者の方、あるいは２号被保険者の方に対応するような特化したようなタイプのものが２事業所できました。民間のほうも４事業所できております。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"それで次の質問に入りますが、障害者相談支援システムネットワーク整備として基本構想の検討委託が次年度予算立てされております。どういうシステムを構想しているのでしょうか。どういうところにどういう形で検討の委託を行うのか、伺います。これは私の見落としでしょうか。それとも何か削る理由があったのでしょうか。伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"どこまで外部と庁内との連携がとれるシステムが構築できるのかということにつきましては、来年度は基本構想ということで、業者に委託して区と一緒に考える予定です。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは要望として、ぜひそういう方向で検討していただきたいと思います。次の質問にいきます。今までどれぐらいの相談実績があるのか、伺いたいと思います。どういう形態、一回一回申し込んで相談するのか、それともある程度１つの相談をしたら継続して何回かで解決、解決というのはどの辺かわかりませんけれども、解決に至るまでの相談ができるのか、その辺のシステムについても伺います。","respondent":"松山障害者福祉課長","answer":"城南ブロックの高次脳機能障害の拠点病院の荏原病院と連携しまして、高次脳機能障害の症例検討会等を実施している仕組みになっております。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問","question":"平成３０年度の実の数字が５５人というのは、この５５人はみんな専門的な相談に対応できる方の相談を１回は受けたと理解してよろしいでしょうか。何か後のほうのご説明を聞くと、やはり最初に高次脳機能障害の状態を把握するために専門的な人のチェックが必要と理解したのですが、それでよろしいでしょうか。","respondent":"松山障害者福祉課長","answer":"そこから検査が必要だということであれば、この相談員につながる方もいらっしゃいますし、病院のほうから直接検査評価をしてほしいということでこちらの相談をお受けになる方もいらっしゃいます。５５人の方が受けているです。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは要望しておきます。次に、高齢者福祉と障害者福祉全般からケア者支援について伺いたいと思います。実態把握はどのように進んだか、伺いたいと思います。障害者福祉に関する当事者へのアンケートが昨年度に実施されましたが、その中に「あなたの年齢」と、「あなたの介護者は誰ですか」ということをそれぞれ問う項目があります。これらの実態把握はどのように進んでいるか、それぞれ伺います。","respondent":"寺嶋高齢者福祉課長、築山障害者施策推進担当課長","answer":"ダブルケアの関係の情報収集、実態調査ということで、今までは例年、給付通知をお送りするときにモニタリング調査ということでアンケート用紙をお送りして、おおむね３年間で全員から回答をいただくということでやっておりました。障害者福祉課のほうでは、第６期品川区障害福祉計画および第２期品川区障害児福祉計画策定に当たりまして基礎調査を実施したところです。","id":"exchange-037"},{"speaker":"吉田委員","kind":"提案","question":"高齢者福祉のほうも、もし後でご答弁があれば伺います。議員提案での上程を目指していて、現在、プロジェクトチームで議論が進められていて、昨年１２月に条例案についての進捗の報告を聞く機会がありました。ぜひ、各部署でアンテナを高くしてケア者の状況を見つけ出す努力をしていただきたいのですが、さっきの高齢者のことだけをちょっと伺いたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"今回、ダブルケアというところに着目してアンケート項目を増やしましたけれども、通常のご相談の段階で、例えば老老介護であるとか、それから一定程度の年齢がいったひきこもりのお子さんがいらっしゃるとか、こういったことは地域包括支援センター。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"繰り返しになりますけれども、ヤングケアラーの場合、そういうご相談に行くという発想がないのです。若い方たちで、もっと年齢が低いと、行政に自分が行っていいのだという認識がない。ぜひその辺をちょっと頭の隅にでもいいから置いていただいて、日々の掘り起こしということに努めていただきたいと思います。ほかのことは別の機会に伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"松本委員","kind":"質問","question":"本日は２１７ページ、高齢者社会参加促進事業、２１９ページ、高齢者福祉施設運営費、２４９ページ、あと２５５ページと２５９ページにあるのですけれども、オリンピック・パラリンピック応援事業ついて伺えればと思います。その中でふれあい給食というものがあるのですけれども、こちらの事業内容、開催頻度、参加者の声などの反響がございましたらお聞かせください。","respondent":"宮尾高齢者地域支援課長","answer":"今年度は１２月末時点で２８校にご協力いただいて実施しています。例年大体３０校程度にご協力いただいて実施しています。","id":"exchange-040"},{"speaker":"松本委員","kind":"質問","question":"かなり開催していただいているということで、いいことだと思います。継続的な接点というか、１回だけやりましたということだと、それはそれでイベントとしては大事だと思うのですけれども、一度接点を持った、給食を一緒に食べたような児童とシニア世代の方たちがその後も継続的に交流するというようなことはあるのでしょうか。","respondent":"宮尾高齢者地域支援課長","answer":"こちらのほうも引き続き内容の充実を図ってまいりたいと考えております。","id":"exchange-041"},{"speaker":"松本委員","kind":"質問","question":"そうすると、年齢が広がれば広がるほど、その分、話題が合わないというようなこともあるのではないかと思うのですけれども、交流する中で話が合わないかもしれないといった懸念というか、不安のところを払拭する上では、何か工夫はされていますでしょうか。","respondent":"宮尾高齢者地域支援課長","answer":"ただ一方で、繰り返しになってしまいますが、ふだんなかなか機会のない、例えば核家族化が進んでいる中でそういった年の離れた方との接点がふだんなかなかないお子さんにとって、ご高齢の方の昔話だったり。","id":"exchange-042"},{"speaker":"松本委員","kind":"質問","question":"お子さんにとって本当にいい機会だと思います。ここはなかなか難しいという話を私も地域から伺っていて、なぜかといったら、デジタルデバイドという言葉がありますけれども、インターネットとかスマートフォン、ここの部分が結構大きいのだろうなと思います。これは、深いところでいったら理解できなくて不安なのだというような思考というのもシニア世代には結構あるのかなと思うのです。","respondent":"宮尾高齢者地域支援課長","answer":"私からは、いきいきラボ関ヶ原で実施しておりますパソコン・タブレット教室についてお答えします。こちらは、基本的にはシニアの方たちに便利なものとして情報通信端末を使えるようになる、そのハードルを下げる一助となればというところで開催しております。","id":"exchange-043"},{"speaker":"松本委員","kind":"質問・要望","question":"これは要望です。ちょっと時間がないので次にいきますと、オリンピック・パラリンピック応援事業なのですけれども、これは当初予算案のプレス発表資料を拝見いたしますと、区立保育園の東京２０２０大会機運醸成というようなものがあがっております。これは区立保育園と限定されているのですけれども、これを区立に限定されている趣旨というのはどういうことでしょうか、お願いします。","respondent":"佐藤保育課長","answer":"プレスの編集の単位なのですけれども、保育課ということで区立保育園に特化したものを書いておりまして、内容といたしましては実際に観戦するときの熱中症対策経費と、実施競技の体験教室とか英語体験も一定程度やりますので、その辺を書いているところです。","id":"exchange-044"},{"speaker":"松本委員","kind":"質問","question":"区立がまず書いてあって、私立のほうも予算説明書を見ると一応予算は上がっているのですけれども、これは本区の場合もなかなか認可に入れないご家庭がある中で、認可に入れている人たちにはこういった応援の支援があるけれども、結局実際には認可に入れないという方たちがいるというところで、認可外の方たちに対して、区民の公平性というところからどうなのかなということもあるのですけれども。","respondent":"大澤保育支援課長","answer":"オリンピック・パラリンピックの……。","id":"exchange-045"},{"speaker":"芹澤委員","kind":"質問","question":"私からは２４３ページ、しあわせ食卓事業、関連して坂井市との連携について、時間があれば２６５ページのフードパントリー事業について伺います。しあわせ食卓事業について伺います。今年度から新事業としてしあわせ食卓事業をスタートされたということで、目標額３００万円のところ、５５０万円余りの寄附が集まったという記載があります。","respondent":"三ッ橋子ども家庭支援課長","answer":"周知をいたしましたところ、こちらは申請制度ですけれども、食の支援が必要だと思われた方々からの実際の申請は約３００世帯となっております。","id":"exchange-046"},{"speaker":"芹澤委員","kind":"質問","question":"そうすると、３００万円のもともとの目標額は当然達成されて、これから食料が配送されるということですが、想定していたよりも多い食料、もしくは高品質のものが送られるというような認識でよろしいのでしょうか。","respondent":"三ッ橋子ども家庭支援課長","answer":"目標額３００万円のところ、実際は５５７万円余となっております。こちらにつきましては、ひとり親家庭のしあわせ食卓事業以外に子ども食堂への継続支援というものもありますので、そちらを差し引いた部分を支援してまいります。","id":"exchange-047"},{"speaker":"芹澤委員","kind":"質問","question":"そういった意味では、今年度は３００世帯に配布予定ということで、来年から目標額も大きく引き上げられるということですから、ぜひこれは幅を広げていただいて、また周知方法もさまざま考えていただいて、生活保護等もそうですが、役所のお世話になる、行政のお世話になるということを少しハードルに思っている方々もまだまだいらっしゃるかと思いますので。","respondent":"三ッ橋子ども家庭支援課長","answer":"こちらの思いやり型返礼品というのは、寄附することで、自分のためではなく誰かのためになるというような趣旨でございまして、ふるさとチョイス対応のきふとというものです。","id":"exchange-048"},{"speaker":"芹澤委員","kind":"質問・要望","question":"このホームページにも、今、まさにおっしゃったような米の流通がなかなかできない中でウィン・ウィンになると坂井市のほうにも書いてあるのですが、どういった経緯であれ、品川区のしあわせ食卓事業にとっては非常に大きな、ありがたい事業でありますので、ぜひこれはどこかの形で、今現在では品川区のホームページ等ではこういった事業がありますよというのは書いていないかと思いますが、発送の時点なのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"松澤委員","kind":"質問","question":"私からは２１１ページ、高齢者等地域見守りネットワーク事業、２１３ページ、認知症高齢者支援事業、２２１ページ、家具転倒防止対策助成、順不同にて質問いたします。先ほどもご答弁がありましたけれども、品川区もさまざまな取り組みを推進し、支援が充実しておりますが、特に力を入れている、また評価が高い、そういった取り組みなどがありましたら教えてください。","respondent":"寺嶋高齢者福祉課長","answer":"１回目は昨年のゴールデンウィークが大変長い期間のお休みでして、その早い段階で認知症の方が警察に保護されますと、警察に結構長期間いなければいけないという事態が想定されまして、その場合に区内の地域密着型ホームに至急保護して。","id":"exchange-050"},{"speaker":"松澤委員","kind":"質問","question":"見守りアイテム、これも大変効果的だというのは私もお聞きしていました。その中で当事者のお話をお聞きしますと、やはり人のつながり、これにとても刺激されます。品川区における認知症カフェの取り組みは、１１か所から２０か所と、だんだんと拡充している、広がりを見せていますが、どのような経緯で広がりがあったのでしょうか。教えてください。","respondent":"寺嶋高齢者福祉課長","answer":"もう一つ特徴的なのは、これは荏原第二地区という旗の台あたりの地区になるのですけれども、こちらには町会が主体となってやっていただいているカフェが４か所ほどございまして、当初は専門家がいないのでどうだろうかというご相談もいただいたのですけれども。","id":"exchange-051"},{"speaker":"松澤委員","kind":"質問","question":"私も町会が主体でやっているとは知りませんでした。だんだんと拡充していく、これは認知症になっても住みやすいまちづくりがだんだんとつくられているということかなと感じております。しかし、認知症というものは早期相談、早期診断というのがとても大切であります。そういった映像を流すとか、そういった取り組み、こういうものはありますでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"今、委員からご紹介いただきましたみんなの談議所、こちらにつきましては区の高齢者福祉課も今、連携ができておりまして、いろいろな形で情報交換、情報共有を行っているところです。","id":"exchange-052"},{"speaker":"松澤委員","kind":"質問","question":"やはり認知症の当事者の方がしゃべるという、お話しするというのは非常に参考になると私も思っております。しかし、やはり一番は早期診断であると思います。そこで、先ほどもちょっと答弁が出ましたけれども、品川区における早期診断の取り組みについてのお考えはありますでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"そういった意味で、来年度、医師会の方にご協力いただきまして、令和３年度に向けた認知症検診の実施に向けた準備を進めていきたいと考えております。","id":"exchange-053"},{"speaker":"松澤委員","kind":"質問","question":"正しい知識が広がり、安心して住み続ける品川を強く望み、次の質問へ移らせていただきます。東京都防災会議の被害想定によりますと、マグニチュード７.３の地震が夕方に発生した場合、都内全域で約５万４,５００人が家具類の転倒・落下により負傷すると想定され、建物の耐震化と並び重大な地震対策ではないでしょうか。そこで、ここ数年において、この助成金が使われている傾向を教えてください。","respondent":"宮尾高齢者地域支援課長","answer":"昨年、平成３０年度は６２件、平成２９年度が２８件の申請をいただいておりまして、平成３０年度が他の年度よりも突出して高かったのは、この年は全国各地で、例えば北海道の胆振地方、それから大阪、熊本、こういったところで大きな地震があって。","id":"exchange-054"},{"speaker":"松澤委員","kind":"質問・要望","question":"やはり年度によってばらつきがあるということは、今、課長がおっしゃったように防災イマジネーション、不燃化でも言いましたが、想像力の低下によっていろいろな部分でばらばらになってしまうかと思われます。家具転倒は寝ているときが一番危険だとお聞きしました。そういったところにしっかり拡充できるように、これからも支援していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"あくつ委員","kind":"質問・要望","question":"会派としては、この制度の創設を強く強く求めてきました。そして昨年の第３回定例会でも、本事業を声の上げにくい子どもたちと困難のあるご家庭のために継続性を持った事業としてぜひ育てていただきたいと要望しておりましたので、今回の継続については歓迎させていただきたいと思います。対象はひとり親世帯とどのような世帯であったのか、ひとり親世帯とそうでない世帯別にその内訳を教えてください。","respondent":"三ッ橋子ども家庭支援課長","answer":"周知の仕方ですけれども、児童扶養手当、こちらはひとり親医療証発送のときに、約１,５００世帯全員の方にお知らせをいたしました。そのほか広報しながわ１２月２１日号にお知らせをしています。","id":"exchange-056"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほど伺った、集まった５５７万円余の子ども食堂との割合、どちらにどのぐらいの割合で配分するのかということも教えてください。私はこれを見て「えっ」と首をかしげたところがあったのです。今回も同じような対象者がこのプレス発表資料には書いてあって、「等」と書いてあるので、今回も「等」だと思うのですけれども、この「等」のところを検討していただきたいと思うのですが、いかがでしょうか。","respondent":"三ッ橋子ども家庭支援課長","answer":"今回、５５７万円余が集まりまして、まず子ども食堂の継続支援に１００万円、こちらは子ども応援基金の中に入れします。その残りの部分をしあわせ食卓事業に充当していくところです。そして周知ですが、確かに委員おっしゃるように１２月末の段階でございました。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"提案","question":"３年前になりますでしょうか、私が文教委員長のときに提案させていただいて、区内の子ども食堂を委員会として視察したことがあります。次に２１３ページ、避難行動要支援者個別計画の作成でケアマネジャーの関与。それとも今後、今回要支援者の名簿に載っている方たちのうちで要支援・要介護の方については、全てケアマネジャーが引き受けるということなのでしょうか、このあたりのイメージを教えてください。","respondent":"寺嶋高齢者福祉課長","answer":"ただ実際に町会ごとに規模も違いますし、それから取り組みの進度も若干違っておりまして、場所によってはまだ十分に避難計画等がなされていないといったところも踏まえまして、福祉の観点から。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"確認","question":"２０１ある町会・自治会、全ての所管、全ての管轄に在支はあるわけです。このケアマネジャーがそこに全部顔を出して、まずは町会・自治会の方と関係を構築して、そして、その上でそういうことをやっていくのか、そこについてちょっとイメージが湧かなかったものですから教えてください。","respondent":"寺嶋高齢者福祉課長","answer":"その際は、もちろんご本人の同意を得た上でケアマネジャーと町会の方が顔を合わせて相談するということになっていると思いますので、これを基本形としまして、それに対して取り組みの進みが若干遅いところ。","id":"exchange-059","title":"町会・自治会支援"},{"speaker":"あくつ委員","kind":"質問","question":"そこのところについてちょっとイメージが湧きにくかったものですから。もう一つ、個人情報保護の関係を前にも総務費のところでやらせていただきましたが、いわゆる個人情報取扱事業者になるわけです。そもそも在支は、在支の職員として、そこが事業者になるのか、それとも委託している民間の居宅介護支援事業所の扱いになるのか、そこについてわかれば教えてください。","respondent":"寺嶋高齢者福祉課長","answer":"個人情報保護の観点に関しましては、区内の２０の在支それから民間の居宅介護支援事業所、いずれにしてもケアプラン作成のときにご本人の同意を得るという行為が必要になってきます。","id":"exchange-060"},{"speaker":"あくつ委員","kind":"提案","question":"おっしゃるとおり、ケアプラン等を立てるときに個人情報保護に関しては、恐らく町会・自治会以上に在支のほうはきちんとやっておられるのかなと思うのですが、新しい形になりますので、そこについては、私が前からご提案しているのは、ちょっと所管が違いますけれども、町会・自治会において、これは個人情報保護に関するものの規定をしっかりとつくらないと、もし母体が町会・自治会の。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061","title":"町会・自治会支援"},{"speaker":"くにば委員","kind":"質問","question":"本日は、２４７ページ、就学前教育推進費のＩＣＴ体験事業、２４５ページから保育室等記録機器モデル導入経費についてお伺いします。昨年６月、文部科学省から新時代の学びを支える先端技術活用推進方策という報告書が発表されまして、その中で、学校のＩＣＴ環境は鉛筆やノート等の文房具と同様に教育現場において不可欠のものとなっていることを強く認識する必要があるとの記述があります。","respondent":"佐藤保育課長","answer":"実績に関しましては、多くの保育園で利用されておりまして、貸出期間における利用率は約６０％という状況です。他区での導入状況ですが、こちらのロボットに関しましては２３区初と認識しております。","id":"exchange-062"},{"speaker":"くにば委員","kind":"質問・要望","question":"先ほどご紹介がありましたように就学前教育とロボットを組み合わせた取り組み、こちらは他自治体での事例が全くない中、大変興味深い取り組みだと感じます。ぜひ拡充を図っていただきたいと思います。次に、こどもモードＫｉｔＳ搭載アプリについてお伺いします。こちらも事業内容、導入した経緯等をお伺いします。","respondent":"佐藤保育課長","answer":"実績に関しましては、昨年度のモデル実施に関しましては大体６５％程度の利用率です。他自治体の導入状況ですが、民間の幼稚園や保育園では導入実績がありますけれども、公立に関しては２３区初です。","id":"exchange-063"},{"speaker":"くにば委員","kind":"質問・要望","question":"２つの事業とも２３区で初ということで、こちらの事業に関して本当に庁内全体であるとか、いろいろな方々にぜひ知っていただきたいと思います。続きまして、２４５ページの保育室等記録機器モデル導入経費についてお伺いします。函館市のとある認定こども園では、映像記録機器導入から５年間で園内でのけがが３分の１に減ったとの事例もありました。","respondent":"吉田保育施設調整担当課長","answer":"現場説明会は２月末に終わりまして、提案内容については３月、選定会議によって３月末に業者を決めまして、４月に契約、設置工事等もありますので５月頃から運用を開始しようと予定しています。","id":"exchange-064"},{"speaker":"くにば委員","kind":"質問・要望","question":"今回、まずは４園でのテスト導入ということで、こちらの導入の有用性を考えますと、区立保育園全施設において早期の導入促進を求めますが、追加設置についての取り組み、また幼稚園での設置のお考えについてお聞かせください。","respondent":"吉田保育施設調整担当課長","answer":"そういう面を含めまして、まずは４園で実施いたしまして、そこでの問題点だとかがありましたら洗い出してみたいと考えております。その後の展開につきましては、検証を経まして、どうしていくかというところを考えていく予定でおります。","id":"exchange-065"},{"speaker":"くにば委員","kind":"質問・要望","question":"保育の質という部分に関して、事故はぜひとも減らしていただきたい。こちらのＩＣＴや記録機器に関しては、保育の質だけではなく、やはり保育士の負担を減らす、そういった部分の側面もありますので、ぜひとも労働環境の改善も含めて取り組みをお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問","question":"２１９ページ、北品川シルバーセンター改築検討経費、同ページの高齢者クラブ支援事業に関わって電動アシスト三輪自転車について、２３７ページ、すまいるスクールの新型コロナウイルス感染症対応について伺います。利用できない期間は代替場所を確保すべきだと思いますが、いかがでしょうか。敷地面積や改築要件などから従来の高齢者の利用が狭まってしまうということはないのか、伺います。","respondent":"宮尾高齢者地域支援課長","answer":"ただその間、これまでもシルバーセンターの建て替えをする際には周りのシルバーセンターへの丁寧な周知を促す、あるいは他の区有施設をご案内するなどの丁寧な対応をしてまいりましたので、本件につきましてもそのような丁寧な対応をしていきたいと考えております。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ工夫をお願いします。私が参加したグループ討論では移動支援の要望が多く出されました。具体的には、コミュニティバスとともに三輪電動自転車への補助や貸し出しの検討を、というご要望でした。そこで伺いますが、品川区でも、先の高齢者クラブの懇談会で出されましたこの電動アシスト三輪自転車の購入費補助の検討を行ってはいかがでしょうか、伺います。","respondent":"宮尾高齢者地域支援課長","answer":"こういった事業を通じて、まずは皆さんがしっかりと健康な体力を維持していただいて、いつまでもご自身の足でいろいろなところに行っていただくというところをベースに推進していきたいと考えているところです。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問","question":"こんな事例があったのですけれども、昨年１２月、私の主催する報告懇談会に、しばらく見ていなかった８０代の男性が久しぶりに参加してくれたのです。これを見て合点がいきました。伺いますけれども、高齢者の外出や社会参加の支援にとって、この電動アシスト三輪自転車というのは有効だと思いますけれども、この効果についてはどのように区はお考えでしょうか。","respondent":"宮尾高齢者地域支援課長","answer":"実際にその効果を調べたということはございませんが、一つ言えるのは、私どもは日ごろから高齢者クラブの方たちとおつき合いをしていますが、例えばその中には体調がなかなか思わしくなくて会議に出ることができない、こういったことをおっしゃる方もいらっしゃいます。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"全然かみ合っていないのです。しかし障害のあるお子さんというのは、小学校４年生以上であっても自宅にはいられないという声も届いています。障害のある子は特にそうだと思うのですけれども、事情や希望があれば、小学校４年生以上であっても考慮して午前中からすまいるスクールで受け入れるような体制をとるべきだと思うのですが、いかがでしょうか。","respondent":"廣田子ども育成課長","answer":"登録のないお子さんに関しましても、就労等事情がある場合はご相談に応じてということになっておりますので、誰でもというわけではございませんが、現在のところ４年生以上で障害がある方で今回特別に、という方は耳に入ってきてはございません。","id":"exchange-070"},{"speaker":"安藤委員","kind":"質問","question":"まだ耳に入っていないということですが、すごく必要な方というのはいらっしゃるし、実際にそういう心配が届いていますので、ぜひそういったお声があれば個別に事情を考慮していただいて、率先して感染予防に協力いただいている方もいるわけですから、ぜひご検討の上、受け入れをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"木村委員","kind":"確認","question":"私からは、２１１ページの上から４行目、高齢者安否確認事業からの質問をしたいと思います。２０００年の品川区の高齢化率というものが１７.１％、そして２０１２年には約２０％、そして２０１７年には２１％、そしてこれから５年後の２０２５年には本区の高齢化率が２２％と予想されております。お聞きいたします。","respondent":"大串福祉計画課長","answer":"町会・自治会の皆様方による見守りといったところかと思います。今現在、令和元年度で６１の町会・自治会の皆様方にご協力いただいているところです。","id":"exchange-072"},{"speaker":"木村委員","kind":"質問","question":"品川区では今現在、２０３の町会・自治会があると私も記憶しております。平成３０年３月末の時点で６１の町会・自治会がさまざまな形で見守り活動を行っておりますけれども、現在、本区でのパトロール活動というのをやっている町会・自治会というものは以前と変わりがないのかどうか、お聞きかせください。","respondent":"大串福祉計画課長","answer":"こちらといたしましては、町会・自治会の皆様方にお願いしている際には、あくまでも無理のない範囲で、やりやすい範囲、またはそれぞれの地域の特性に応じた形での見守り、これをやっていただきたいというお願いをしているところでございまして、取り組みの中身としては。","id":"exchange-073","title":"町会・自治会支援"},{"speaker":"木村委員","kind":"意見","question":"今言われたように町会・自治会ごとにいろいろなパターンがあろうかと思いますけれども、またこれもしっかりと続けてほしいと思います。見守りパトロール中に実際に起きたトラブル等のまれなこと、何か変わったようなことが起きた事例というのはあるのかどうか、今後のためにも差し支えのない程度でお聞かせいただければと思います。","respondent":"大串福祉計画課長","answer":"この事業が始まって、見守り活動の中で特に何かトラブルということがあったということでのお話は、こちらには特に届いているところではございません。","id":"exchange-074","title":"町会・自治会支援"},{"speaker":"木村委員","kind":"質問・要望","question":"お聞きいたします。品川区では、誰もが安心して住み続けることのできる地域社会を実現するために、町会・自治会、民生委員、高齢者クラブなど、地域で活動する皆さんや民間事業者の協力を得ながら見守り活動を行っていますけれども、民間事業者だけではなく、個人個人が今以上に仲よくなる策や、また町会単位で活動を考えるべきと思いますけれども、いかがでしょうか。","respondent":"大串福祉計画課長","answer":"品川区は、まだまだそうした形でのおたがいさま、あるいは支え合うという気質が残っている地域です。そうしたものをうまく醸成しながら、共生社会の実現に向けて各施策を充実させていきたいと考えているところです。","id":"exchange-075","title":"町会・自治会支援"},{"speaker":"木村委員","kind":"質問・要望","question":"ぜひ先頭を担って、また活動していただければと思っています。品川区の人口が増えることで、隣り近所のつながりも時とともに薄くなってきていると私も感じておりますが、行政が入り込むことにも限界があると思いますけれども、区、町会・自治会とが力を合わせて、より一層高齢者に対して気配りをし、今以上に地域の集まりを開催し、温かく見守っていただきたいと思います。お聞かせください。","respondent":"大串福祉計画課長","answer":"今後ともそういった機会を捉えて、こういった事業の展開等々をご紹介させていただきながら、そういった機会と場、この提供の機会を増やしていければと考えております。","id":"exchange-076","title":"町会・自治会支援"},{"speaker":"小芝委員","kind":"質問","question":"２２１ページの障害者理解についてお聞きします。２月５日に議員研修会で聴覚障害者のサッカー競技でありますデフサッカー日本代表の監督をされております植松隼人さんのお話をお伺いいたしました。昨年の決算特別委員会での課長答弁では、聴覚障害者協会の方々や当事者、ご家族の方々、また明晴学園のお考えをお伺いしながら研究を進めていきたいとのことでしたが、その後５か月を経過しました。","respondent":"松山障害者福祉課長","answer":"先ほどの話題にもなりました日本語対応手話、日本手話といった違いはあれども、理念ですとか、手話が言語であるという考えということにつきましては、ある程度ですけれども合意しつつあります。","id":"exchange-077","title":"議員研修会の内容と所要時間"},{"speaker":"小芝委員","kind":"質問","question":"今後も引き続き研究していただき、前向きに検討いただければと思います。聴覚障害に関連しまして、聴覚障害者の国際競技大会ですデフリンピックのことでちょっとお聞きします。去年の決算特別委員会でもデフリンピックの開催について聞きましたところ、課長からは国、都と連携して開催できるかどうか検討していきたいという答弁をいただいておりますが、その後の検討の経過をお聞かせ願います。","respondent":"松山障害者福祉課長","answer":"デフリンピックの検討状況についてです。デフリンピックを東京に招致したいというお声は聴覚者障害の方からも受けているところです。委員ご紹介のとおり聴覚障害者の方のいわゆるパラリンピックということですので、なかなか区だけでは難しいというところになります。","id":"exchange-078"},{"speaker":"小芝委員","kind":"質問・要望","question":"長期基本計画にもうたわれています誰もが参画・活躍できる豊かな地域社会の実現に向けて前向きに進んでいってもらいたいと強く要望いたします。次に、２４７ページの東大井保育園についてお伺いします。東大井保育園の老朽化に伴います改築工事により、東大井公園内に仮の園舎を建設し、４月から２年間、仮の園舎を稼働するとの話を伺っております。わかれば教えてください。","respondent":"吉田保育施設調整担当課長","answer":"立会川方面からの厳密に細かい人数までは不明なのですが、約５０名はいらっしゃるのではないかと考えております。","id":"exchange-079"},{"speaker":"小芝委員","kind":"質問","question":"そこでお聞きします。さらに言いますと、丁字路を曲がる箇所には横断歩道がない上、ミラーもない場所です。平たんな道でもちょっと危ないかなと思うのですけれども傾斜のある道なので、その辺にミラーを設置するとか、あとは横断歩道をつくるとかして環境を整えていくべきだと思いますが、こちらのほうはどうなっているのか、教えてください。","respondent":"吉田保育施設調整担当課長","answer":"そこのところにたしかカーブミラー等がかなり多数あったように思います。その辺は、保護者の方に十分注意していただくよう周知してまいりたいと思っているところです。","id":"exchange-080"},{"speaker":"小芝委員","kind":"質問・要望","question":"ありがとうございました。続きまして、２３１ページのヘルプカードについてお聞きします。障害や内部障害をお持ちの方が、災害時や日常生活の中で困ったときに周囲に自分の障害への理解を求めるのがヘルプカードですが、このヘルプカードが来年度に新しく、新規といいますか配布されるとのお話を伺いましたが、その内容、形状について教えてください。","respondent":"松山障害者福祉課長","answer":"委員お尋ねのヘルプカードの内容、形状についてですが、当事者からはストラップ、いわゆるかばんにつけられるような形でというところと、あと今現在もある程度の支援情報を記載できる部分があると考えていますが。","id":"exchange-081"},{"speaker":"小芝委員","kind":"質問","question":"ヘルプカードに関連しましてヘルプマークというのがあります。このマークですが、現在は品川区では中延駅、戸越駅、五反田駅、あとは都営バスの営業所で配布されているとお聞きしておりましたが、こちらは地域センターなどには配布されているのでしょうか。","respondent":"松山障害者福祉課長","answer":"ただし、今は配布先が限定的なことから、配布先まで行かれない困難な方につきましては東京都のほうにお問い合わせいただいて、郵送する場合もあるという回答を得ております。","id":"exchange-082"},{"speaker":"小芝委員","kind":"質問","question":"続きまして、生活保護者の自立支援事業についてお聞きします。平成３０年度の品川区における生活保護受給の廃止原因を見てみますと、全体の中で就労に伴う収入増加は１１.４％で、本人の死亡そのほかに次いで２位でございました。この１１.４％の中で世代ごとの人数というのはわかりますか。特に生産年齢で２０代から５０代まで、その世代ごとの人数を、もしわかれば教えてください。","respondent":"矢木生活福祉課長","answer":"世代ごとの人数ですが、申しわけございません、統計をとっておりませんが、廃止の決定通知等は私を経由しますので、その感じだと４０代、５０代の方が多いように思っております。","id":"exchange-083"},{"speaker":"小芝委員","kind":"質問","question":"そうしたら、就職力アップ支援のことでお聞きしたいのですけれども、これは講習会や体験やカウンセリングなどが行われていると聞いておりますが、その対象者は世代ごとにわかりますか。もしわかれば教えてください。その成果も教えてください。","respondent":"矢木生活福祉課長","answer":"こちらも世代ごとということで、大体対象者と同じような傾向を示していると思います。そして成果といたしましては、平成３０年度は就労開始された方が１５人で、支援を終了された方が１２人。令和元年度は同様に就労開始された方が８人といった成果になってあります。","id":"exchange-084"},{"speaker":"小芝委員","kind":"質問","question":"生活保護者の中には精神の疾患を抱えている方や、そもそも就労経験がない人、引きこもりの方など、そのほかにもさまざまな理由で就労への課題を抱えた方がいると思います。そういう方々も一律にこの自立支援事業の対象に組み込まれているのでしょうか。","respondent":"矢木生活福祉課長","answer":"こちらの就職力アップの対象者ですが、開始原因の中で傷病、障害といった疾患を抱えられている方は除きます。そして稼働年齢層、おおむね高校生ぐらいから６５歳までの年齢ゾーンの方ということで、対象者をその中から選定しています。","id":"exchange-085"},{"speaker":"小芝委員","kind":"質問","question":"ちょっと時間が足りないので進めますが、２４１ページの高校生等入院医療費助成についてお聞きします。昨年７月から１５歳以上の高校生を対象にしまして入院医療費の助成が始まりました。これは、育ち盛りの高校生が予期せぬ病気で入院を余儀なくされた家族にとりましては、心に寄り添う具体的な政策であると考えます。その感想について、一言お聞かせ願います。","respondent":"三ッ橋子ども家庭支援課長","answer":"高校生の入院医療費助成ですけれども、かなり好評を得ております。","id":"exchange-086"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、２３５ページ、児童センター事業、２３７ページ、児童相談所移管推進事業、２３８ページ、子ども家庭支援センター費、すまいるスクール運営費、２４２ページ、児童保育費についてお伺いいたします。今後も国と都と区が一緒に、社会全体で取り組むべき重要な課題である子どもの健やかな成長に影響を及ぼす児童虐待の防止と発生時の対策を全力で進めていただきたいと強く要望いたします。","respondent":"二ノ宮児童相談所移管担当課長、廣田子ども育成課長","answer":"その理由といたしましては、通常、児童相談所を設置する自治体というのは措置権者と言われて、児童福祉法の権限に基づいて子どもを措置する権限を持つ自治体になるのですけども。今回、閉館するに当たっては、児童センターの職員は大変心を痛めているところではありますけれども、今現在、すまいるスクールの運営に児童センターの職員が新年度の準備を含めまして応援に出ている状況でございまして。","id":"exchange-087"},{"speaker":"横山委員","kind":"質問・要望","question":"ご紹介します。国や都の補助なども活用しながら子育てを応援いただきたいという思いで伺います。先日、つる委員の質問により区のお考えはわかりましたが、子育て応援、虐待予防の視点からも多胎児育児支援を要望いたします。多胎児妊産婦サポーター、また産後ドゥーラ、ベビーシッター、家事育児ヘルパーなど人材育成の支援を求め、進めていただきたいと思いますが、いかがでしょうか。簡潔で構いません。","respondent":"佐藤保育課長、廣田子ども育成課長、崎村児童相談担当課長","answer":"高い評価をいただきまして、誠にありがとうあります。今後も気を引き締めて区民サービスの充実に努めてまいります。すまいるスクールについても、引き続き地域の皆様に喜んでいただけるように取り組んでまいります。こちらも児童虐待の未然防止につながっていると認識しておりますので、こちらについても今後力を入れてまいりたいと考えております。","id":"exchange-088"},{"speaker":"横山委員","kind":"確認","question":"国の未就園児等全戸訪問事業に関連してもお伺いいたします。未就園児などの安否確認を区でしていただいているかと思いますが、その訪問する際なのですけれども、家庭に寄り添ったアプローチをぜひお願いしたいと思うのですが、区のお考えをお聞かせください。","respondent":"崎村児童相談担当課長","answer":"委員の質問にもございましたように、未就園というような理由だけで訪問するというのは、相手方の保護者にとってみますと虐待が疑われたと捉える方もいらっしゃるかと思いますので、そういった訪問をする際にどういったアプローチの仕方がよいのかということにつきましては。","id":"exchange-089"},{"speaker":"塚本委員","kind":"確認","question":"そういった中で、現在の給付のあり方について、国での議論というのが何かなされていることがあるのかどうかということと、その国の議論が前提だとは思いますけれども、区としてこの状況というかあり方についての考えということをお伺いしたいと思います。","respondent":"松山障害者福祉課長","answer":"区の認識についてですけれども、国全体の中で各事業所の負担感について、きめ細かな負担感の設定にはなっていない部分もあるのではないかと考えておりますけれども、ただし、事業者の負担感を客観的に、例えば上乗せ補助するという形にできるかどうかについては。","id":"exchange-090","title":"議員研修会の内容と所要時間"},{"speaker":"塚本委員","kind":"確認","question":"いわゆる良質なサービスというところで、そのためにということでの研究、検討を今後ともよろしくお願いしたいと思います。施設側の対応等で今までにはなかった新たな対策、対応というのか、そういったことも出てきたりしているところはないのか、これまでどおり安定して通常どおりだということなのか、そこを確認させてください。","respondent":"寺嶋高齢者福祉課長、松山障害者福祉課長","answer":"当初はご家族の方からどうしてなのだというようなお問い合わせも数件はあったように聞いておりますけれども、これは昨今の報道等からもおわかりいただけるように、それから、あと例えば容体が急変した場合。今のところ施設側から特段大きな変化はないと聞いております。これまでもインフルエンザ対策等できちんと感染症対策は気にかけておりまして、さらにそれ以上に感染症予防に配慮して支援を行っていると聞いております。","id":"exchange-091"},{"speaker":"塚本委員","kind":"質問","question":"一応３月３１日までということになっておりますけれども、これは新型コロナウイルス感染症の状況次第でどうなるかわからない、４月以降についてもというところはあるかと思いますので、特に高齢者の方を預けていらっしゃる方から、ずっと家族と会わないと認知症が進んでしまうのではないかとか、そういったご心配の声も届いていたりするので、長期化していくかもしれないという中では。","respondent":"大澤保育支援課長","answer":"私立保育園の特別支援児の加算ですけれども、区内私立保育園経費の運営費の区加算という項目の中に入ってあります。予算としては、今年度は昨年度の実績を踏まえまして５０名程度の予算を見込んでいるところです。","id":"exchange-092"},{"speaker":"塚本委員","kind":"質問","question":"そういったところで、基準の緩和というとちょっと言い過ぎなのですけれども、そういった例外的なというか、現場の状況において、現在の基準には沿っていないのだけれども、かなり客観的に周りから見ると特別支援は必要だねといったような場合に加配していくというような考え方というのは難しいのでしょうか、ご検討いただけないかというところなのですが、ご答弁をお願いいたします。","respondent":"大澤保育支援課長","answer":"基本的には特別支援の巡回指導等で臨床心理士の方が各園を回っており、そのときに保護者の方への伝え方等も相談にのっておりますので、その中で対応していただいているという状況です。","id":"exchange-093","title":"議員研修会の内容と所要時間"},{"speaker":"塚本委員","kind":"質問","question":"でき得る限り現場の状況に即した形で、臨機応変ではないのですけれども、そういった対応についても、特に保護者の方への理解促進ということがしっかり進めばこの問題も大分解決する部分もあると思いますので、よろしくお願いしたいと思います。最初に、事務負担増というのはどういうところが増えているのかというところを教えていただければと思います。","respondent":"大澤保育支援課長","answer":"無償化に伴う私立保育園の事務負担ですが、一番大きなところは副食費を保護者から徴収する事務が各園でかなり大変だと聞いてあります。ただ、品川区におきましては副食費分は公費負担になってありますので、品川区内の園ではそのような事務負担は生じておりません。","id":"exchange-094"},{"speaker":"塚本委員","kind":"意見","question":"今後は区としてもこの辺に注視していただいて、書類の簡素化あるいは手続きをＩＣＴ化等して、なかなか保育士の方というのはそういう事務という、その辺の能力を期待されて採用されているという方はあまりいらっしゃらないだろうと思いますし、そういう意味では事務の簡素化にいろいろな形でのアイデアを提供するではないですけれども、できる限りの簡素化ということに努めていただければと思うのですが。","respondent":"大澤保育支援課長","answer":"無償化に伴う事務に限らず、補助金ですとか公定価格の部分でかなり難しい書類がたくさんあることは認識していますが、都に出したり、国に出したりということでいたし方ない部分もあるのですけれども、できるだけわかりやすい説明をするなど、努めてまいりたいと思います。","id":"exchange-095"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"初めに２１７ページ、外国人介護人材受入環境整備、そしてＩＣＴ見守りシステム設置というところで、これは新規事業だと思うのですけども、プレス発表ですと外国人介護人材受入の支援として、外国人介護人材登用における現地面接からの受け入れということなのですが、これは事前にもうあらかじめ決めているのか、いないのかということと、取り組みをまず最初に教えていただきたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"特に令和元年度は他地区の法人が取り組んでいて、品川区の法人が未実施である事業といったあたりを重点的に洗い出しまして、その中の１つであったのが外国人材の活用というところでございました。","id":"exchange-096"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"このＩＣＴ見守りシステム設置支援の予算は３,９００万円余ということなので、結構これの構築を図って取り組んでいくのかなと思うのですけれども、その取り組み内容と、時期はいつごろになるのかということをお知らせいただきたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"それからやはり外国人ということなので法人が家を借りて、それに対して外国人に住んでもらうということで、大家に断られないような施策の一環としてやるということで、この２点を入れまして外国人に対する家賃助成は非常に効果的だと。","id":"exchange-097"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひとも人材確保、ＩＣＴ見守りシステムの設置をやっていただきたいと思います。続きまして４８５ページ、後期高齢者歯科健康診査についてお聞きいたします。今期、令和元年度から東京都後期高齢者医療広域連合からの補助金の交付を受けて実施しているということなのですけども、今期からの初めての事業だと思うので、まずその内容をお知らせいただきたいと思います。","respondent":"池田国保医療年金課長","answer":"後期高齢者医療の歯科健診の内容についてお知らせいたします。こちらにつきましては、一般的な口腔内検査のほかに口腔機能の評価、それからフレイル評価ということで３つの健診を行うものでございまして、従来の口腔内検査だけでなく、実際にフレイルに着目した検査です。","id":"exchange-098"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"わかりました。これは対象者が７６歳、７８歳ということなのですけれども、この対象者の方には年度内に受診してくださいということで、約７,０００人に対して受診の見込み者数が約２,０００人ということなのですけども、今大体どれぐらいの方が受診されているのか、わかれば教えていただきたいと思います。","respondent":"池田国保医療年金課長","answer":"今の歯科健診についてですけれども、１月３１日で終了ということになってございまして、私どものほうに請求があった件数ですが、実際には８１８件が２月末の結果として届いている状況です。","id":"exchange-099"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これは来年度、令和２年度にも予算として盛り込まれておりますけれども、今度は対象者が７６歳、７８歳に加えて８０歳の方も対象になるということなのですが、見込み人数もまた２,０００人ということで、これは見込みですから２,０００人という数字が出ているのですけれども、区の予想としてはどの程度になるのかということを教えてください。","respondent":"池田国保医療年金課長","answer":"今年度の実際の受診率につきましてはおよそ１４％を見込んでいたところですけども、来年度につきましてはおよそ１９％の方に受診していただくということで、７６歳、７８歳。","id":"exchange-100"},{"speaker":"のだて委員","kind":"質問","question":"私からは２３９ページ、子育て応援課の組織改編について、２４１ページ、子どもすこやか医療費助成事業について伺います。これまでは子ども家庭支援課という名称でしたが、来年度から子育て応援課に名称が変更されることが示されました。支援から応援と名称が変わり、一歩引いた感じがしております。福祉を後退させて、権利保障から自己責任に変質させるものではないのか、伺います。","respondent":"三ッ橋子ども家庭支援課長","answer":"引き続き子どもすこやか医療費助成、そしてひとり親家庭相談、またガバメントクラウドファンディングなど子育て事業の推進に向けて取り組んでまいります。","id":"exchange-101"},{"speaker":"のだて委員","kind":"質問","question":"内容は全く変わらないと、そういったこととは関係ないということでしたけれども、この機会に合わせて後退させるということがあってはならないと思います。これまでの子ども家庭支援課では、やはり児童手当とかひとり親家庭への支援などを行ってきた所管課ですので後退させてはいけないと考えていますけれども、施策を後退させるものではないということでよろしいでしょうか。","respondent":"三ッ橋子ども家庭支援課長、崎村児童相談担当課長","answer":"今回の課名変更ですが、来年度、児童相談機能の強化のために子ども家庭支援センターが課として設置されますので、その関係で子ども家庭支援課が子育て応援課に変更になります。本区におきましても、今回の組織改正において児童相談機能の強化、児童相談体制の一元化ということで子ども家庭支援センターを設置するものです。","id":"exchange-102","title":"議員研修会の内容と所要時間"},{"speaker":"のだて委員","kind":"質問・要望","question":"理由はわかりました。後退させるものでは全くないということでしたので、むしろこの名称が変わってよくなったと言われるようにぜひ充実していただきたいと思いますけれども、いかがでしょうか。","respondent":"三ッ橋子ども家庭支援課長","answer":"来年度から子育て応援課として事業が本当に進んで、いい課となるように引き続き努力してまいります。","id":"exchange-103"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ後退することがない、そしてむしろ充実していくということを要望し、今後を見ていきたいと思います。次に、子どもすこやか医療費助成について伺います。今年度から高校生の入院費まで無料ということで拡大されました。今年度の申請件数とその医療費を伺います。","respondent":"三ッ橋子ども家庭支援課長","answer":"今年度の申請が確定している件数は１６件で、その関係の費用ですけれども約１３０万円となっております。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問","question":"今年度の予算では２５０件で８０４万円となっていますけれども、見込みよりも低い水準になっているということになりますが、申請数が少ない理由は何だと考えているのか、伺います。","respondent":"三ッ橋子ども家庭支援課長","answer":"今、委員ご指摘の申請数が少ないという部分ですけれども、非常に難しいと捉えております。まだ明確なことは検証しておりませんけれども、元気な高校生が多いのか、そのあたりは検証しないと明確なことはわかりません。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問・要望","question":"今年度から始まったばかりということで、検証はこれからということでしたので、ぜひそこは検証していただきたいと思いますけれども、やはり今年度からということで周知が行き渡っていないのかなという点はあるのかと思っているのですが、一度お知らせが来ても、実際にけがなどをした場合にすぐに思い至らないということもあるのかなと思いますので、引き続き周知徹底をお願いいたしますが、いかがでしょうか。","respondent":"三ッ橋子ども家庭支援課長","answer":"こちらの周知徹底の部分ですけれども、４月１日、また４月２１日、そして６月２１日の広報しながわでお知らせしています。そのほか、各入院関係の医療機関にもお知らせを貼ってあります。そのほか児童扶養手当、子ども家庭支援課の窓口などでも対応しております。","id":"exchange-106"},{"speaker":"のだて委員","kind":"質問・要望","question":"千代田区の人口は約６万人ですので、単純計算ですと約６.５倍の予算、２億６,０００万円ということで大体妥当な見込みなのかなと考えていますけれども、１人当たり８,５００円ということになり、品川区の財政であれば十分可能だと思いますので、ぜひ１８歳まで医療費の無料化を実施していただきたいと思いますけれども、いかがでしょうか。","respondent":"三ッ橋子ども家庭支援課長","answer":"まだまだ検証の段階だと考えています。委員ご指摘のように２３区の中で千代田区だけが高校生までのすこやか医療費の助成をしているところでございまして、品川区といたしまして拡大につきましては非常に難しい、また今のところ全く検討していない状況です。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問","question":"全く検討していないというお話ですが、先ほどの入院費の問題でも無料にして大変好評だということでしたので、入院費の助成を今年度から始めた効果というのはいかがだったでしょうか。","respondent":"三ッ橋子ども家庭支援課長","answer":"今回、高校生まで拡大した高校生等の入院医療費助成ですけれども、申請された方のご意見を伺いますと非常によかったと聞いております。","id":"exchange-108"},{"speaker":"のだて委員","kind":"質問・要望","question":"助かると思いますので、ぜひ１８歳まで拡大していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"あべ委員","kind":"質問","question":"私からは新型コロナウイルス感染症の関係で高齢者福祉、児童福祉全般にわたっての質問、それから２３１ページ、障害児支援事業、２４２ページ、児童保育費、保育園の二次募集の申し込みの結果について、時間があれば２５９ページのオアシスルームまでお伺いしたいと思います。特に保育園などの応援態勢を考える時期に来ているのではないかと思いますが、いかがお考えでしょうか。","respondent":"佐藤保育課長","answer":"先般、３月２日に臨時の園長会を行いまして、今回の新型コロナウイルス感染症の対応に向けて全力で取り組むということで、複数担任とかというところはとりあえず見直すといいますか、今後の保育に向けては一定自分の家庭状況等、休める環境に向けて。","id":"exchange-110"},{"speaker":"あべ委員","kind":"質問・要望","question":"そのあたりの配置状況、そしてどのような形でシフトが組めているのかということも、保育課でぜひ確認をしていただきたいと思いますが、いかがでしょうか。この開設のスケジュール、それからこれは相談がメインということだと思うのですけれども、対象になる年齢ですとか、あるいは歩ける医療的ケア児や知的な遅れのない医療的ケア児にも対応するかどうかということについて、お考えをお聞かせください。","respondent":"吉田保育施設調整担当課長、松山障害者福祉課長","answer":"公設民営園の運営についてのお話かと思います。公設民営園につきましても区立園同様、柔軟なクラス編成をもちましてこの大変な事態を乗り切っていくように考えて、周知しています。委員お尋ねの戸越ルームのスケジュールについてですけれども、４月以降に委員会報告させていただいた後、公募の上、来年度中には開始していただくことを考えております。","id":"exchange-111"},{"speaker":"あべ委員","kind":"質問","question":"公設民営園についても周知だけではなくて、実際に確保できるような形でぜひ目を配っていただければと思います。それから、保育園の二次申込み結果が先週末に発送されたかと思うのですけれども、その結果の数字について、二次の申し込み数、承諾数そして不承諾数を教えてください。","respondent":"佐藤保育課長","answer":"一次と二次を足した後の不承諾数ですが、０歳児８５名、１歳児６１９名、２歳児２６５名、３歳児１４５名、４歳児５９名、５歳児４４名、合計１,２１７名で、一次の発表時よりも３７０名程度減っているところです。","id":"exchange-112"},{"speaker":"あべ委員","kind":"質問","question":"二次が終わった段階でも１,２００人以上の不承諾があるということで、これから数週間の間、大変心を痛めているところです。この１,２１７人の方々は、二次が終わった後でそれぞれどのような行き先があると考えていらっしゃいますでしょうか。今度の待機児童数がどの程度になるか、改めて見通しを教えてください。","respondent":"大澤保育支援課長","answer":"数としての提供はできておりますが、マッチングとしてはなかなか難しい部分もあると思いますので、実質的にはゼロに近い数になると思いますけれども、空きはあっても、待機児童としてはやはり何人かは残ると考えております。","id":"exchange-113"},{"speaker":"あべ委員","kind":"質問","question":"定期利用はその多くがひろまち保育園のあと１年間だけの定期利用ですので、来年度はここにさらにプラス１００人の行き先のない子どもたちがまた出てきて、来年度の待機児童激増の要因になるのではないかと危惧しております。来年度も含めての定期利用に対するお考えというのはどのようになっておりますでしょうか。","respondent":"大澤保育支援課長","answer":"令和３年４月の開設の計画につきましては、ひろまち保育園の閉園も見込んだ開設の計画を立てておりますので、そこは飲み込んでいけると現時点では認識しています。","id":"exchange-114"},{"speaker":"あべ委員","kind":"質問","question":"定員増については期待しております。ベビーシッター制度では今度東京都が、利用者にとっては１時間１５０円という非常に利用しやすい金額での新たな事業を打ち出しているところです。こうしたことが保護者の誤解やトラブルを生まないように、区のほうでも都と連携して説明が必要だと思いますが、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"区からのご案内でも、必ず利用案内、利用約款についてはご覧くださいということを明記しており、また、必ず区の窓口に一度は来て、職員から説明を受けることになっておりますので、その中でもその辺は漏れなくご案内したいと考えております。","id":"exchange-115"},{"speaker":"あべ委員","kind":"質問・要望","question":"最後にオアシスルーム、これは要望だけにしておきますが、八潮地域で今後開設に向けて努力するというご答弁をいただいております。本年度、是非ご検討いただければと思いますが、もし３秒でも可能であれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"西村委員","kind":"質問","question":"２３３ページ、地域子育て支援センター運営費、２３９ページ、ファミリーサポートセンター運営費、２５７ページ、子育て交流ルーム運営費、２５９ページ、地域子育て支援拠点事業費、時間が許せば、すまいるスクールについて伺います。品川区の乳幼児を育てている親子の居場所について、伺ってまいりたいと思います。今、区内にどのような場所があるでしょうか。教えてください。","respondent":"廣田子ども育成課長","answer":"品川区内にさまざまありますけれども、乳幼児親子の交流の場といたしましては、児童センターの中で行っております親子のひろばでありますとか、ぷりすくーる西五反田の子育て支援センター内にある子育て広場、またその他ゆうゆうプラザ。","id":"exchange-117"},{"speaker":"西村委員","kind":"質問","question":"私も区報などを見ながら、区内の親子施設を改めて整理してみたのですが、室内で平日をメインにいつでも行ける場所はどちらでしょうか。ぷりすくーる西五反田内の地域子育て支援センター、平塚橋の子育て支援センター、ポップンルーム、児童センターで合っていますでしょうか。教えてください。","respondent":"廣田子ども育成課長","answer":"場所によって曜日が決まっているものもありますが、全て自由に行くことができます。","id":"exchange-118"},{"speaker":"西村委員","kind":"質問","question":"プレイパークもありますが、室内に限って伺います。このおでかけひろばを運営する団体の方からお話を伺いました。品川区内の乳幼児を育てている父親、母親は、今ある施設をどれぐらい利用しているでしょうか。ベビーカーで行く行動範囲でいつでも行ける場所というと、ずっと減ってしまうのではないかと思いますが、いかがでしょうか。区内に空白地域はないでしょうか。お聞かせください。","respondent":"廣田子ども育成課長","answer":"現在、品川区内に児童センターが２５館ありますけれども、児童センターが空白地域となる荏原地域につきましては荏原区民センター、平塚橋、大崎のほうもそうですけども、空白地域ということで、こちらで子育て交流サロンを開いているという経過があります。","id":"exchange-119"},{"speaker":"西村委員","kind":"質問・要望","question":"児童センターは私も子どもが小さいころに利用させていただいたのですが、区民の方からの声は二分する部分がありまして、一度行って利用しなくなったという方の声も聞いてまいりました。せっかくセンターごとにさまざまな取り組みをしてくださっていますので、小さな子どもを育てている親がほっと和めるような居場所としての改善を要望しますが、いかがでしょうか。","respondent":"廣田子ども育成課長","answer":"児童センターを主軸としてはおりますけれども、空白となる地域につきましてはポップンルーム、その他さまざまな施設がありますので、アプリ等を利用しまして周知をして、いろいろなところを選択できるような形に努めていきたいと思ってあります。","id":"exchange-120"},{"speaker":"西村委員","kind":"質問・要望","question":"このような施設はたくさんありますけれども、少々わかりづらいというところを再度申し上げさせていただきまして、次の質問に移らせていただきます。区民の皆さんがサービスを活用するために、もう一度、地域のネットワークがどうなっているのかも見てみていただきたいと思っています。今後、子育て支援活動を行っているグループに対する支援の取り組みイメージがありましたら、お聞かせください。","respondent":"廣田子ども育成課長","answer":"一つは、地域の団体の方が自主グループで支援事業を行う際に、簡単な審査は行いますけれども、新年度から上限５万円として事業に対して助成をする制度も持ってあります。こちらにつきましては、使いやすいような形になるようにまた取り組んでいきたいと思ってあります。","id":"exchange-121"},{"speaker":"西村委員","kind":"質問・要望","question":"大変期待しております。地域のつながりの中で、ほっとサロンをサポートしてくださっている方々での、横の連携もあるというふうに伺いました。まさに先ほど申し上げましたような、心配な親子ですとか母親をサポートしながら、声をかけ合っているというふうに区民の方から伺っておりますので、ぜひとも支援の輪を広げていただけますようお願いいたします。次に、人的サポート面での質問をさせてください。","respondent":"三ッ橋子ども家庭支援課長","answer":"今年度につきましても、平塚、大井ファミリー・サポート・センターと定期的に打ち合わせを持ちまして、課題等を確認し、そして解決に向けて話し合っているところです。今後は、委員ご指摘のことも含めてさまざまな課題解決に向けて、一歩一歩進めていきたいと考えています。","id":"exchange-122"},{"speaker":"西村委員","kind":"質問・要望","question":"各自治体にはどのような取り組みがあるのかいろいろ調べてみたのですけれども、例えば品川区のホームページで「シッター」と検索をすると、このファミリー・サポートのサービスが出てくるですとか、さまざまに取り組みはあるのですけれども、そういった努力もしていただきながらではあるのですが、何か今の時代にそぐう形で、求めている方がこれだけいらっしゃいますので、できないかと思っています。","respondent":"三ッ橋子ども家庭支援課長","answer":"委員ご指摘のように、提供会員が少ないという部分に関しましては、依頼会員との比率でやはり、さまざまな状況、現場の声を聞いております。そのあたりにつきましても、平塚、大井ファミリー・サポート・センターの皆さんと、打ち合わせを持って対応してまいりたいと考えています。","id":"exchange-123"},{"speaker":"西村委員","kind":"質問・要望","question":"どうぞよろしくお願いいたします。最後になりますが、新型コロナウイルス感染症におけるすまいるスクールの体制に関しまして、改めて、区民の方々の声を届けさせていただきたいと思います。○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○、どのような声が区民の方から届いているか、お聞かせください。","respondent":"廣田子ども育成課長","answer":"すまいるスクールをご利用いただいているお子さんもいらっしゃるのですけれども、やはり子どもたちが一緒になるということで、何人ぐらい来ていますかということで、かなり心配されているご家族の方もいらっしゃいます。そちらについては少人数で部屋を分けて、対応しています。","id":"exchange-124"},{"speaker":"西村委員","kind":"質問","question":"最後に申し上げました、○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○○、特に低学年のお子さんは先生方もサポートしてくださっていると伺っておりますが、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-125"},{"speaker":"大倉委員","kind":"質問","question":"私は、オリンピック・パラリンピックの応援事業が幾つか挙がっているので、それについて伺いたいのですが、これ自体は金額が異なっているということと、内容の違いがあるのかということを簡単に教えていただければと思います。","respondent":"佐藤保育課長、大澤保育支援課長、宮尾高齢者地域支援課長、寺嶋高齢者福祉課長","answer":"保育課として予算のお願いをしているオリンピック・パラリンピック応援事業に関しましては、区立保育園５歳以上を対象に。私立保育園については公立保育園と同様ですが、私立幼稚園に関しましては、このほかにバレーボールセットを各園にお配りすることになっております。ただ、やはりそこは、高齢者の方は万が一のことがあってしまうと重症化するということが言われておりますので、そこは丁寧にご案内させていただいて。特養ホームというご指摘がありましたので、お答えいたします。","id":"exchange-126"},{"speaker":"大倉委員","kind":"質問・要望","question":"一方で、例えば今政府のほうでもカラオケとかマージャン、そういったところの施設についても少し懸念がされていて、こういう施設についても、なるべく感染拡大にならないように取り組んでくださいというところでは、健康づくり・生きがい活動事業では、さまざまなシルバーダンスパーティー、いきいき健康マージャン広場、いきいきカラオケ広場などがありますが。","respondent":"吉田保育施設調整担当課長、宮尾高齢者地域支援課長","answer":"それから競技の観戦につきましては、これはやはり何十年に１度しかないものですので、観戦する子どもたちの心の記憶に残るような形で、対応がとれればと考えております。その他、例えば春先、春以降に行っているものにつきましては、慎重に見極めさせていただいて、また別途判断させていただきたいと考えています。いずれにしましても、丁寧なご案内を心がけてまいりたいと考えています。","id":"exchange-127"},{"speaker":"大倉委員","kind":"質問・要望","question":"オリンピック・パラリンピック応援事業ですけれど、どのくらいの子どもたちが参加できるのか教えていただきたいと思います。ご答弁があったらお願いします。高齢者のほうの取り組みはわかりました。中止にしていただいたということで、本当に高齢者は重篤化しやすいというところでは、判断をしていただいてよかったと考えています。ありがとうございました。","respondent":"吉田保育施設調整担当課長","answer":"人数につきましては、予定ですけれども、大体１,５００人ぐらいです。","id":"exchange-128"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、２３１ページ、ヘルプカード作製・配布、２３７ページ、すまいるスクール運営費、２４５ページ、区立保育園運営費、２６５ページ、フードパントリー事業、この４点をお伺いしたいと思います。障害者団体の方からのご要望が反映されたことはとても評価いたします。そうすると、東京都が発行しているヘルプマークをお持ちの方は、カードとマークと二つ、かばんにつけることになるのでしょうか。","respondent":"松山障害者福祉課長","answer":"ただし支援情報等の細かい記載内容につきましては、今後またご意見を伺いながら、どうやったらわかりやすい情報が記載でき、あるいはそれを見た方が、その情報を見てどのような支援をわかりやすくできるのか、提供できるのかについて、ちょっと検討していきたいと思います。","id":"exchange-129"},{"speaker":"こんの委員","kind":"提案","question":"一括して、それぞれを一つのものに収納できる、こうした形状もいいのですが、提案です。これを区の窓口で配布してほしいという声を聞くのですが、私も都に確認をいたしました。ですので、こうした補助金を活用して、利用者の利便性も踏まえて、直接ストラップにヘルプマークが付してあるストラップ、カードが収納できる形状にしてはいかがかと考えるのですが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"委員ご提案の形状のものにつきましては、東京都のほうがやはり権利を持っているところなので、東京都福祉保健局と十分に相談の上、ご利用者の声が反映できるようなものをつくっていきたいと考えています。","id":"exchange-130"},{"speaker":"こんの委員","kind":"確認","question":"ぜひ東京都のほうにも確認していただいて、このマークが直接ストラップにつくほうが、スクラップに両方入れるよりもさらに利便性が高まるかと考えますので、よろしくお願いします。できた暁には、ぜひ障害者福祉課だけでなく、高齢者福祉部門や子育て部門でも配布をする、こうしたことも必要ではないかと考えますが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"今回作成させていただきまして、当事者の声、さまざまな支援が必要な方の声があると思いますので、お声を聞きながら、検討していきたいと考えています。","id":"exchange-131"},{"speaker":"こんの委員","kind":"質問","question":"現状がわかりました。これは大変に有用だと考えております。そこで、文字のみで情報交換をしていた連絡帳から、いわゆる動画とか写真とかを送れるようになるというふうに理解するのですが、そうするとより一層保護者の方に、文字で伝えるお子さんの日常の様子、生活ぶり、成長ぶり、それが動画や写真でも伝えられるようになるというふうに思うのですが、その点の運用はどのようになっていますでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"それから動画等を例えば２分ほどのものを１０人からもらいますと、全部見終わるのに２０分かかってしまうということもありますので、今のところまだ動画等でやりとりというところまでは、検討しておりません。","id":"exchange-132","title":"議員研修会の内容と所要時間"},{"speaker":"こんの委員","kind":"質問","question":"現状は運用していないということですが、ぜひ、この先、文字で先生たちも入力をするところが、動画、写真で一目でわかる、こうしたことのほうが伝えやすい場合もあると思うので、ぜひご検討いただくとありがたいと思います。いわゆる情報漏えい、第三者の侵入、こうしたことが気になりますけれども、セキュリティ対策はどのようになっていますでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"それぞれで、例えば人であれば守秘義務を果たすとか、ソフトであれば安全な動作をするようなものであったり、ネットワークであれば途中を暗号化するとか、そういうようなところを契約上に盛り込みまして、安全な状態を確保して。","id":"exchange-133","title":"議員研修会の内容と所要時間"},{"speaker":"こんの委員","kind":"質問","question":"次にまいります。すまいるスクール運営費でお伺いしたいと思います。所管課の職員の方々にも感謝申し上げます。先ほどもご答弁にありました、午前中勉強会をしたりしているということですけれども、できるだけ濃厚接触にならないように過ごし方を工夫される、そうしたスタッフのご苦労もあるかと思いますが、実態はどのように、午前中、午後を過ごされているのか、簡潔にお答えください。","respondent":"廣田子ども育成課長","answer":"過ごし方といたしましては、午前中に１時間、学習タイムで自習をするであるとか、学校図書館で本を読むであるとか、間を見て校庭、体育館で体を動かすような形で、バランスよく過ごしています。","id":"exchange-134"},{"speaker":"こんの委員","kind":"提案","question":"１日のやりくりは大変にご苦労があるかと思います。これは提案なのですが、一つの案として、いわゆる学習の面で、学習塾などさまざまな民間事業で学習できる環境を提供する動きが広がっております。こうしたものを、教育委員会と協議されて、学校の教室を開放していただき、子どもたちがテレビで学習をする、こうした時間も過ごしてみてはいかがでしょうか。","respondent":"廣田子ども育成課長","answer":"なかなか長期化していく中で学習も大切ですので、今後教育委員会と協議して、検討してまいります。","id":"exchange-135"},{"speaker":"西本委員","kind":"質問","question":"再三言わせていただいておりますけれども、ノウハウの継承ということでは、児童センターの指導員の採用、職員の増員ということは、もう前々から言っておりますが、どういう状況になっておりますでしょうか。それから施設の建て替えが計画されると思うのですけれども、今後全体的な計画はどうなっているでしょうか。","respondent":"廣田子ども育成課長、二ノ宮児童相談所移管担当課長","answer":"今後については、どのような施設をつくっていくかというところを検討した中で、また全体を考えていこうと考えているところです。特にこの部分につきましては、現在の東京都と区とのいわゆる２層構造を解消して区が一元的に対応することによって、組織間連携において生じる連絡・調整のための手続き、意思決定に至るまでの時間的ロスの削減。","id":"exchange-136"},{"speaker":"西本委員","kind":"質問・要望","question":"そういう意味でいうと、どこが主導権を握って、どういうふうにすみ分けをしながらやっていくのか、二重構造になっているのではないかと非常に心配したのですが、その辺はいかがでしょうか。ノウハウを検証しながら継承していただきたいと思いますけれども、人員はどうなのでしょうか。採用人員は増えるのでしょうか。そのままなのでしょうか。ぜひ増やしてほしいのですが、いかがでしょうか。","respondent":"廣田子ども育成課長、二ノ宮児童相談所移管担当課長","answer":"児童センターの機能強化につきましては、今現在、１８歳以上と申し上げましたのは、ひきこもり・不登校等の子で、１８歳を超えても社会自立できないというので。私から、児童相談所関係で１点補足します。先ほどお答えした視点の２番目で、区の対応のサービスを生かし支援を必要とする子どもと家庭を重層的、横断的に支援するとお答えしたところです。","id":"exchange-137"},{"speaker":"西本委員","kind":"質問・要望","question":"ですので、計画的に人数は増やしていっていただきたいと思います。学校に来てみれば、コミュニティ・スクールという形で地域とのつながりをつくる方々もいらっしゃるということになると、本当にその地域の資源を最大限活用して、総合的に１人のお子さんがどういうふうな子どもに育ってほしいかということも、ぜひさまざまな所管課で協力してやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-138"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは国民健康保険について伺いたいと思います。先日の厚生委員会で、２０２０年度の国保料がまた値上げということで条例審査もされまして、私たち共産党は今でも高過ぎる国保料をさらに値上げすることは反対だと、そして引き下げこそすべきということで、条例にも反対をしました。ですから、これから国保料は毎年値上がり続けるわけです。今回の国保料算定の大もとの賦課総額を伺いたいと思うのです。","respondent":"池田国保医療年金課長","answer":"令和２年度の国民健康保険の算定に当たりましての賦課額ですけども、私どものほうでは、賦課額というところでは東京都に納めます納付金額から示させていただいているところでございまして、医療給付費、後期高齢者支援金。","id":"exchange-139"},{"speaker":"石田（ち）委員","kind":"質問","question":"この条例審査のときにいただいた資料には、納付金と保険事業費が賦課総額という枠で囲われているのですね。なので、この１２１億１,０００万円と、保険事業費を合わせたのが賦課総額になると思っていたのですけれども、この１２１億１,０００万円というのが賦課総額ということで考えていいのですか。","respondent":"池田国保医療年金課長","answer":"ということで、基本的には均等割額が３万９,９００円と決まってございまして、それに対しまして保険料率というところで２３区共通の、今回の場合は基礎分が７.１４％、後期高齢者支援金分については２.２９％。","id":"exchange-140"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、区も、国や都には公費の投入を求めています。それなのに区自身が公費投入を、要は法定外繰り入れをなくしていくという計画なのですけれども、平成２２年には３５億９,０００万円の法定外繰り入れをしていました。平成３０年は３億３,０００万円と、区の法定外繰り入れを１０分の１以下に減らしていったということですけれども、こうしたことが保険料の引き上げにつながっているのです。","respondent":"池田国保医療年金課長","answer":"保険料の収入が多くあったですけれども、こちらにつきましては保険料の収納率、こちらが多くあったです。それと繰越金ということにつきましては、平成２９年度から平成３０年度に繰り越したお金を繰入金のほうに戻したということで、やっておるところです。","id":"exchange-141"},{"speaker":"石田（ち）委員","kind":"意見","question":"収納率が９２％あるというのは知っているのですけれど、想定よりも保険料の収入があったということを説明されているのです。ですので、想定していたよりも保険料が集まってきた理由というのをお聞かせください。","respondent":"池田国保医療年金課長","answer":"収納が多くなった理由というのは、まず加入されている方の納付意欲があった、向上されているということで、自主納付が多くなっていたこと、それと私どもの職員の収納に対する努力が実りまして、結局のところ、予想以上の収納があったということだと考えています。","id":"exchange-142"},{"speaker":"石田（ち）委員","kind":"質問","question":"９２％という高い収納率の品川区、２３区でトップです。保険料を納めてもらうために、この間厳しい取り立てや急な差し押さえなどがされて、本当に苦しい声が私たちのところにも寄せられてきましたけれども、今は大分減ってきているのかなと思います。品川区のここ１０年間の滞納処分の執行停止数、この推移を教えてください。","respondent":"池田国保医療年金課長","answer":"私どもとしてはその年、その年で、お支払い困難な方とか、徴収ができないものについては、執行停止ということで処理をしています。","id":"exchange-143"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本当に大変な方には、収納率にもしっかりと反映してきますので、執行停止ということを進めていただきたいと思うのです。区の国保条例にも延滞金の徴収ができるというふうになっているのですけれども、今まではずっと徴収してこなかったと思います。なぜ今回徴収することとしたのか、そして今まで徴収してこなかったのはなぜなのか、伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"なぜ令和２年度から実施をするかについてですけども、これまでも延滞金という条項はございまして、私どものほうでは、いただいてなかったところですけれども、私どもの今の財政状況ですけれども、年々減ってまいります被保険者の数、それから年間総額も。","id":"exchange-144"},{"speaker":"石田（ち）委員","kind":"意見","question":"これからのことはわかりました。ですけれど、なぜ今まで延滞金をとれるのにとってこなかったのか。多分、国保が始まってから７０年間取ってきていないですよね。これからのことはわかったので、なぜ今までとってこなかったのかという理由をもう一度お聞かせください。","respondent":"池田国保医療年金課長","answer":"こちらのほうは未来の話をさせていただいているだけではなく、これまでは被保険者の数も多く、それで保険料のほうで負担ができていたものが、これからますます被保険者が減る、なおかつ医療費のほうも増えていくというところで。","id":"exchange-145"},{"speaker":"石田（ち）委員","kind":"質問","question":"この間、区が入れてきた法定額繰り入れを１０分の１にしても、しっかりと９２％の収納率を上げてきているわけです。ですので、先ほども自主納付が多くなった、職員の努力だということをおっしゃっていましたけれども、引き続きそういう形で進めていけばいいのではないのですか。もう一回、なぜとらなかったのか。区の公費も減らしているのに運営できているわけですから。","respondent":"池田国保医療年金課長","answer":"今までとってこなかった理由というのは、先ほどから言っておりますように、まだ被保険者の数が多かったということ、それから医療費の伸びについても、品川区でいえば、平成３０年度は多少減ったところですけれども、実際に令和に入った段階では。","id":"exchange-146"},{"speaker":"石田（ち）委員","kind":"質問","question":"課長は厚生委員会のときに意識改革という言葉を使いましたけれども、お金で意識改革させるのではなく、今までどおり職員の皆さんと努力して収納していただけるように、それでこれだけ９２％のトップの収納率を上げてきたわけですから、国保財政が厳しくなったというのは、私は理由にならないと思うのです。引き続き聞いていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-147"},{"speaker":"渡部委員","kind":"質問","question":"保育園の待機児のところで幾つか質問をまとめて聞きたいのと、プレイパークを聞きます。よろしくお願いします。ひろまち保育園は、基本的に転園希望者は全員、無事に移れたかどうかが１点目。３点目は、申込書に８園書いている人で不承諾になってしまった人がいるのかどうなのか。わかればでいいです。４点目、最後ですけれど、地域偏差があるではないですか。わかれば教えてください。","respondent":"佐藤保育課長","answer":"認証から認可に行った数に関しては、今のところ押さえておりません。今後分析してまいります。定員割れは、すみません、０、１歳児に関しては、短時間保育等を除くとほとんどない状態ではあるのですけれども、３、４、５歳に関しては一定程度出ているところです。","id":"exchange-148"},{"speaker":"渡部委員","kind":"質問・要望","question":"もう何年もさまざまな手法による待機児解消ということでお願いをしていて、ここ数年はほぼゼロというところで行っているのだと思います。２３３ページ、プレイパークは、荏原という言葉が出てきてとてもうれしくて、どういうお話かというのもあらあら伺ったので、どういうことをやるかというのは承知しているつもりです。よろしくお願いします。お願いいたします。","respondent":"廣田子ども育成課長","answer":"委員ご紹介のとおり、外遊び推進事業という形でやるのですけれども、今回、荏原にプレイパークが欲しいというご意見はたくさんいただいておりますが、今のところ適地が見つからず、戸越公園という候補もあったのですけれども、戸越公園につきましては仮園舎をつくったり。","id":"exchange-149"},{"speaker":"渡部委員","kind":"質問","question":"後で館長などに聞いていくと、彼らに報酬というのでしょうか、何か出ているのだよねと言ったら、何言ってるのですか、無償ですよという話です。中高生にお金を払えるわけがないではないですかということで。これから彼らに、区のその事業でないにせよ、どういうふうに活躍できる場をつくってあげるかというのも、児童センターの仕事かもしれないし、ややもすると、それを超えた力になると思うのですよね。","respondent":"廣田子ども育成課長","answer":"そんな壮大な建物ができるかどうか、すぐにはできないと思うのですが、今後の課題として取り組んでいきたいと考えています。","id":"exchange-150"},{"speaker":"渡部委員","kind":"質問・要望","question":"というのは、ある程度人と接することが好きな人、面倒を見てあげようと思える子たちであるわけですから、そこで何か登録制かなにかにしておいて、例えば音楽だけでなくても、ちょっと体を動かすであったとしても、それはそれでさまざまなお手伝いが入ってくると思うのですけれど、ここまで児童センターの中での活動がいい方向で動いているので、ぜひ何か、中高生版ボランティアセンターの設立だったり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-151"},{"speaker":"本多委員","kind":"質問・要望","question":"２４７ページ、区立保育園の改築について、そして民営化について伺います。初めに改築について伺います。プレス発表資料の４７ページに、区立保育園の改築には、老朽度、改修履歴、併設施設等を考慮とありますが、全体の計画を進めていく中で、安全重視で老朽度を最優先に進めるべきと考えますが、その点につきまして教えてください。その辺の全体の中の進め方を教えてください。","respondent":"吉田保育施設調整担当課長","answer":"そこに３階建てぐらいの建物が建つのですけども、それだけの土地を確保するというのはなかなか難しいところがあります。公園等で一部使えるようなところは、今回このような形で三ツ木保育園の建て替えにも使いますが、なかなかそのような土地を確保するのは難しいところです。","id":"exchange-152"},{"speaker":"本多委員","kind":"質問・要望","question":"保育園の場合は学校と違って敷地面積が小さいので、本当に敷地内では厳しくて、代替地を探すとどうしても公共の土地を探すことになると思います。いろいろ工夫が多いかと思いますけれども、いろいろ注意して選定していっていただきたいと思います。民営化について伺います。この予算のプレス発表資料のところで、民営化調査検討経費２５３万円について、内容を教えてください。","respondent":"吉田保育施設調整担当課長","answer":"その業者と、民営化のガイドラインを作成しまして、それは３月中に公表できると思います。その業者と今度４月から、令和３年４月の三ツ木保育園の公設民営化に向けて、その際の支援を行っていただきます。","id":"exchange-153"},{"speaker":"本多委員","kind":"質問","question":"民営化のメリットにつきまして、サービス向上というと本当に広くいろいろ入ります。時間的にもサービス向上、それと運営費の負担軽減、受け入れ児童数の増、区職員定数減など、公設民営となるメリットの情報を広める周知を図る必要性について、それと既存の公設民営の検証を広める点について、既存の公設民営のサービスや運営についてですけども、そういったところについてはいかがでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"公設民営にするということ自体は、民にできるところは民でサービスをお願いしたいということと、区の保育園だと一律な方法になりますけれども、民間事業者が持つノウハウとか、サービス向上とかが見込まれるものと考えております。","id":"exchange-154"},{"speaker":"本多委員","kind":"質問・要望","question":"既存につきましてはわかりました。令和３年度から始まる内容については、広く状況をお知らせする必要があるかと思いますので、質問しました。このような、民間委託を進めた後、区民の皆様に状況をお知らせするというのが大事だと思いますので、ぜひ、そうしていただきたいと思いますが、どのようなイメージか教えてください。","respondent":"吉田保育施設調整担当課長","answer":"委員ご指摘のとおり、民営化した際、民営化するに当たりましても、実際にそこの園の利用者等の声を聞きながら進めていくとともに、実際、民営化してもサービスの低下がないような形で、区も監視、調整していくことで、第三者評価においても高い評価となることを目指して。","id":"exchange-155"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"こちらは定員が６名、当初受け入れは３名ということでスタートしましたが、登録は１２名で、延べの利用者は、伺ったところ２月は２６名ということ、１日に１名いらっしゃるかどうかというところで、利用の状況が大変少ない。そして改善、これはまさか利用の抑制ということではないと思うのですが、支援サービス拡充、そして受け入れ体制の整備のお考えはいかがでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"以上、状況についてですけれども、今後の見通し等につきましては、当然、障害児者総合支援施設につきましては、地域の障害者の生活を支える、地域生活支援拠点として整備したものですので、より多くの方にご利用いただくよう、運営法人等と協力しながら。","id":"exchange-156"},{"speaker":"高橋（し）委員","kind":"質問","question":"もちろん私も指定管理の議案を議決した議会の一員として責任を感じていますけれども、平成３４年９月３０日まで待たずに、この施設の指定管理の対象を再検討するべきではないかと思います。そのためのプロジェクトをつくり、あるいは体制管理をしていく。例のひろまち保育園の、あれは委託ですけれども途中で解約したこともありますが、その点についてはいかがでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"次の体制につきましては、現在検討しています。","id":"exchange-157"},{"speaker":"須貝委員","kind":"質問","question":"私は、２４４ページ、児童福祉費と、その保育園についてお聞きします。そして２１２ページ、高齢者福祉費についてお聞きしたいと思います。このままでは、保育士が倒れるとも言われていますが、区立保育園や区内の私立保育園の状況を教えてください。保育士はかなり忙しいようですが、人数は足りているのでしょうか。そして、マスクと消毒液は当面、十分あるのでしょうか。教えてください。","respondent":"佐藤保育課長、吉田保育施設調整担当課長","answer":"２点目の保育士の数に関しましては、大まかな数字なのですけれども、正規が大体８００人、非常勤が７００人と、計１,５００人も公立保育園のほうには配置しておりますので、先ほど言った関係もありますが、十分対応できているです。区立保育園におけるマスクと消毒液の件ですけれども、２月の頭に各園へ、１箱５０枚入のマスクを１０箱、消毒液１ｌ入りのものを各２個、配置しております。","id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"今、課長からご答弁いただいたのですが、区立保育園はわかります。ですが、この品川区は区立だけではないですよね。民間の保育園によっても支えられております。民間の状況ももちろん把握されていると思うのですが、その辺の人材等に関して、どうなのでしょうか。教えてください。","respondent":"大澤保育支援課長","answer":"それによって、少し休む方ですとか、あと時間を短縮して利用されている方がいるということで、今、保育士の人数としては問題なく運営ができております。マスクや消毒液等についても、現時点で不足しているという園の情報は入ってきておりません。","id":"exchange-159"},{"speaker":"須貝委員","kind":"質問","question":"保育所などで職員や園児が感染した場合、臨時休園するようになっていますが、区内の全ての保育園が同様なのでしょうか。教えてください。そして、実際に休園しなければいけない場合には、何日ぐらい休園するのか、教えてください。","respondent":"佐藤保育課長","answer":"基本的に２週間以上を考えております。一方、発症していない場合、自宅療養して、その後陽性になった場合に関しましては、東京都や保健所と状況を確認して、休園するか、しないかを判断するです。","id":"exchange-160"},{"speaker":"須貝委員","kind":"質問","question":"なぜお話しするかというと、中小零細企業で働いている方にとっては子どもの預け先がないため、長期間にわたって会社を休まなければいけないことになります。ですから、勤めている方も会社を辞めざるを得ないという状況があります。ならば、臨時休園にならないように、最大限のウイルス感染防止対策を、私はこの品川区でしているのかと思うのですが、その辺について対応策を教えてください。","respondent":"佐藤保育課長","answer":"新型コロナウイルス感染症に関する対応策ですが、これまで保育園のほうでは園内の消毒、手洗い、うがいというのを常に徹底していますが、国からもその予防が一番大事だというところもありますので、私立も含めて再三各園に周知をして、今のところそれが徹底しているので。","id":"exchange-161"},{"speaker":"須貝委員","kind":"質問","question":"そういうところの対応というのはどうされているのですか。１ｍ以上離れて暮らせなどというのは、まず不可能ですよね。そうすると、本当に条件的には密閉空間で濃厚接触をするわけですから、私は大変危険な状況に子どもたちが置かれていると思うのですが、それにしては手洗い、うがいだけで済むのでしょうか。そして、検温というのをどのようにやっていらっしゃるのか、教えてください。","respondent":"佐藤保育課長","answer":"１点目の児童の健康管理ですが、こちらに関しましてもこれまで徹底していますが、保護者向けに２月上旬に２回、あと下旬に２回、新型コロナウイルス感染症の対策に関しまして、児童の健康管理と保育園へのご連絡、検温も含めて徹底をお願いしますといった対応をしておりますので。","id":"exchange-162"},{"speaker":"須貝委員","kind":"質問","question":"検温というのは、親御さんが持ってきたその状態だけなのですか。園内では、測るということはしていないということでしょうか。今、非常時ですよね。平時ではないですよね。それだけでいいのですか。お子さんの安全というのを、それだけできっちり守れると言い切れるのですか。何か足りないのではないですか。もう一度お答えください。","respondent":"佐藤保育課長","answer":"当然保育園でお子さんの状況を常に確認しておりますので、体調が悪い場合は随時、検温をしておりまして、３７度５分を超えた場合は保護者にご連絡して、お迎えに来ていただくという運用を徹底しています。","id":"exchange-163"},{"speaker":"須貝委員","kind":"質問","question":"保育園と一緒です。中には小学校の休校により職員の出勤が困難な方もいるため、人員不足の影響もあるようですが、訪問介護を含めて、品川区内の区立や民間の介護施設ではどうなのでしょうか。こういうふうなことがあるのでしょうか。教えてください。マスクや消毒薬などは十分にあるのでしょうか。教えてください。そして、職員不足の施設やサービスはあるのでしょうか。民間も含めて教えてください。","respondent":"寺嶋高齢者福祉課長","answer":"それからマスク等につきましては、今月中旬までは不足はないのですけれども、それ以降につきましては少しずつ不足が発生するという情報もありますので、これは庁内会議等で情報提供して、対応を検討している最中です。","id":"exchange-164"},{"speaker":"須貝委員","kind":"質問","question":"保育園も介護施設もそうですが、介護の場合はヘルパーがもし病気をしてしまったら、発症してしまったら、そこの施設は使えないのですよね。それは一体どうするのですか。私はそれが大きな問題だと思うのです。保育施設もそうですけれど、保育士がかかってしまったら。大勢の子と接触しているわけです。そうしたら当然、長く閉園になる。ぜひそういうところの対応をしっかりやってください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-165"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私からは、２２３ページからの障害者福祉費、そして２２９ページの高次脳機能障害、２２７ページの障害者の緊急通報システム、４７４ページの後期高齢者医療について、伺いたいと思います。そういう要望にも応えられるのか、伺いたいと思います。特別支援学校も含めて、小中高に通学する医療的ケア児の人数は、それぞれ何人なのかについても伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"ただし特別支援学校のほうでも午前中からお預かりするということで、福祉の支援体制が整うまでの間、特別支援学校でお預かりするというような体制をとっていただきまして、教育のほうと連携いたしまして対応しています。","id":"exchange-166"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"拡大の方向でぜひ取り組んでいただきたいと思うのですが、いかがでしょうか。重度の方の世帯は、それだけでもお金がかかりますし、また共働きができないという状況もあると思いますので、ぜひこの場合、住民税非課税世帯は無料ということにしていただきたいと思うのですけれど、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"緊急通報システムに重度の方が適用できないかですけれども、対象者の中には、下肢または体幹機能障害１級から３級と、内部障害の方も１級から３級という形で対象となっておりますので、その方の状態によっては対象となるか、ならないかというのが。","id":"exchange-167"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから高次脳機能障害のほうに移らせていただきたいと思います。例えば広報で、高次脳機能障害をご存じですか、お気軽にご相談くださいというようなことでお知らせをするとか、また、これは委員長にも断っているのですけれど、品川区がリーフレットをつくられていると思うのですが、これがどのように活用されているかということについてもお聞かせください。","respondent":"松山障害者福祉課長","answer":"先ほどの緊急通報システムの件につきましては、継続して、また今後も検討してまいります。２点目の高次脳機能障害につきましては、専門の相談員が２名いらっしゃいます。その２名が交代で週に１日勤務となっております。","id":"exchange-168"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひよろしくお願いしたいと思います。品川区でもぜひ高次脳機能障害者支援センターをつくって、支援の充実をしていただきたいと思うのですが、いかがでしょうか。高次脳機能障害専門のデイサービスや自立訓練、就労Ｂについても必要ではないかと思うのですが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"品川区内では、心身障害者福祉会館がその機能を担っているものです。高次脳機能障害の方につきましては、数の把握が非常に難しいということと、心身障害者福祉会館で行っている自立訓練の生活訓練の中で、高次脳機能障害の方をお受けしている状態です。","id":"exchange-169"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私は、２１１ページの成年後見制度利用促進基本計画策定について伺いたいと思います。この利用促進基本計画の策定に当たっては、権利擁護支援のための地域連携ネットワークづくり、またそうしたネットワークを運営していくための中核となる、中核機関の設置等が求められておりますけれど、これについての考え方をお知らせください。","respondent":"大串福祉計画課長","answer":"これまでの成年後見センターの取り組み、あるいは私ども区と社協で築き上げてきた関係性、これが基本的にはネットワークの中心になってこようかと思いますし、また、社協と区との連携関係をどういう形で発展させていくかというところになろうかと思いますけれども。","id":"exchange-170"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そうした中で、そういったお考えについて、またもう一回お答えいただきたいとともに、私は市民後見の活動をされている市民後見人の方からお話を伺う機会がありまして、これから市民後見人の役割が増えていく中で、財産がある方ばかりではなくて、生活保護も含めて資産がない方が、さまざまな権利擁護のために後見人を利用するに当たって、その報酬は家庭裁判所が決定するわけですけれども。","respondent":"大串福祉計画課長","answer":"それだけではなく、後見活動そのものに対しての区からの支援、これは今現在も行っているところですけれども、今後こういった後見活動が増えていくことを踏まえて、この辺につきましても計画策定の中で社協と役割分担といいますか。","id":"exchange-171"},{"speaker":"たけうち委員","kind":"質問・要望","question":"ご存じのとおり、この促進法策定に当たっても、品川区の社協はじめ、さまざまな方が率先して取り組んで、厚生労働省等でいろいろなバックアップをする中で法律ができた、まさに品川区が推進してきた中で、全自治体が品川区の取り組みを注視していると思います。要望として終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-172"},{"speaker":"大沢委員","kind":"質問","question":"お願いします。２１９ページ、外出習慣化事業と、それから派生した社会保障について聞きます。外出習慣化事業ですけれども、高齢の方がひきこもりがちだということを防止するために、この事業が行われているのですけれど、現状を教えてください。","respondent":"宮尾高齢者地域支援課長","answer":"さらに今年度からは、歯科衛生士等による口腔機能向上プログラム、これを各期１回ずつ実施させていただいているところです。ちなみにこちらの事業は、現在４会場にて実施しています。","id":"exchange-173"},{"speaker":"大沢委員","kind":"質問","question":"これは今、大体、引きこもりがちの方はどれぐらいいらっしゃるのですか。","respondent":"宮尾高齢者地域支援課長","answer":"こちらは各会場とも定員が９名ということで、掛ける４会場で３６人。各会場とも２期、実施させていただいているという状況です。","id":"exchange-174"},{"speaker":"大沢委員","kind":"質問","question":"見えてこない数字で、高齢の方で引きこもっている方が、都の調査、国の調査でも数字等、漏れ聞こえてくるのですけれども、品川区の現状は、把握しづらいところは十分にわかりますけれども、どのように現状を捉えていらっしゃるのか、想像していらっしゃるのか、教えてください。","respondent":"宮尾高齢者地域支援課長","answer":"確かに委員おっしゃったように、細かい人数等の調査分析というのはなかなか、まだできていない部分があるのですけれども、私どもでやらせていただいているのが、７５歳以上のご高齢の方で、例えば現時点で介護サービス等につながっていない方を対象に。","id":"exchange-175"},{"speaker":"大沢委員","kind":"質問","question":"７５歳ということですけれども、繰り返し私のほうで申し上げますが、２０２５年、団塊の世代の方が全て７５歳を超えるということになると、いろいろ複雑な問題等々、デリケートな年代の方たちですから、増えてくるのは予想できるのですけれども、２０２５年、団塊の世代の方が高齢を迎えた場合、この事業あるいは事業に対する見立てというか見通しをどのようにやっていこうと思われていらっしゃいますか。","respondent":"宮尾高齢者地域支援課長","answer":"確かに委員おっしゃるとおり、これから当面高齢化は進むというふうに、我々は想定、認識をしております。そういう中で、やはり事業の、例えば定員の拡充であったり、コース数を増やすですとか、できる限りの対策はとっていきたいと考えています。","id":"exchange-176"},{"speaker":"大沢委員","kind":"質問","question":"どう見ても今のところ、ご存じのようにこういう世相でありまして、それが十分に機能していないような感じがします。ましてや昨今の経済状況、社会状況によると、２０２５年についてはそこの部分が機能しない、あるいは機能不全、完全に機能しないような状況に陥るのではないかと私は見立てていますけれども、どのようにお考えでしょうか。","respondent":"宮尾高齢者地域支援課長","answer":"確かに心配すべきというか憂慮すべき点はありますけれども、我々としてはそこを見据えて、そうならないように、いろいろな手立てを打って介護予防等含めて、充実を図ってまいりたいと考えています。","id":"exchange-177"},{"speaker":"大沢委員","kind":"意見","question":"社会的包摂という言葉があります。インクルーシブという言葉をせお委員も発しておりますが、その中で、社会保障においても、対象者を限定しない社会保障をつかさどる政策というのが、私は必要であると思います。ちょっと直しますけれども…、終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-178"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は５４０ページ、地域包括ケアシステムのことについて伺います。だから、皆さんがこれを進めていくときに一つお聞きしたいのは、統合していかないと、ということをどう捉えているのかと考えています。今、頑張っていらっしゃるのはわかるのですけれども、そこら辺の考え方を教えていただきたい。これは受け皿づくりが求められていて、出口戦略が必要だということであります。","respondent":"大串福祉計画課長","answer":"そうした中で、また精神病院等々のお話も出していただきました。なかなかその辺の病院の運営、あるいは開設といったところで、区が関与できる領域はなかなか難しいと考えています。空き家活用といったご提言もいただいたところです。","id":"exchange-179"},{"speaker":"石田（秀）委員","kind":"意見","question":"まさにその包括というのは曖昧な言葉だと思っておりまして、いろいろ読めば読むほど曖昧だと思うようになってきて。品川区民の方々のそういう部分をしっかりと捉えて、そういうところとも話していけるような形、品川モデルというのをぜひそこでつくっていただくことで、逆にコストも下がってくると思っているので、そこら辺のところをぜひお願いだけして、終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-180"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/384106?Template=document&Id=1114#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":127412,"voices":410}},{"id":"r02-20200310-3","meetingId":"r02-c-budget","date":"2020年3月10日","dateIso":"2020-03-10","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を163件抜き出しています。","topics":[{"id":"topic-01","title":"行う委員の質問を先行して行い、該当の質問が終わり次第、品川区保健所長をはじめとした関係理事者には退席していただくこととしましたので、ご了承願います。 それでは","agenda":"行う委員の質問を先行して行い、該当の質問が終わり次第、品川区保健所長をはじめとした関係理事者には退席していただくこととしましたので、ご了承願います。 それでは","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"おはようあります。よろしくお願いします。私からは、２７５ページの各種がん検診について、２８５ページ、オリンピック・パラリンピック開催期間中の回収対応について、また、２９３ページ、中小企業経営支援事業費についてお伺いいたします。各種がん検診についてです。国が指定しますがん検診、とりわけその１つです胃がん検診についてお聞きいたします。理由を教えてください。","respondent":"高山健康課長","answer":"平成３０年６月から胃がん内視鏡検診を導入いたしまして、現在は委員ご案内のとおり、胃がん内視鏡検診、そしてバリウム検診、それから胃がんリスク検診という３つで検診を用意しているところなのですが、現下の状況、胃がん内視鏡検診が順調に伸びているということをもちまして。","id":"exchange-001"},{"speaker":"小芝委員","kind":"質問・要望","question":"前回の決算特別委員会では、口腔がん検診を行っています区内の歯科医院のリストをほかのがん検診の案内に載せていただきたいなど、歯科医師会が主体となって行っております口腔がん検診への積極的な姿勢をお願いしましたところ、課長答弁では、時期尚早か実行すべきか慎重に判断されるという答弁をいただきました。歯科医師会への取り組みも含めて教えていただきたいと思います。","respondent":"高山健康課長","answer":"口腔がん検診につきましては、地元の歯科医師会の取り組みとして、地元の歯科医師のスキルアップに資するということで、その取り組みは私どもとしましても応援したい立場にありますので、来年度におきましては。","id":"exchange-002"},{"speaker":"小芝委員","kind":"質問","question":"２８５ページのオリンピック・パラリンピック開催期間中の回収対応についてお伺いします。オリンピック・パラリンピック推進特別委員会でも質問させてもらったのですが、競技場周辺で行っているボランティアの清掃活動を行政が支援することはできないものなのでしょうか。ぜひ「しな助」としての清掃活動をご支援いただければと思いますが、検討されていますでしょうか。","respondent":"工藤品川区清掃事務所長","answer":"やはりラストマイルというところ、立会川駅の周辺ですが、内容といたしましては、立会川駅周辺につきまして、大会期間中は日曜収集を実施しまして、気持ちのいい清潔な町をつくり出すところが１つです。","id":"exchange-003"},{"speaker":"小芝委員","kind":"質問","question":"中小企業経営支援事業費についてお伺いいたします。大井町のとある飲食店で話を聞けば、前年度比４割減との話も伺っております。品川区中小企業事業融資あっ旋「経営変化対策資金」の制度ですが、急な事案に対しての予算であると思うのですが、こちらの財源は中小企業資金融資あっせんの６億９,２４６万７,０００円なのでしょうか。教えてください。","respondent":"山崎商業・ものづくり課長","answer":"財源につきましては、委員お示しの中小企業資金融資あっせんの予算の中でです。","id":"exchange-004"},{"speaker":"小芝委員","kind":"質問・要望","question":"ちなみに、今日に至るまでの相談件数がもしわかれば教えていただきたいのと、あと、相談に来た事業者の中でどういった業種が多いのかなど、その特徴も教えていただけますでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"今回の新型コロナウイルス感染症対策という観点では、もう１００を超える相談を受けております。業種につきましては、委員お示しのございました飲食業ですとか、宿泊関係、それからタクシーの自営の方などが多いかということが１つの特徴です。","id":"exchange-005"},{"speaker":"小芝委員","kind":"質問・要望","question":"今後とも、ちまたの飲食店、中小企業の皆様が、国難ともいうべき新型コロナウイルス感染症の影響を極力最小限に抑え乗り切ってもらえるよう、区としても積極的な支援をお願いいたします。こちらは要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"せお委員","kind":"質問・要望","question":"私からは、２７３ページ、乳児健康診査、２８５ページ、ワンウェイ（使い捨て）プラスチック削減推進、２８７ページ、リサイクル活動支援事業、２７１ページ、受動喫煙防止対策費についてお聞きします。子どもへの感染症対策は難しいことも多いですので、できる範囲でやっていただきたいとは思うのですが、先週からほかの委員からも質問がありますので、まずは、簡単にで結構です。","respondent":"仁平品川保健センター所長","answer":"実際に健診中ですけれども、ふだんより換気に努めているところです。健診に際しまして、集団指導があるのですけれども、こちらは簡略化、資料のお渡しなど簡略化して、健診の総時間の短縮化に努めているようなところです。","id":"exchange-007"},{"speaker":"せお委員","kind":"質問","question":"古いものを新しいものに変えたり、なくしたりするだけでも清潔になりますし、見やすくもなります。掲示物や案内表示などの見直しや清掃は、時期などを決めて定期的にやっていたりしますでしょうか。そちら、何かあればお聞かせください。","respondent":"仁平品川保健センター所長","answer":"区では全庁的にイメージアップ運動をしていますので、１２月には一斉に館内を点検している、そういう状況です。ふだんから子どもが来たりして掲示物等が破れたりしますので、その辺は適宜交換する等して、今後とも見やすい掲示物、案内に努めてまいりたいと考えております。","id":"exchange-008"},{"speaker":"せお委員","kind":"質問","question":"会場全体を清潔に保っていただくだけでも感染症対策になりますので、引き続き、お願いいたします。次に、乳児健診における発達障害の早期発見に関してです。現状、健診において発達障害が疑われる事例において、どのような対応がなされていて、紹介機関は決まっていたりするのでしょうか。お聞かせください。","respondent":"仁平品川保健センター所長","answer":"その中でどうしてもこれはちょっと次の機関につないだほうがいいというのは保護者の考え方もありますので難しいところではあるのですけれども、その辺は保護者に寄り添いながら、区としまして次の機関につないだほうがいいといった場合には。","id":"exchange-009"},{"speaker":"せお委員","kind":"質問","question":"ただ早期と言っても、早期であるほど不確実なことも多くて、発達障害児の特徴には、定型発達の子どもにも見られるものもあるそうです。発達障害という言葉が先行してしまった部分もあるかと感じます。そして、保護者の考え方だったり、知識も重要になってくると思いますが、保健センターなどにおいて、発達障害の正しい知識を得られる講演会などを行うといった機会はありますでしょうか。お聞かせください。","respondent":"仁平品川保健センター所長","answer":"現在、保健センターにおきましては、発達障害関係の講演会は、企画も、実施したこともございません。","id":"exchange-010"},{"speaker":"せお委員","kind":"質問・要望","question":"ワンウェイプラスチック削減ももちろんすごくよい取り組みで、新しい事業ですので、積極的に行っていただきたいと思っています。ただ、品川区においては、もっと広く環境問題に取り組んでいただきたいと考えています。この結果には私も驚きました。そこで、人工芝の対策も取り組んでいただきたいところですが、人工芝については学校での整備が多かったりしますので、教育費のほうで質問します。","respondent":"小林環境課長","answer":"プラスチック削減に対するお問い合わせです。区として使用をなくしていく、減らしていく取り組みとしましては、今年度、来年度事業の中で新たに新規事業としまして、各種イベント等で使用します使い捨て容器類をプラスチック以外のものに変更することを進めていくところです。","id":"exchange-011"},{"speaker":"せお委員","kind":"意見","question":"マイボトル用の自動販売機なども開発されていますので、品川区の施設、まずは庁舎などにおいて、試験的にマイボトル・マイカップ用の自動販売機を設置して、ペットボトルを売っている自販機を減らしていく方向で取り組まれてはいかがかと思いますが、見解をお聞かせください。","respondent":"小林環境課長","answer":"そういったところは引き続き動向を注視しまして、また職員に対するマイボトルの積極的活用の周知について、区として可能な取り組みは引き続き研究してまいりたいというふうに考えているところです。","id":"exchange-012"},{"speaker":"せお委員","kind":"質問","question":"ぜひ検討をお願いいたします。次に、プラスチックごみを再生利用するということですが、予算書にリサイクル活動支援事業とありますが、これはどのような事業でしょうか。お聞かせください。","respondent":"工藤品川区清掃事務所長","answer":"リサイクル活動支援事業の内容です。こちらは、集団回収事業といいまして、集団回収団体の活動が活性化するような支援をしています。","id":"exchange-013"},{"speaker":"せお委員","kind":"意見","question":"一方で、神奈川県では、かながわプラごみゼロ宣言をして、リサイクルされない廃棄されてしまうプラごみゼロを目指していると聞いています。品川区をはじめ２３区などがそのような宣言をしてもいいかとは思っています。このワンウェイプラスチック削減のほかに、今後、検討している取り組みなどがありましたら、お知らせください。","respondent":"工藤品川区清掃事務所長","answer":"清掃事務所といたしましては、ごみの組成、排出されているごみの組成分析をした結果、やはりまだまだプラスチックはしっかりとリサイクルに回されていないという実情もありますので、そういったところをなるべく資源にしていただくということと、冒頭申しましたように。","id":"exchange-014"},{"speaker":"せお委員","kind":"意見","question":"今後も取り組みをぜひお願いしたいと思います。次に、受動喫煙防止対策費です。日本では、受動喫煙による年間の死亡者数は推定で１万５,０００人と言われております。そこで、４月１日から改正健康増進法と東京都受動喫煙防止条例が全面施行されるにあたって、区として受動喫煙防止対策事業をどのように進めていくか、事業内容の説明とあわせてお聞かせください。","respondent":"高山健康課長","answer":"来年度に関しましては、そうした送付しましたシールがきちんと貼られているかということを改めて店頭の確認をするほか、講習会の開催、そして４月からの全面施行に伴いまして、さまざま指導でありますとか助言、勧告、命令などの取り締まりが始まりますので。","id":"exchange-015"},{"speaker":"せお委員","kind":"質問","question":"世界的に見て、ＷＨＯは日本の受動喫煙対策を４段階評価の最低レベルと評価していまして、まだまだ対策が不十分であると考えられます。ニコチンは交感神経を刺激して血液を急激に上昇させます。こういった動脈硬化とかが進行して、心筋梗塞や脳卒中などの発症リスクも高まりますが、区として目標をもって受動喫煙対策に取り組むべきと考えますが、その点はいかがでしょうか。","respondent":"高山健康課長","answer":"区では、健康増進計画ということで、しながわ健康プラン２１を、今年度、中間評価見直しということで改定いたします。そして、その中でたばこ対策ということを重点的な目標と定めまして、数値目標を立てて取り組んでまいります。","id":"exchange-016"},{"speaker":"つる委員","kind":"提案","question":"２７３ページ、母子保健指導事業費、多胎児支援「とうきょうママパパ応援事業」の活用について伺っていきます。それから２７７ページ、こころの健康づくり事業については、摂食障害について、２７５ページ、予防接種費については、小児がんなどの治療で免疫を失った子どもの定期予防接種の再接種の費用助成について伺っていきたいと思います。これは歳入でも確認をさせていただきました。","respondent":"仁平品川保健センター所長","answer":"母子保健法一部改正に伴う対応と今後の区の施策の考え方、それと対象の範囲という形になるかと思います。産後、産まれてから１歳ぐらいまでの小さい時期の支援は非常に重要になってまいります。","id":"exchange-017"},{"speaker":"つる委員","kind":"質問・要望","question":"いずれにしても法律が改正された、また運営要綱が見直された暁には、しっかりとそれを確認いただいて、厚労省側からも各自治体にしっかりと丁寧な説明をするとしておりますので、そうした詳細をしっかりと確認いただいて、品川区の各施策に生かしていただきたいというふうに思っております。ここについては、しっかりと注視をしていきたいと考えております。これについてお答えをお願いします。","respondent":"仁平品川保健センター所長","answer":"「とうきょうママパパ応援事業」の活用についてですけれども、本来ですと、３月ぐらいに東京都の補助金説明会があるのですけれども、こちらが新型コロナウイルス感染症の関係で中止になっており、まだ詳細が入ってきていないところです。","id":"exchange-018"},{"speaker":"つる委員","kind":"質問","question":"ぜひ積極的な活用をよろしくお願いしたいと思います。次に、こころの健康づくり事業に関連して、摂食障害について伺っていきたいと思います。品川区は、これまでこころの健康づくり事業の中でそうした方も含めご対応いただいていると思いますけれども、まず、この摂食障害に対する区の取り組みについてお知らせください。","respondent":"榎本荏原保健センター所長","answer":"摂食障害についての取り組みですが、摂食障害につきましては、神経性の痩せ症とか過食症などの症状があらわれる病気です。","id":"exchange-019"},{"speaker":"つる委員","kind":"質問","question":"過日、国会でも公明党の議員からの質問に対して、厚生労働副大臣からも、まず啓発活動が大変重要であるという認識が示されたところであります。いずれにしても、さまざまな課題に対応いただいている中で、こうしたマゼンタリボン運動というものがありますけれども、国としてもそうした啓発活動との連携が今模索されている中ですが、区として、このあたりについての取り組みの考え方をお知らせください。","respondent":"榎本荏原保健センター所長","answer":"年に１回、広報におきましても大きな紙面をいただきまして、気軽にご相談できるような周知・啓発活動を行っております。今後はこの摂食障害についても、より早い段階でご相談や治療ができたほうがいいことも多いと思いますので、一層力を入れていきたいと思います。","id":"exchange-020"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひこのマゼンタリボン運動との連携も含めて、ご検討、推進いただきたいと考えております。最後に、時間があるので、予防接種費についてです。小児がんなどの治療で免疫を失った子どもの定期予防接種の再接種の費用助成について、何度も確認をしていますが、現状を教えてください。","respondent":"鷹箸保健予防課長","answer":"なかなか対象者の限定ですとか、接種方法について難しい問題があって時間をいただいておりましたけれども、年度末までにはしっかり対応が可能になるように、今、進めております。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"２８１ページ、環境保全事業にかかわって、住宅の騒音問題、それと、２７９ページ、住宅宿泊事業届出等事務費にかかわって、旅館業条例について伺います。この物件は、写真にあるように、お隣の住宅との距離がほとんどないのです。２０cmぐらいでしょうか。伺いたいのですけれども、条例改正後に開業したこのような常駐者がいない、フロントがない旅館・ホテルは何件ぐらいなのか教えてください。","respondent":"鈴木生活衛生課長","answer":"法改正後、申請のあった旅館についてのお尋ねですが、旅館については、一昨年の法改正後増えた件数について、１０数件というふうに記憶をしております。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"私は、この写真のケースですけれども、住民の方の不安も伺いましたので、この場所とか地域性とかをみれば、設備からいって、住民の不安も当然だなと思いました。伺いますけれども、品川区としては、この事業者、所有者と住民の話し合いを進めて、双方が納得するまで許可を待つべきだと思うのですけれども、いかがでしょうか。","respondent":"鈴木生活衛生課長","answer":"今回お尋ねの北品川の件に限らず、旅館業の申請が出た時点で、近隣の住民の方から不安の声やさまざまな意見をいただいた場合には、保健所のほうから事業者にお伝えして、説明会を開いたり、個別の対応をするなりということで。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"そのように義務づけはなくても、保健所から説明会を開くことを含めてやってくださいと要請をしているというのは、それはいいのですけれども、私が伺ったのは、その話し合いをある程度、双方が納得するまできちんと話し合ってもらうということに品川区はある程度責任を持つべきだと思うのです。双方が納得するまで許可は待つべきだと思いますが、いかがでしょうかと伺ったのでお答えください。","respondent":"鈴木生活衛生課長","answer":"できるだけ地域において円滑な営業活動、また近隣への影響を抑えるということでの指導をしているところでございまして、その住民の方全員の納得が得られるまで許可を出さないということは、権限的にも無理ですし、現実的には、全員が何も意見。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"全員というか、ある程度、とは言っても、地域の中で営業するわけですから、やっぱり一定の理解が絶対にない限り、私は開業していいのかという思いがあります。少なくとも理解が全く得られない状況のままで許可を出すということは違うのではないですかと言っているのです。許可を少し待ってもらうということはできるのではないですか。いかがでしょうか。","respondent":"鈴木生活衛生課長","answer":"先ほど申し上げましたように、法令等の定めに従って手続をして、保健所としては主に衛生面、環境面の確認といった法に定めたものを行っておりますが、それを必要以上に住民の方の合意がないということで引き延ばすということは、法的にはできないというふうに考えております。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"実際、頻発している面もあると思うのですけれども、設置場所とか常駐者の義務づけなど、どこまでやるのかはあるのですけれども、必要な規制を強化する条例改正が必要なのではないでしょうか。伺いますけれども、区はなぜ法の規定を超えて必要な規制を行う考えがないのか伺います。住民の不安に寄り添った一定の規制をかける条例改正は必要だと思うのですけれども、いかがでしょうか。","respondent":"鈴木生活衛生課長","answer":"委員のご指摘にもありましたように、法の趣旨、またその規制に合わせた条例での規制、対応ということで、区は条例改正をしたところです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"その品川区の判断が私は疑問なのです。ですから、私は、宿泊者にとっても地域にとっても、必要な規制は大事だと思います。時間がないので次にいきます。委員長に許可を得ましたので、写真を表示するのですが、まず、こちらです。土日祝日関係なく、３６５日営業は行われていて、元日でもやっていたというのです。今回、このケースに適用されるものはないのか伺いたいと思います。","respondent":"小林環境課長","answer":"道路上で発生していますと、それは所管する警察あるいは国が対応するです。もし敷地内で何か規制対象になるかですと、まずはこの施設が工場とか指定作業所に該当するかどうか、そういうところがまずは１つの視点かと思ってあります。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"区としては、要請レベルではいろいろ要請すると思うのですけれども、少なくとも広い通り、八ツ山通りに出てからエンジンをかけるとか、あるいは営業時間の見直しですとか、そういった具体的な要請をしていただきたいと思うのですけれども、どのようなお願いをしているのでしょうか。その結果、どう確認しているのか伺いたいと思います。","respondent":"小林環境課長","answer":"本件ですが、過去に環境課のほうにそういった相談があって対応したことは把握しています。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"ですから、健康づくり支援というのは積極的に進めるべきかと考えています。続けていきます。これもＳＤＧｓの目標１３、気候変動に具体的対策を、そもそも環境保護がＳＤＧｓの１つの柱ですから、これは今後、重要な価値を有するものだと考えております。収束のきざしが見えましたら、ぜひともにぎわい創出を直ちにやっていただきたいと考えておりますけれども、その点、いかがお考えでしょうか。","respondent":"高山健康課長、小林環境課長、山崎商業・ものづくり課長","answer":"それから３点目といたしましては、やはり飲食店で受動喫煙を受けた方が多いということであれば、飲食店の対策が一番肝要かと思いますので、先ほど。私からは、戸越公園で建設を予定しております（仮称）品川区立環境学習交流施設についてのご質問にお答えいたします。大きく３点あったかと思います。区では、従前、年間６億円、春、秋に３億円ずつに加え、今年は２億円の増額を予定しておりまして、春、秋に。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"しながわ健康プラン２１についてですけれども、受動喫煙対策は、ぜひともしっかりとやっていただきたいと考えております。しながわ健康プラン２１の存在自体を知らない区民の方がまだまだ多いかと思いますので、この健康プラン２１の存在と、そしてこの内容をどうやって区民に対して届けていくのか、これが課題かと思いますけれども、その対応についてどのようにお考えになっているのかをお伺いいたします。","respondent":"高山健康課長、小林環境課長、山崎商業・ものづくり課長","answer":"健康づくり推進委員の集まる会合の場などで、新しくできました健康プランをお示しすることで。こういったところの活用を進めてまいりたいと思います。展示物につきましても、更新性が高いものを工夫してまいりたいと考えているところです。前月比較で５％減です。ただ、５％では済まないというようなことで相談に来ていらっしゃるのが現実です。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問","question":"２７０ページ、４款衛生費、１項保健衛生費、２目母子保健費、２７１ページ、１目健康推進費、荏原保健センター管理運営費、２８５ページ、２項環境費、１目環境対策費、エコライフ普及事業、２９５ページ、５款１項１目産業経済費、雇用確保支援事業、そして環境で、除草剤、農薬についてと、また、品川区中小企業事業資金融資あっせん、経営変化対策資金について伺います。","respondent":"榎本荏原保健センター所長","answer":"荏原保健センターにおきましては、今、委員がおっしゃられた集まりでありますとか、もしくは乳幼児健診、母子保健事業、精神保健事業、あと、精神や難病の方々の医療費助成の窓口なども行っておりますので。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"２７０ページ、母子手帳について伺います。生活者ネットワークは、これまでも子どもを授かって母子手帳を手にした母親が、そのときに子どもの権利条約を知ることができるように、子どもの権利条約を母子手帳に記載すること、または母子手帳配付時に権利条約を別途配布することを求めてきました。しかし、日本は権利条約の締約国です。改めて見解を伺います。","respondent":"高山健康課長","answer":"児童の権利に関する条約も大変崇高なものだと思いますし、児童憲章につきましても、内容においては遜色のないものと考えておりますので、今後、母子手帳の内容を見直していく中で、そうした新たなものの可能性については検討してまいりたいと考えております。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"２０１９年に「広げよう！子どもの権利条約キャンペーン」がありました。子どもたちは、自分たちは子どもの権利条約を知る機会がたまたまあり、運がよかった、条約を１人でも多くの人に知ってもらい、子どもには安心して生きられる権利があると知ってほしいと話しています。子どもの権利が実現するよう、改めて保護者の認識、理解が広がる工夫を、リーフレットでもいいので求めますが、いかがでしょうか。","respondent":"高山健康課長","answer":"子どもの救急の関係でありますとか、あるいは妊娠にまつわるさまざまなご相談先を記載した名刺サイズのカードを入れることで提供しています。あまり過度な負担とならないような中で、内容については精査してまいりたいと考えております。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもの権利条約は、子どもが守られていると子どもたちが確認できる条約です。款をまたぐため答弁は結構ですけれども、ホームページの更新もあわせて求めます。次の質問に進みます。除草剤、農薬の使用状況について伺います。区内の施設のさまざまな場所で除草剤が使用されているのではないかと懸念しますが、特に子どもが手を触れるところでの除草剤、殺虫剤の使用状況について伺います。","respondent":"小林環境課長","answer":"国や都から、特に学校においては児童が授業を受けている日あるいは時間等に実施しないなど散布等や時間等に対して十分配慮するように求められているところです。","id":"exchange-034"},{"speaker":"田中委員","kind":"確認","question":"成分を確認して、環境に負荷のない安全性が高いものを選択してほしいと思いますし、なるべく手で抜く方向というか、使わない方向でお願いしたいと思います。２９７ページ、伴走型企業支援訪問事業、就労支援について伺います。これまで行ってきた伴走型企業支援訪問事業の拡充、強化をする中で、障害者の就労を進めるために、事業者への雇用支援を、強化、拡充してほしいという視点から質問をします。","respondent":"山崎商業・ものづくり課長","answer":"障害者の方にとってみますと、なかなかフルタイムも難しいというようなことも場合によって多いですので、短時間勤務等のマッチングなども含めてやらせていただいているような状況です。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"障害者の方にもフルタイムを求めている方がいらっしゃいます。企業が受け入れ態勢を整えられるような区の支援が必要だと考えますが、改めて見解を伺います。社会全体で障害者の就労について考えることや、法に沿って誰もが働ける環境を整えていくためのフォローを品川区に率先して行ってほしいと考えています。区の見解を伺います。","respondent":"山崎商業・ものづくり課長","answer":"そういう意味では、フルタイムに限らず労働力としてきめ細かいマッチングを私どもは模索をし、障害者福祉分野では、そうした自立の観点からというようなところで、繰り返しになりますが、双方、所管部門が連携しながら対応させていただいて。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"新型コロナウイルス感染症の影響による品川区中小企業事業融資あっせん、経営変化対策資金について伺います。紹介状を持っていった金融機関から融資決定までには、どのくらいの時間がかかるのかも伺います。フリーランス、パート、アルバイト雇用者への支援政策についても、基本は国がやるべきと考えていますが、国の制度ができるまでの緊急的支援策を区として既に検討されていたら、それもあわせて伺います。","respondent":"山崎商業・ものづくり課長","answer":"品川区では、こうした事業所が全２万の事業所のうち８５％を占めておりますので、小規模事業者については、ほぼこちらの融資が対応できるというような状況です。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"本来であれば、丁寧な審査チェックを求めるところですが、今回は緊急的な対応としては、なるべく早く事業者の手に渡り、支援につながるよう進めていただきたいと思います。次へいきます。２８５ページ、エコライフ普及事業について伺います。区有施設建設のときには、国産材を使用する施設となるのか、建築材としては無理でも内装や家具などに間伐材を使用していくのかなど、方向性を伺います。","respondent":"小林環境課長","answer":"方向性ですが、区では平成２７年にそういったような木材利用に関する方針を策定しておりまして、木材利用の推進を図ったところです。現在、学校をはじめとしまして、現在計画を進めております環境学習施設、児童相談所においても、その使用について進めているところです。","id":"exchange-038"},{"speaker":"松本委員","kind":"質問","question":"今日は２７７ページのこころの健康づくり事業について伺います。昨年、ＷＨＯがゲーム障害を新しい国際疾病に認定しまして、この新分類は２０２２年から発効されるというふうに伺っております。逆に言ったら、まだ発効されてもいないというような状況だと思います。慎重に対応していく必要があるのではないかというふうに思うところですけれども、まず、このゲーム障害の定義についてお願いいたします。","respondent":"間部大井保健センター所長","answer":"ゲーム障害の定義ですが、ゲームを過度に集中してやり過ぎることにより、社会生活や学校生活等に影響が出る、このような定義になってあります。","id":"exchange-039"},{"speaker":"松本委員","kind":"意見","question":"実際に診断されるためには、１２カ月以上その状態が続いているとか、なかなかハードルが高いところもあるのではないかというふうに思っております。昨年度で結構ですけれども、そういった相談が全部で何件ぐらいあって、そのうちネット・スマホ・ゲーム依存だというふうな形で相談があった件数がどの程度あったのかお願いいたします。","respondent":"間部大井保健センター所長","answer":"過去３年を見ても、大体１,０００から１,１００件ぐらいで推移しておりまして、この中の内訳としては、アルコールや薬物依存や躁鬱関係だとか、いろいろなものがございまして、直接的にネット・ゲーム依存ということは、この中から推定はしかねるのですが、最近は。","id":"exchange-040"},{"speaker":"松本委員","kind":"意見","question":"そういった中で、当然ですけれども、ゲーム依存なのだという相談が来ても、それが果たして本当にＷＨＯが認定した定義と合致するというか、診断と合致するのかというのは、また別問題だと思いますし、一方で、そもそもゲーム障害、今回、一応認定はされたということですけれども、それ以外のスマートフォンやネットの依存症、これもよくメディアではそういう用語は出てくるのですけれども、医学上。","respondent":"間部大井保健センター所長","answer":"ただ、依存症につきましては、この原因がさまざまでありまして、私もいろいろな現場での対応を見てみますと、やはり何かしらの生活上の生きづらさを感じた方が、それをやわらげるために、ある方はギャンブルにいったり、ある方はアルコールにいったりという中で。","id":"exchange-041"},{"speaker":"松本委員","kind":"確認","question":"一応確認なのですけれども、明確に国際的にこういうふうなものだったら、ネット依存症だ、スマホ依存症だという形で診断しなさいみたいな基準は特にないというふうに伺ってよろしいでしょうか。","respondent":"間部大井保健センター所長","answer":"現在のところ、先ほど委員からもご指摘がありましたように、ＷＨＯの分類につきましても２０２２年１月から発効ということで、今段階でまだ明確な位置づけという形はございませんし、今、日本におきましても。","id":"exchange-042"},{"speaker":"松本委員","kind":"確認","question":"ゲームの時間のところもまたあとで触れたいところですけれども、ありがとうあります。そうなってくると、言ってみたら、調査研究段階で予防法や診断、対処法が確立しているわけではない、これも一応確認しておきたいのですけれども、ご答弁をお願いいたします。","respondent":"間部大井保健センター所長","answer":"現在のところ、いまだ確立はされてございません。","id":"exchange-043"},{"speaker":"松本委員","kind":"意見","question":"そのような状況の中で、ゲーム障害あるいはスマートフォン、インターネットの使い過ぎとの関係で、よく名前が出てきますのが、独立行政法人国立病院機構久里浜医療センターかと思います。過去の議会の議事録を拝見いたしますと、品川区でも思春期講演会で久里浜医療センターの方を講師にお招きというふうな情報が出てきました。どのような講演会だったのか、こちらもお願いいたします。","respondent":"間部大井保健センター所長","answer":"私ども、平成３０年１２月に思春期講演会ということで、このネット・ゲーム依存を取り上げて、ちょうどそのときに新聞紙上でも、先ほど来、委員がご指摘のようなことが騒がれていたということで取り上げたもので、内容については、一般的なネット・ゲーム依存の成り立ちですとか。","id":"exchange-044"},{"speaker":"松本委員","kind":"質問","question":"そういった中で、例えばゲームやスマートフォンを取り上げてしまうというふうなことについても、それがよいのか悪いのかというところを含めてお話があったのでしょうか。お願いします。","respondent":"間部大井保健センター所長","answer":"私どもが開催しました思春期講演会で講師を務めていただいたのが久里浜の先生で、１つの考え方として、そういうゲームを取り上げるというか、時間に制限を設けるようなことも対策上は有効ではないかというお話があったところです。","id":"exchange-045"},{"speaker":"松本委員","kind":"質問","question":"政府としても、ゲームのプレイ時間の制限に科学的な根拠があるとは考えていないというふうなことがわかったわけです。先ほどもご答弁がありましたけれども、ゲームやスマホを無理やり取り上げるというところと関連して、ゲーム障害、あるいは依存症と言われているものの発症を防ぐためのゲーム時間の制限に科学的な根拠や有効性があると区としてはお考えでしょうか。お願いいたします。","respondent":"間部大井保健センター所長","answer":"私どもにつきましても、先ほど来ご紹介のありました政府の答弁と同様、現在のところ、エビデンスについては承知していないです。","id":"exchange-046"},{"speaker":"松本委員","kind":"意見","question":"ひきこもりなどは、本当に原因がネットとかスマホなのかというところもすごく重要なところで、実は原因は全然違う、いじめとか家庭の問題とかいろいろなところがある中で、結果的に、その後、ネットやゲームにはまってしまったというようなところもあると思いますので、そのあたりはまずは実態調査、研究、そういったところから、これは区に限らず大切だと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今から２年前、２０１８年の第３回定例会の一般質問で、品川区には存在していなかった品川区版のがん対策推進計画の策定を、やはり区民の命と健康にとって大きな驚異であるということから、我が会派として求め、区長から検討するというご答弁をいただいて、いよいよその成果物が出てまいりました。この意味を端的に教えていただきたいということです。このことを要望したいと思いますが、いかがでしょうか。","respondent":"高山健康課長、小林環境課長","answer":"２点お尋ねいただいておりますが、今年度、しながわ健康プラン２１とは独立した形で策定委員会を立ち上げての計画づくりということで、この間、さまざまな要素を盛り込もうということで取り組んできた結果。そういったところも区内で率先的な開発を行っている企業がありますので、そういったところとの連携につきましては、関係課と情報共有を図りながら、地産地消といいますか。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"確認","question":"施政方針の中で改めてマギーズ東京の活用について、令和２年度はがん患者やその家族が気軽に訪れて安心して相談できる夜間相談の充実を行っていくということで、江東区豊洲にあるマギーズ東京を、月に１回、品川区民を対象にした、特に就労されている方、仕事をされている方向けの相談窓口を開いていただく委託をするということを伺いました。行きは法定速度で１４分でした。","respondent":"高山健康課長","answer":"具体的には、区内には２カ所のがん対策の拠点病院がありますが、そこでのがん相談支援センターでの周知はもちろんのことなのですが、保健センターを訪れる方、また、このマギーズ東京の代表を務められている秋山先生のアドバイスでは。","id":"exchange-049"},{"speaker":"あくつ委員","kind":"確認","question":"やっぱり今、働いている方は、品川区の公式のＳＮＳなどをよくみられている。職場においても見られるでしょうし、通勤・退勤の最中でも見られるから、ＳＮＳでの発信もお願いしたいと思いますが、いかがでしょうかというところ。江東区では、これも同じように月１回やっていますけれども、もしデータがあれば、どれぐらいの方の利用数があるのか、そこについても確認をさせてください。","respondent":"高山健康課長","answer":"２点のお尋ねです。ＳＮＳの活用という点です。もちろんこれは若い世代もがんになるですので、こうした若い層に向けたより効果的な周知方法としてＳＮＳの活用なども図ってまいりたいと考えております。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問・要望","question":"年間でそれぐらいの方が利用されるということですけれども、先ほど、私も自分の体験を申し上げましたが、やはりそういう病院以外のところにゆっくりと自分の気持ちに寄り添ってくれる方がいるという施設があるということを区民に知っていただく、繰り返しになりますが、そこのところをしっかりと知らしめていただきたいということをお願いいたしまして、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問","question":"私からは、２７１ページ、受動喫煙防止対策費について伺います。２月に日本禁煙推進医師歯科医師連盟が行ったシンポジウムでも、外国人の方が話されています。オーストラリアでは、たばこは１箱３,５００円ほどで、日本は安い。台湾の方は、台湾では２００７年から室内全面禁煙で、レストランでは煙がないことが当たり前。世界での日本の状況と区内の状況を区はどのように認識しているのか伺います。","respondent":"高山健康課長","answer":"具体的には、飲食店における受動喫煙がやはり一番大きな要素だと思いますので、そちらを重点的に取り組むことによって、そうした受動喫煙の害に遭ったという人の割合を減らしてまいりたいと考えております。","id":"exchange-052"},{"speaker":"のだて委員","kind":"質問","question":"立ち遅れたこの日本の状況を世界に肩を並べられるように対策が急がれると思います。こうしたたばこによる健康被害の周知徹底が必要だと思いますが、いかがでしょうか。","respondent":"高山健康課長","answer":"具体的には、喫煙が全てのがんにおいて何らかの形でがんのリスクを高めていく、確実ないしはその可能性があるといったリスクの因子として挙げられている点につきましても、計画の中で対応しています。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問","question":"具体的にどのように周知を進めていくのか、先ほど、計画を策定しているということで重点の１つということで説明されておられましたけれども、具体的にどうしていくのかというところで伺いたいと思います。広報でも繰り返し取り上げることですとか、あとはたばこの健康被害についてのパンフレット作成など、周知を徹底していくべきだと思いますけれども、いかがでしょうか。","respondent":"高山健康課長","answer":"具体的には、来年度以降、品川区がん対策推進計画を進めていく中で、がんの予防に資するさまざまな生活習慣などをわかりやすい形で周知をしてまいりたいと考えております。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問","question":"大阪国際がんセンターがん対策センターの田淵医師は、有害性成分の量を９０％低減との宣伝もありますが、一部の有害物質の結果に過ぎません。むしろプロピレングリコールは２３倍、グリセロールは２倍など、有害物質が増えているものもあります。この加熱式たばこの害についての区の認識と、この害についても周知をすべきだと思いますが、いかがでしょうか。","respondent":"高山健康課長","answer":"加熱式たばこにつきましては、実はホームページで既に危険性といいましょうか、取り扱いについて載せておりまして、現下におきましては、都において科学的なエビデンスが少ないということで、取り締まりについては紙巻きたばこと同一ではございませんが。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ力強くやっていただきたいと思いますし、子どもたちにも、ぜひそういったたばこの害について教育をしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、２６９ページ、地域医療連携、２７７ページ、こころの健康づくり事業、感染症対策、２９５ページ、産業支援施設運営費、２９７ページ、中小企業活性化推進事業費についてお伺いいたします。大規模感染症が発症した際の医療提供体制について、今後、状況の進展に応じて講じていくべき施策、地域医療体制の平準化のあり方などをご検討いただきたいのですが、区のご見解を伺います。","respondent":"鷹箸保健予防課長、榎本荏原保健センター所長","answer":"大規模感染症、例えば今の新型コロナウイルス感染症であれば、もう少し患者が増えていって医療が平準化することに関してですけれども、３月１日に国から出された方針で、今後、考え得る対策、患者がもう少し増えた場合に。私からは、軽度知的障害や境界知能のお子さんや若者の抱えている課題と相談支援の状況ということですけれども、乳幼児から児童、若者の世代とさまざまな時期の中で。","id":"exchange-057"},{"speaker":"横山委員","kind":"質問","question":"３点目ですけれども、産業支援施設運営費についてお伺いいたします。区民の方から、品川区は女性の創業支援に積極的です。４点目、中小企業活性化推進事業費についてお伺いします。今、Ｊリーグですけれども、クラブ名に地域名が入っているので、クールローカルということで、地域と海外とを直接結びつけるようなビジネスモデルのスキームでやっているとお聞きしました。","respondent":"山崎商業・ものづくり課長","answer":"２点目の五反田バレーのご提案の中身につきましては、いろいろ区としましても地域性ですとか、五反田の企業のニーズなども勘案しながら、ご提案の趣旨については研究してまいりたいというふうに思っているところです。","id":"exchange-058"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひさまざまな手法を研究していただけたらと思います。最後に、私は、平成２８年の第１回定例会からテレワークの推進をお伝えしておりまして、区としても進めていただいているところです。こちらは要望を伝えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、２７５ページ、子宮がん検診、乳がん検診、２８１ページ、家庭における温暖化対策啓発冊子作成、２９３ページ、中小企業経営支援事業費、この３点をお伺いいたします。ページ数、順不同でまいります。子宮がん検診、乳がん検診についてですけれども、受診率の現状をお聞かせいただきたいと思います。国や都の受診率と比べて、区の受診率の現状をどのように捉えていますでしょうか。お願いします。","respondent":"高山健康課長","answer":"国、都との比較で申しますと、実はこちらは乳がん検診、子宮がん検診ともに、いわゆる東京都の平均、それから区部の平均よりは上回っているという状況ではありますが、しかしながら、国が目標とします５０％という高い目標には。","id":"exchange-060"},{"speaker":"こんの委員","kind":"質問","question":"現状はわかりました。まだまだ５０％の目標にはなかなか至らないところではありますが、現状としてはよくわかりました。次に、この受診率向上への取り組みについてお伺いしたいと思います。現在はどのような取り組みをしているのか、また、その取り組みの評価とか、課題とか、さらに今後の取り組みをどのように考えていくのか、受診率向上への取り組みの現状と今後の方向性をお聞かせください。","respondent":"高山健康課長","answer":"乳がん検診、子宮がん検診の受診率向上に向けた取り組みです。こちらの検診につきましては、個別の通知を差し上げております。","id":"exchange-061"},{"speaker":"こんの委員","kind":"提案","question":"これまで私たち会派として、受診率向上への取り組みについて、さまざまな提案をしてまいりました。例えば、夜間・休日の検診、電話による受診勧奨、女医による検診の提案など、さまざましてまいりましたが、残念ながら、いまだそれは取り入れられていない状況であります。具体的には、乳がん検診も子宮がん検診も１カ所の医療機関で同日検診ができる検査体制、こうしたことが必要であるというふうに思います。","respondent":"高山健康課長","answer":"受診率向上に向けた受診環境の整備というお尋ねかと思います。委員ご紹介のとおり、現在、２つの検診を同じ医療機関で受診ができるところは２カ所ということで、旗の台の検診センターと牧田総合病院の検診クリニックの２カ所というふうに私どもも認識しています。","id":"exchange-062"},{"speaker":"こんの委員","kind":"質問","question":"次の質問にまいります。中小企業経営支援事業費からです。そこでまず、通常の融資あっ旋事業と比べて、今回の緊急資金はどのぐらいの規模の融資なのか、また、利用できる零細企業はどういう要件なのか、また、融資を受けられるまでの日程など、どのぐらいのスピード感でこれが申請、そして受理できるのか、事業の概要や要件など、また申請から融資を受けられるまでの流れ、日数などを、簡潔にご説明ください。","respondent":"山崎商業・ものづくり課長","answer":"相談をいたしまして、銀行に融資を実施していただくことがありますので、紹介状の発行を基本的には即時に行います。その前段で電話で丁寧な対応をして、二度手間にならないような注意深い配慮をしながらやらせていただいております。","id":"exchange-063"},{"speaker":"こんの委員","kind":"質問・要望","question":"この事態を乗り切るための対策として、非常にこの対策を評価するところです。そこで、実際に緊急資金を活用したい場合の相談対応についてお伺いしたいのですが、細かい案件で恐縮ですが、お聞きいたします。こうした零細企業もこの緊急事態を乗り切るためにご相談に乗っていただきたい、こういう思いで質問するのですが、こういうケースに対しての相談対応について、お考えをお聞かせください。","respondent":"山崎商業・ものづくり課長","answer":"もちろん今回の影響につきましては、区としましても、商店街などにある飲食店などでお客さんが減っている、あるいは、いろいろな催し物がキャンセルによって影響を受けているというような特徴があるかと考えております。","id":"exchange-064"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ大事な観点の啓発の冊子ですので、より一層、読んで、見て、行動に移れる、そうしたところまでの踏み込んだ啓発のものにしていただきたい。もう１つ大きな視点で、ＳＤＧｓの１７項目の中でも６項目が環境にあたる項目でもあると思いますので、こうした視点も盛り込んで、取り組みやすい環境対策をお願いして終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、２７５ページ、成人歯科健診と眼科検診に絡めてしながわ健康プラン２１についても伺いたいのと、それから、少し新型コロナウイルス感染症についても伺えたらと思っています。そうした方が歯科治療につながっているのかどうかというところまで把握はされているのでしょうかということを伺いたいと思います。","respondent":"高山健康課長","answer":"成人歯科健診のお尋ねを２ついただきました。１つ目は、区の成人歯科健診の受診率の評価という点です。平成２９年度に、委員ご紹介のとおり、二十歳まで年齢を引き下げまして、二十歳から７０歳までの５歳刻みで、今、事業を実施しています。","id":"exchange-066"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"歯科健診が歯科にかかるきっかけにということも私も言ってきたので、そうなるといいなとは思っているのですが、これだけの方が要指導、要精密検査ということで、受診率が９％台ですので、まだまだ多くの方が自分の歯の状況をどうなっているか知らなかったり、わからない状況にいるのではないかと思います。そのかむ力、咀嚼力についての区の考えというか、認識をお聞かせいただきたいと思います。","respondent":"高山健康課長","answer":"当然のことながら、区で実施しております８０２０運動でありますとか、９０１６運動であるとか、そういった年を重ねても自分の歯でかめる喜びといいましょうか、そういったものをきちんと区民の方にもわかっていただいて、長きにわたって自分の歯でかむことができる。","id":"exchange-067"},{"speaker":"石田（ち）委員","kind":"質問","question":"かむということは、脳への影響もありますし、それから、よくかむことで吸収できる栄養も違ってくるということにもなってくるのです。こうしたことまでかいていただくと、これは大変だな、歯石をとろうかな、歯を私は磨けているのかなというふうに自分からの自発的なものになってくるのではないかと思いますので、そういうところまで知らせていただけないかと思うのですけれども、いかがでしょうか。","respondent":"高山健康課長","answer":"いずれにしましても、歯と全身の疾患との関係については大変大きな課題として取り上げられておりますので、そうした点につきましては、この計画の内容にとらわれずに、さまざまな場面を通じて啓発してまいりたいと考えております。","id":"exchange-068"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"どうしてもこれは少な過ぎると私も思うのですけれども、これは医師会と協議して決定したということを、昨年、課長が答弁されているのですけれども、医師会の先生方がこの２つの年齢だけでいいと言うわけはないだろうと思って医師会の先生方に確認しましたところ、ゼロか２つかと言われれば、ないよりは２つの年齢のほうが、あったほうがいいということで、それが４５歳と５５歳になったというご意見でした。","respondent":"高山健康課長","answer":"年齢拡大につきましては、とりあえず今年が終わり受診率などが出てきますので、そうした精密検査などの状況などを見ながら検討してまいります。","id":"exchange-069"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ拡大していただきたいですし、医師会の先生方もそうおっしゃっていますので、ぜひお願いします。そして、新型コロナウイルス感染症のほうに移ります。そういう上では、体制の強化がすごく必要なのだろうと思っています。ですので、体制強化、ただでさえ品川区は保健師が２３区で最低の人数と言われていますので、そういった職員拡大をしていくべきなのではないかと思うのですけれども、いかがでしょうか。","respondent":"鷹箸保健予防課長","answer":"何とか潰れないよう区民の方に影響がない形で、いい形で感染症対応は進めていきたいと考えております。","id":"exchange-070"},{"speaker":"石田（ち）委員","kind":"質問","question":"本当にご苦労はあるだろうと思っていますし、帰りが遅くなるということもお聞きしています。そういう中でやっぱり体制強化、これからさらに対応が必要だと、戦いが必要だとまで言われていますので、ぜひ保健師の増をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"高橋（し）委員","kind":"提案","question":"健康センターです。歳入のほうでもお尋ねしたのですが、最後にちょっと時間がなくなってしまったので、再確認します。利用料から引く基準額と、その差し引いた金額の２割が還元金という契約の基準額と、２割という割合を年度協定等で改める考えはないのでしょうか。そういったことを指定管理者に提案するつもりはないでしょうか。この点についていかがでしょうか。","respondent":"高山健康課長","answer":"割合もそうなのですけれども、金額面においても指定管理者にとってもメリットがあるような形で、区と指定管理者双方にＷｉｎ－Ｗｉｎの関係でこの割合が決まっていけばいいものというふうに考えております。","id":"exchange-072"},{"speaker":"高橋（し）委員","kind":"提案","question":"ですから、今のところで年度協定の中での提案を改めて求めます。これは要望をさせてください。ですから、この還元金のことを含め、指定管理者との契約、指定管理者制度のあり方という大きな見方で、公の施設で事業所がこのような形で管理をしているという、事業者と一定の緊張感を持つべきではないかと考えます。指定管理者制度全体の考え方としてお伺いします。","respondent":"柏原企画調整課長","answer":"緊張感というお話がございましたけれども、指定管理は区民サービスの向上、それから民間の事業者を使うメリット、そういったところを生かしていくというのが最大のポイントではありますけれども、事業者側にもメリットがないと。","id":"exchange-073"},{"speaker":"高橋（し）委員","kind":"質問","question":"民生費のほうでも保育園の貴重な人材として派遣されているというご答弁がありました。現在はどのような状況ですか。もちろん一部の方だけのお話だと思うのですが、全体の評価につながってしまいますので、その点をお願いします。それから、今、保育園に派遣されている方々がいらっしゃると思いますが、どのような勤務の状況というのでしょうか、勤務先での評価というか、その辺をお願いします。","respondent":"山崎商業・ものづくり課長","answer":"いわゆる就業規則等に反する行為などを行う不適格就業会員に対して苦情といったものは全体的な傾向としては減少しております。これは平成２９年度にそうした会員に対しての措置要綱を制定し、シルバー人材センターで改善活動が行われているというようなことです。","id":"exchange-074"},{"speaker":"高橋（し）委員","kind":"質問","question":"お忙しい保育士のフォローというか、カバーを、この派遣されている方々が行われているということで、今、評価が高いということを伺いました。それぞれマナーやモラルについての問題も解決していると伺いました。区としては、今後、このシルバー人材センターの取り組みの拡大について、どのように行っていくのでしょうか。支援などについて、具体的にお願いします。","respondent":"山崎商業・ものづくり課長","answer":"保育園へのさらなる展開、あるいは一般事務部門など新たな派遣分野の拡大などにも取り組んでいくとしておりますシルバー人材センターの活動を区として支援してまいりたいというふうに考えているところです。","id":"exchange-075"},{"speaker":"湯澤委員","kind":"質問","question":"私からは、２７１ページ、公害健康被害予防事業費、機能訓練事業、それから、２９３ページ、「伝統の技と味しながわ展」開催等経費について質問します。その中で、水泳教室・ぜん息健康教室とありますが、このぜん息健康教室とはどういった教室であるのか、ぜん息との診断がないと申し込めないのでしょうか。定員と応募状況などもあわせて教えてください。","respondent":"高山健康課長","answer":"対象者は、水泳教室につきましては、年長児から小学校６年生、それからぜん息健康教室については、小学校１年生から中学校３年生までというような形です。募集の定員については５０名ということですが、基本的にはこの５０名の定員内で応募いただいているところです。","id":"exchange-076"},{"speaker":"湯澤委員","kind":"質問","question":"水泳は呼吸器の機能を高めるということで、小児ぜん息などの予防には大変効果的だと聞いておりますので、この事業での効果が出ていると思いますが、そちらはいかがでしょうか。","respondent":"高山健康課長","answer":"こちらは、品川区の水泳連盟の方々のご協力のもと、非常に丁寧に指導していただいておりまして、多くの子どもたちが連続する４日ないし５日の期間を満了して修了証を皆さんが受けとっているということで、事業としては大変充実したものと考えているところです。","id":"exchange-077"},{"speaker":"湯澤委員","kind":"質問・要望","question":"私も実はぜん息持ちでありまして、２年前からぜん息と診断されました。予防事業として、ここに書いてあります年齢以上の方に対する取り組みがあれば教えていただきたいと思います。ぜん息と診断された方への区の取り組みなどもあれば、あわせて教えてください。","respondent":"高山健康課長","answer":"そのほかにも呼吸器リハビリ教室という、これは予防事業とはちょっと異なるのですが、福祉的な視点で実施している事業がございまして、こちらは公害認定を受けられた方と、区内にお住まいまたは在勤の気管支ぜん息の方も対象とする事業で。","id":"exchange-078"},{"speaker":"湯澤委員","kind":"質問・要望","question":"このイベントは、今年で３０回を迎える歴史のあるものでありますが、まず、この事業の目的と計上されている６４０万円余の予算の内訳を教えてください。それから、全国的に見ると、伝統工芸への従事者は年々減少傾向にあると思いますが、品川区においてはいかがでしょうか。しながわ展への来場者数はどのくらいであったか、ここ数年の推移と、しながわ展への区の評価もあわせて教えてください。","respondent":"山崎商業・ものづくり課長","answer":"これらを毎年ご紹介することを通じて、身近な区民の皆様に楽しんでいただくとともに、内外に品川区の魅力として発信するということで、毎年、きゅりあんのイベントホールで１月末に行っているです。それから、主な内訳です。","id":"exchange-079"},{"speaker":"湯澤委員","kind":"質問","question":"私は、この予算でそれだけの来場者があるのはすごいなというふうに思っております。昨年はＴＯＣで開催されておりまして、大変盛り上がっておりましたので、そちらの企画を担当された方にお話を伺いました。先ほど、しながわ展の事業目的をお伺いしましたが、区のホームページでは、区内で育まれた伝統と歴史を持つ職人の技と味を多くの方に知ってもらうとうたってありました。","respondent":"山崎商業・ものづくり課長","answer":"こうしたことを通じて、区としてもしっかり承継がなされることを応援してまいりたいというふうに考えるところです。","id":"exchange-080"},{"speaker":"湯澤委員","kind":"提案","question":"それともう１つ、お話を伺った方からは、あらゆる方に体験してもらいながら魅力を五感で感じてもらうことが大きなコンセプトであると教えていただきました。天候に左右されずに多くの方に参加してもらうための周知として、著名人を呼び、一緒に体験をしてもらう、区内小中学校にて生徒にチラシを配布してもらう、予約制の体験コーナーを各ブースにつくるなどをされているとのことです。","respondent":"山崎商業・ものづくり課長","answer":"イベントは効果的に集客をさせるというのは、１つ、実施する側の工夫なども含め、おっしゃるとおりだと思います。１つ、今年も伝統の技と味ということですので、それが変わらぬよさと、何か１つ新しい工夫を入れることによってマンネリを防ぐということも必要かと思ってあります。","id":"exchange-081"},{"speaker":"湯澤委員","kind":"質問・要望","question":"さまざまな取り組みをされていることで理解させていただきました。本当に人材育成を目的として、これからもしながわ展が体験型重視で開催されることを要望させていただきまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"木村委員","kind":"質問","question":"私からは、２８５ページの中ほど下にありますけれども、地域エコ活動推進事業からの質問をいたします。小学生のいる家庭にリーフレットを配布とありますけれども、なぜ小学生がいる家庭だけにこだわるのでしょうか。","respondent":"小林環境課長","answer":"家庭エコチャレンジのご質問です。小学校だけにこだわったところではございませんが、さまざまな年代に対して啓発活動を進めているところです。","id":"exchange-083"},{"speaker":"木村委員","kind":"質問","question":"小学生だけにこだわったということではないということをお聞きしました。子どもたちは学校では先生の言葉に、また家庭では親の言葉に反応するわけですから、親の再教育というと、ちょっと失礼ですけれども、私はまずは親にしっかりとそのことをもう一度告知をすることが必要と思っていますけれども、その点について、お考えをお聞かせください。","respondent":"小林環境課長","answer":"この家庭エコチャレンジも、子どもだけを対象にしたというか、親子で一緒にやっていただいて、親子でいろいろな答えを出してもらう、そのようなところもここの中の趣旨には入っているかと考えています。","id":"exchange-084"},{"speaker":"木村委員","kind":"質問・要望","question":"“もったいない”プロジェクトからの質問ですけれども、令和２年２月２２日に、スクエア荏原にて、家庭で余っている食品を集めるフードドライブを開催する予定でしたが、新型コロナウイルス感染症のために中止になったということでありました。現在、本区での認定店は何店あり、そして実際に認定店の活動や活躍ぶりというものはいかがでしょうか。","respondent":"小林環境課長","answer":"“もったいない”推進店のご質問です。こちらは平成２７年から事業を開始したものでございまして、来年度、令和２年度に１５０店舗を目標に進めている事業です。","id":"exchange-085"},{"speaker":"木村委員","kind":"質問・要望","question":"どうぞ頑張っていただきたいと思います。そして、このような活動を品川区全体でできれば本当にかなりの効果が出てくると思います。現在、１５０店舗に迫るということでありましたけれども、まだまだこの活動をしっかりと続けなければいけないと思っています。行政側として、しっかり指導をして、しっかり調査等は行っているのかどうか、もう一度お聞かせください。","respondent":"小林環境課長","answer":"そういった中でも事業者向けの展開等につきましても、法の趣旨を踏まえながら、広く展開してまいりたいところで、今後、検討してまいりたいと考えているところです。","id":"exchange-086"},{"speaker":"木村委員","kind":"質問","question":"２８７ページのリサイクル活動支援事業からの質問です。ずばりお聞きいたしますけれども、区内にあるリサイクルショップは何のためにあるのでしょうか。","respondent":"工藤品川区清掃事務所長","answer":"特に、リサイクルショップです。リユース事業ですので、実際にそういったリユースの場である店舗の中に来ていただいて、直接やりとりしていただく。そういったところでリユースの大切さを実感していただける、そのようなところです。","id":"exchange-087"},{"speaker":"木村委員","kind":"意見","question":"そういう中で、裕福になると、我々はどうしてもお金をむだに使ってしまう、そしてちょっとだめになれば、すぐに捨ててしまうようなところがありますけれども、そういうことをなくすためにも、本当に子どものうちからしっかりと教育をしていかなければいけないと思いますけれども、まず行政側から区民の皆さんに伝えることがあればお伝えください。","respondent":"工藤品川区清掃事務所長","answer":"やはり３Ｒ、特にリユース（再利用）ということは大変重要です。そういった意識を持って発信してまいりたいと思ってあります。","id":"exchange-088"},{"speaker":"くにば委員","kind":"質問","question":"本日、私からは、２９７ページ、競争力強化支援事業および３０１ページ、商店街活性化事業費から、商店街ＩＴ導入支援事業について、３０３ページの商店街国際化推進事業についてお伺いします。商店街ＩＴ導入支援事業についてです。政府は、２０１７年に２１.３％だったキャッシュレス決済比率を、２０２５年に４０％にすることを目標としており、導入推進に力を入れております。","respondent":"山崎商業・ものづくり課長","answer":"商店街の店舗の導入支援ということになりますと、その商店街に属する個別の飲食店だとかという個店のほうになってくるわけですけれども、個店のほうにそうしたキャッシュレス対応機器のハード経費でありますとか、そうしたものを個店のほうに支援する部分と。","id":"exchange-089"},{"speaker":"くにば委員","kind":"質問","question":"各自治体や地域特性によって、キャッシュレスがなじむ、なじまないという点も一律で評価されるべきではないポイントだと考えます。そこで、地域密着店の多い１０５の商店街を有する品川区において、キャッシュレス決済を既に導入している店舗、事業者、また最近導入した店舗、事業者のご意見や感想等、地元ならではでお聞きになられている点をお知らせください。","respondent":"山崎商業・ものづくり課長","answer":"今回、キャッシュレスを導入しているという意味では、直接イコールの数字ではないかもしれません。６月までの５％の国の還元サービスに申し込みをした個店店舗数ということで、これは国のホームページにも公開されている数字ですけれども、約５,０００店舗というようなことです。","id":"exchange-090"},{"speaker":"くにば委員","kind":"質問","question":"ちょっと短い質問になりますけれども、それでは、国の施策とはまた別に、品川区としては、今後、商店とかを含めて、キャッシュレス導入について、どのようにお考えでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"一番大事なのは、「推進」という言葉で区が押しつけにならないような形で、先ほども商店街なり個店のそれぞれのニーズを把握しまして、この決済事業者でＩＴ化にしっかり対応した商店街をつくっていくのだというような自主的な部分に区としてはご支援をするということで。","id":"exchange-091"},{"speaker":"くにば委員","kind":"意見","question":"少し駆け足になります。品川区は従前よりインバウンド施策にさまざま取り組んでいますけれども、東京２０２０大会を目前に控え、これからの数カ月間がまさに勝負どころといえると思います。この短い期間中に訪れる多くの訪日外国人が品川区で体験する１つ１つのことをＳＮＳ等を通じ世界中に発信します。中小事業者、商店にどのようなメッセージを発信し、支援、後押しをしていくのか、お聞かせください。","respondent":"山崎商業・ものづくり課長","answer":"多言語などの対応という形でさまざま取り組まれている商店街の方々につきましては、そうした方向性で実現可能になるよう側面支援をしっかりしていくというようなところで取り組んでまいりたいというふうに考えているところです。","id":"exchange-092"},{"speaker":"くにば委員","kind":"意見","question":"そこで、最終的に、訪日外国人が短期間の間、大会期間中に大挙して、事業者にとってはそれが体験したことのないイレギュラーな事態として、ちょっと予測ができないことも発生すると思います。そういった短期間での例えば人手不足が予想される事業者に対して、雇用支援をしたりとか、あとは短期的な融資の緩和など、その辺について、短期間でのどのようなバックアップ支援していくか、最後にお願いいたします。","respondent":"山崎商業・ものづくり課長","answer":"従来からイベント単体のサポーター支援とか、あるいは、商店街のいろいろな諸活動を支援するサポーター制度がありますので、そうしたものを適用するなり、来街者と商店街の諸活動に乖離があるような部分が発生しましたら、商店街連合会などと連携しながら。","id":"exchange-093"},{"speaker":"くにば委員","kind":"質問・要望","question":"この数年間、まさに東京２０２０大会に向けて、インバウンド施策にさまざま取り組んできましたので、この数カ月の間でぜひとも成功させていただきたいと強く望みまして質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"西村委員","kind":"質問","question":"２９７ページ、２９９ページ、３０１ページ、五反田バレー情報発信・ネットワークづくり事業等、商店街にぎわい創出事業より、五反田バレー商店街連携事業について伺います。２９５ページ、武蔵小山創業支援センター、創業スタートアップ支援の充実についても伺ってまいります。商店街活性化につながる五反田バレー商店連携についてお聞かせください。","respondent":"山崎商業・ものづくり課長","answer":"来年度の新規事業で、五反田バレー商店街連携事業というものを１つ計画しています。","id":"exchange-095"},{"speaker":"西村委員","kind":"意見","question":"一体どうしたら商店街が元気になるのか、さまざまな自治体の取り組みを見ましても、一時的に売り上げが上がっても、根本的な解決につながるものはなかなか見当たりませんでした。担当課も手応えを感じていらっしゃる点や、区のお考えをお聞かせください。","respondent":"山崎商業・ものづくり課長","answer":"広い観点では、先ほどの地産地消的な答弁と重なりますが、どちらも品川区の特徴ですので、特徴と特徴をさらに掛け合わせて大きな付加価値を生んでいきたい、このようなところで取り組む所存です。","id":"exchange-096"},{"speaker":"西村委員","kind":"質問・要望","question":"五反田バレーの方に実際に伺いますと、大手企業や行政とつながることが実利につながるので五反田バレーに参加したいと地元企業の方から言ってきてくださるとおっしゃっていました。平均年齢３０歳から３５歳ぐらいとおっしゃっていましたから、渋谷に比べると少し落ち着いた年齢かと思います。渋谷、品川のビルでは、入居の審査で３期分の決算が求められ、赤字だと入居は難しくなると聞いたことがあります。","respondent":"山崎商業・ものづくり課長","answer":"品川区としましては、情報通信業の集積の進展ということで、特に五反田バレーという法人に対してのみということではございませんが、これは１つ、品川区の産業構造の特徴として、もともと情報通信業が集積をしていたということで、平成２０年ぐらいから。","id":"exchange-097"},{"speaker":"西村委員","kind":"質問","question":"ＩＴ企業の皆さんは、本当にスピードが速いなというふうに感じておりますので、さまざまな取り組みに期待をしております。次に、武蔵小山創業支援センターのリニューアル工事について伺ってまいります。リニューアルの目的と概要を簡単にお聞かせください。","respondent":"山崎商業・ものづくり課長","answer":"武蔵小山創業支援センターは平成２２年８月にオープンしまして、一定、物理的に少しメンテナンスが必要だというところと、いわゆる老朽改修だけではということもありまして、そこに１０年前から始めた創業支援で蓄えた知恵を踏まえて。","id":"exchange-098"},{"speaker":"西村委員","kind":"質問・要望","question":"今後、利用可能人数はどれぐらい見込めるのでしょうか。例えば１階の交流スペースだけを登録制などで利用することができるですとか、またＰＯＰ広告やチラシ等が製作できる工房を新設するとのことですので、新しい方がこのサービスだけを利用できるようにするなど、サービスの幅を広げると、新規利用者の開拓にもつながっていくのではないかと思いましたが、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"今現在、入居期限の関係もあり、事務室に入居をしている企業もありますので、相互理解のもと、調整をつけさせていただいて、場合によっては６階のコワーキング化を拡張するとか、６階についてはそのようなところで。","id":"exchange-099"},{"speaker":"西村委員","kind":"質問","question":"大変期待しております。新しい「ＭＵＳＡＫＯ ＨＯＵＳＥ」という親しみやすいネーミングもいいなと考えています。区は先んじてこのような取り組みを実施してきてくださいましたが、乳幼児を育てるフリーランスや在宅ワークの方は、区内にどれぐらいいらっしゃるのでしょうか。在宅ワーク支援につながるこのような整備も区全体で検討していただきながら、引き続きお願いしたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"おくの委員","kind":"質問・要望","question":"この問題については、昨年の決算特別委員会にて、我が党ののだて委員が、２０５０年までの温室効果ガス実質ゼロを目指す立場から、区有施設の太陽光発電などの再生可能エネルギー設備のさらなる設置、太陽光発電システム設置助成額の拡大、ＲＥ Ａｃｔｉｏｎへの参加の検討、非常事態宣言などを求めて質問しました。そこでお伺いいたします。いかがでしょうか。","respondent":"小林環境課長","answer":"委員ご指摘のとおり、実質ゼロを目指していくというところについては、各国、動きがあることは承知しています。各自治体の中でも独自に実質ゼロを目指していきたいというところをお示ししているのは事実でございまして、区としてもそういったところは情報として把握しています。","id":"exchange-101"},{"speaker":"おくの委員","kind":"質問","question":"私は、実質ゼロを目指す期限のことについて、パリ協定の段階では２１世紀後半だったものが、その後の２０１８年の今述べました特別報告書を経て、２０５０年に実質ゼロを目指さなければいけない、もっと急がなければいけないのだという認識に変わってきたのだということなのですけれども、この認識、時期が早まってきたという認識はお持ちなのでしょうかと伺ったのですけれども、その点はいかがでしょうか。","respondent":"小林環境課長","answer":"あわせて国のほうですが、温暖化対策に向けた基本となる計画です地球温暖化対策計画が、来年度、見直しの時期を迎えるところでございまして、そういった内容を踏まえて、必要に応じた対応を区としてもとっていきたいと考えているところです。","id":"exchange-102"},{"speaker":"おくの委員","kind":"提案","question":"ですから、これはもう与党だ野党だを問わない、大企業かどうかも問わないような、そういう流れになっているのだなという問題です。そこでお伺いいたします。思い切って削減目標を、温室効果ガス２０５０年実質ゼロを前提にしたものに見直しまして、啓発冊子もそれを前提にしたものに見直されることを提案しますけれども、いかがでしょうか。お伺いいたします。","respondent":"小林環境課長","answer":"その予算については、令和３年度予算に反映させるとしているところでございまして、こういった国の動き等を見ながら、区としてどういったところで設定ができるかについては、引き続き検討はしてまいりたいというふうに考えているところです。","id":"exchange-103"},{"speaker":"おくの委員","kind":"質問・要望","question":"２０５０年実質ゼロというのは、非常に大きな流れになっているということを、これを目標に掲げること自体に意味があるということを踏まえて頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"高橋（伸）委員","kind":"確認","question":"初めに、オリンピック・パラリンピック開催期間中の収集対応ということで、新規事業であり、今年、東京２０２０大会の期間中にごみ収集を強化するということで、日曜収集、収集車両の増車、啓発活動をやっていくということですけれども、これは確認ですけれども、事業予算が３,４００万円余に対して、私が見ているところだと、２８９ページ。","respondent":"工藤品川区清掃事務所長","answer":"２８９ページのオリンピック・パラリンピック開催期間中の収集対応というのは、委員おっしゃるとおり、ごみ収集車を増やすというところでの経費、それと、先ほどお話がありましたように、資源回収のほうも増やすというところで、それを合わせた経費です。","id":"exchange-105"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それで、同じく２８９ページの車両購入ですけれども、小型プレス車を４台購入するということですけれども、この４台の内容を教えてください。お願いします。","respondent":"工藤品川区清掃事務所長","answer":"その内容といたしましては、清掃車両の買い替えですが、来年度は４台のうちハイブリッドの清掃車を２台購入しまして、あとの２台は通常使っている清掃車両を購入するという形になってあります。","id":"exchange-106"},{"speaker":"高橋（伸）委員","kind":"質問","question":"わかりました。この４台の内訳で、２台がハイブリッド車ということですけれども、これを全てハイブリッド車にしたほうがいいのではないのかと私は思うのですけれども、それをしない理由をお聞きしたいのと、あと、清掃事務所の直営車の台数と今後の購入はどういう考え方をされておられるのかお聞きしたいと思います。","respondent":"工藤品川区清掃事務所長","answer":"最後のご質問の今後の購入の考え方ですけれども、基本的にプレス車両は毎日使うものなので、かなり損傷が激しいということで、一応、考え方としては、６年ごとの更新を一定の目安にしています。","id":"exchange-107"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"引き続き環境に配慮した取り組み、また事故防止の取り組みを要望して、この質問は終わらせていただきます。ありがとうございました。続きまして、武蔵小山創業支援センターの事業内容についてお伺いいたします。大体例年行い、今回で９回を迎えていて、エントリー数は件数自体が増えているかどうかという確認をさせていただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"今年の８３件につきましては、ほぼ平均的な数です。過去には、一番最高では、第２回の１２３件です。それから、一番少ないところでは、平成２９年度の７８件というようなところです。","id":"exchange-108"},{"speaker":"高橋（伸）委員","kind":"確認","question":"私も今回、観覧に行く予定でいたのです、楽しみにしていましたが残念です。私の知人がエントリー審査、プレゼン審査に残って、信用組合賞を受賞しました。この信用組合と創業支援センターとのかかわりといいますか、どういう経過でかかわっていただいているのかということだけを確認させてもらいたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"ビジネスグランプリで受賞した人に賞品ということで協賛を創業支援センターのほうで募りまして、そういう意味で、地元の信金が幾つかございましたけれども、本グランプリの事業趣旨などに乗っていただいて、ともに応援しますです。","id":"exchange-109"},{"speaker":"芹澤委員","kind":"質問・要望","question":"私からは、２８７ページ、リサイクル活動支援の中から、リサイクルショップの運営と、関連してリサイクル情報紙の「くるくる」について伺います。２９９ページ、五反田バレー情報発信・ネットワークづくり事業等、あとは、２８７ページ、家庭用生ごみ処理機普及事業、５０台、こちらは時間があればやっていきます。リサイクルについて伺います。はご意見をお聞かせください。","respondent":"工藤品川区清掃事務所長","answer":"今後の運営につきましては、この運営はＮＰＯ法人エコタウンしながわというところにお願いしておりまして、そういった部分を含めて、今後どのような観点で展開するのがふさわしいのかというところも意見交換をしていますので。","id":"exchange-110"},{"speaker":"芹澤委員","kind":"提案","question":"五反田バレーについて伺います。その１つの提案として、例えば五反田バレーの加盟店の方々、ＩＴ、先進技術をいろいろ駆使した会社、民間企業がそれぞれそろっておりますので、それぞれのアイデアを活用して、例えば地域の五反田バレー内でのマニフェスト大会とかというのをつくっていただいてもいいのかなと思います。ご見解をお聞かせください。","respondent":"山崎商業・ものづくり課長","answer":"そういう意味では、さまざま取り組んでまいります。","id":"exchange-111"},{"speaker":"あべ委員","kind":"質問","question":"私からは、２９２ページ、産業経済費、特に中小企業経営支援について、それから２８３ページの（仮称）品川区立環境学習交流施設、２８５ページのプラスチックの削減などについてお伺いしたいと思います。株価が急落し、急激な円高も進み、３月の決算を乗り越えられない企業も少なくないと言われております。区の現状と今後の見通し、そしてその対策に対する決意をお願いいたします。","respondent":"山崎商業・ものづくり課長","answer":"国や東京都の政策、施策が充実してくるような動きになれば、そうしたところにもつなぐような、そういったことも必要だろうということと、それから、今回の場合は、特徴的に、いつまでにという区切り、期日がなかなか見えないところが難しいのですが。","id":"exchange-112"},{"speaker":"あべ委員","kind":"質問・要望","question":"品川区が経営変化対策資金としていち早く融資あっ旋を行っていることは高く評価をしております。品川区は従来の制度を下敷きにしていることもあって、今のところ、３月末までとありますけれども、見直す括弧書きもありますけれども、早急に期限の延長を検討し、周知をしていただきたいというのが１点。そしてもう１つは、対象の拡大です。ご答弁をお願いします。","respondent":"山崎商業・ものづくり課長","answer":"もちろん延長については、そうした方向で考えてあります。それから、実はもともと個人事業主も中小企業ということで位置づけをしまして、従来より融資の対象ということで適正に応援しています。","id":"exchange-113"},{"speaker":"あべ委員","kind":"質問・要望","question":"これは区ではないのですけれども、消費税の予定納税の期限の延期など、要望を多く聞いております。これは国に対して働きかけていっていただきたいと、これは要望にしておきます。それから、（仮称）品川区立環境学習交流施設、これは頑張って取り組んでくださっている方にはちょっと申しわけないのですけれども、これをつくる意味が、私にはどうもわからないのです。","respondent":"小林環境課長","answer":"施設ができ上がった後につきましても、使用するエネルギーにつきましては、自然エネルギーの電力会社から電力を購入するなど、さまざまな工夫をしていきながら、環境負荷がかからない活動は引き続き検討してまいりたいというふうに考えてあります。","id":"exchange-114"},{"speaker":"あべ委員","kind":"質問・要望","question":"ここは要望にしておきます。その結果と対策については、教育費のところでまた伺いたいと思いますが、もう１つ、プラスチックということで、今、注目しているのが、ビーズクッションです。このビーズクッションの捨て方について、環境の負荷をより小さくするための捨て方を検討し、そして指針をつくって広報していく必要があるのではないかと考えておりますが、いかがでしょうか。","respondent":"工藤品川区清掃事務所長","answer":"ごみリサイクル通信や、例えば地区連絡会といいまして、廃棄物減量推進員の連絡会があります。そういった中で、どのような形で出していただけるのかというところは考えてまいりたいと考えています。","id":"exchange-115"},{"speaker":"あべ委員","kind":"質問・要望","question":"ですので、やはり排出の段階からごみのカレンダーなど、あるいは分別の表などに、このビーズクションという項目をつくっていただいて、まずは出す方がほかのものと混ぜてしまったら、これを気づいてとり出すというのはなかなか難しいことだと思いますので、そちらの方向でぜひよりよい方向を考えていただきたいと思いますが、改めてご答弁をお願いします。","respondent":"工藤品川区清掃事務所長","answer":"ビーズクッションにつきましては、排出方法等につきましては、引き続き検討したいと考えています。","id":"exchange-116"},{"speaker":"大倉委員","kind":"質問・要望","question":"そこで商店街なのですが、品川区の１つの魅力に商店街があるのかと私は思っておりまして、そうしたところに海外の方が来たときに、やはりなかなか外国語が通じないというところで、多言語化がされたり、ポケトークが導入されたりしてきましたが、改めて調査によると、外国の方が買い物をする際に困ったときというのは、小売店で、特に商品の説明や商品を探す際には非常に困ったということで。","respondent":"山崎商業・ものづくり課長、小林環境課長","answer":"商店街のほうでは、そうしたスマホを使えるといいますか、若い方々の後継者育成事業などもやっていますので、これは商連と区も連携して、そうした方々を通じてアプリの有用性なども含めて。ただ、わざわざそれを使わなくてもいいのではないかというものもあるかと考えています。そういったところにつきましては、庁内でも情報共有を図りながら、可能な限りの取り組みは進めてまいりたいというふうに考えているところです。","id":"exchange-117"},{"speaker":"大倉委員","kind":"質問・要望","question":"変えられるものをというところでは、イベントで使用するプラスチック容器というところで、例えば今、天然素材を使用した木製のスプーンやフォーク、マドラーとか、あとは非木材を使用した紙容器みたいなものがあるのですが、そういったところを活用していくのかと思うのですが、こうしたところのまずは削減をしていくというところで、目標とか削減方針みたいなものがあるのでしょうか。","respondent":"山崎商業・ものづくり課長、小林環境課長","answer":"そういう意味では、所管を連携してというのは当然そういう意識で効率的ににぎわい創出などに努めてまいるということで基本的には考えているところです。職員のプラスチックに対する意識の向上がやはり大きな成果につながるですので、職員への情報発信を行うとともに、区としての新しい方針の方向性については、今後、研究を重ねていきたいというふうに考えてあります。","id":"exchange-118"},{"speaker":"大倉委員","kind":"質問","question":"プラスチックのほうですが、削減方針も変わっていくというところで、その目標をどのくらい削減していくのだという、品川区の行っているイベント、または販売等でさまざまワンウェイプラスチックが使われているかと思うのですが、今、どのくらい使われていて、今後どのように削減していくかという目標を持って啓発をしていったほうが、よりいいのかと思っているのですが、その辺の考えと、あと、東京都では。","respondent":"小林環境課長","answer":"地域との連携、大学との連携につきましても、さまざまな動きがあることは承知していますので、その辺の情報収集は引き続き図ってまいりたいというふうに考えているところです。","id":"exchange-119"},{"speaker":"塚本委員","kind":"質問","question":"現在、テレワークについては、工場のラインで物をつくっているような、そこに人が介在しているようなところとか、あるいは、いわゆるオフィスでのパソコン中心の事務作業とか、そういう業態によって親和性があるというか、導入しやすいとかしにくいとかということもあるかと思うのですけれども、区内の中小企業のテレワークの実施の現状、それと。","respondent":"山崎商業・ものづくり課長","answer":"ただ、例えば五反田に集積が進んでいるＩＴベンチャーなどにおきましては、今日的な課題に対応するために、既にテレワーク、いわゆるリモートワークで１週間に１日しか出勤されずに活動しているというようなお声もたくさん五反田エリアのベンチャー企業から入ってきます。","id":"exchange-120"},{"speaker":"塚本委員","kind":"質問・要望","question":"こういったことについて、今後、ＡＩ・ＩｏＴ活用イノベーション創出事業というのは、一応中身を要綱などで対象みたいなものを見てみると、地域の産業振興、あるいは課題解決のための製品、サービスの開発というようなことが対象にはなっているのですが、そういった意味だとちょっとずれるかなという感じはするのですけれども、今後の品川区の中小企業の発展というか支援の中で。","respondent":"山崎商業・ものづくり課長","answer":"私どものＡＩ・ＩｏＴ活用イノベーション創出事業では、委員もおっしゃっておられました企業の業務の効率化ですとか、そういった部分、それから防災に資する部分、商店街振興に資する部分ということで、実は３つの部門を今年選定して、いろいろな実証実験だとか。","id":"exchange-121"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういう意味では、まだ始まったばかりというか、今後よくよく進めていくべきというようなところもあるかと思いますけれども、ぜひ前向きにご検討いただければと思いますので、よろしくお願いいたします。こういったものも引き継がれるのかどうかを確認させていただきたいと思います。","respondent":"小林環境課長","answer":"今も乳幼児の方が使われている遊具エリアがありますので、それらの方が室内でも安心して遊べるような遊具、具体的にはこれからの検討になるかと思っているところですが、環境学習施設ですので、例えば木のぬくもりが感じられるようなものを含めて、今後。","id":"exchange-122"},{"speaker":"塚本委員","kind":"確認","question":"この環境学習施設に駐輪場をつくっていただくのはもちろん大切で、これは必要なのですけれども、戸越公園の周辺には本当に駐輪場がないので、近隣にとめられない、この環境施設のほうが足らなくてとめられないとなると、周りにとめられてしまったりする、そうするとかなり苦情が来るということも予測されるというところで、駐輪対策はそういった意味で十分でしょうかというところを確認したいと思います。","respondent":"小林環境課長","answer":"苦情等につきましても、例えば施設利用が多いイベントとか、そういったときにつきましては、自転車のご利用を控えていただくような案内をするとかを含めて、運営事業者と調整を図ってまいりたいというところで、今後検討してまいりたいと考えています。","id":"exchange-123"},{"speaker":"塚本委員","kind":"意見","question":"そうすると、公園内の駐輪は、現状のつくりではあまりできないかと思うので、そこは以前も文庫の森で桜の花見のときにものすごい数の駐輪がありまして、結構地域が騒然としたときがあったので、この駐輪対策については、できる限りそういったことのないように、利用がどれぐらいあるのかということをよく想定していただいて、十分受け入れられる駐輪場の設置をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-124"},{"speaker":"本多委員","kind":"質問","question":"２８１ページ、環境保全事業の区有施設の二酸化炭素排出量分析委託２３８万円について質問します。令和元年度では、温室効果ガス排出量分析委託２６４万９,０００円になっておりまして、令和２年度とは若干名前が違います。区有施設ということで、これは分析が進んでいるというふうに理解すればいいのでしょうか。その違いも教えてください。","respondent":"小林環境課長","answer":"そうした中では、その目標達成に向けてしっかりと施策を進めてまいりたいというところでございまして、今回の分析委託を含めながら中身はしっかり把握していきたいというふうに考えているところです。","id":"exchange-125"},{"speaker":"本多委員","kind":"質問","question":"いろいろ取り組みはあるかと思いますけれども、１つだけ伺います。それとあわせまして、（仮称）品川区立環境学習交流施設で、これからいろいろ進めていくわけですけれども、この建物の中にエアコンをつけるのか、つけないのか、また、つけるのであれば、従来型のものをつけるのか、それとも新しく開発されたような環境にふさわしいエアコンをつけるのか、その辺についてもお聞かせください。","respondent":"小林環境課長","answer":"（仮称）品川区立環境学習施設のエアコンの設置の件ですが、空調機自体はつける予定ですが、その中で、委員ご指摘のとおり、新たなというか、環境負荷の少ないエアコンを設置することを大前提にしまして、来年度の予算の中では地中熱の検討業務が入っております。","id":"exchange-126"},{"speaker":"本多委員","kind":"質問","question":"続きまして、温暖化対策事業の太陽光発電システム設置助成と、ミスト設備設置助成について伺いますが、令和２年度における対象件数は、太陽光はほぼ同額計上、ミストが大幅に減になっているのですけれども、今年は特に重要な年だとは思っておりますが、今年度の予算計上についてご見解を教えてください。","respondent":"小林環境課長","answer":"ミストと太陽光に関する助成の件です。太陽光はご指摘のとおり、例年と同等の額を助成額として見込んでいるところでございまして、家庭用３０件、１件当たり最大９万円の助成です。","id":"exchange-127"},{"speaker":"本多委員","kind":"質問","question":"わかりました。ミストシャワーの業務用とかだと、以前は２０万円以上するものとかでしたけれども、最近では水道ホースにつなげるだけのミストシャワーキットがあったり、本当にいろいろな形、形態、形状のものができてきて、レンタルも可ということなのですが、レンタルとかリースとかも、その辺も全部含めて大丈夫ということですか。教えてください。","respondent":"小林環境課長","answer":"リースについてですが、移動式のものにつきましては、リースについても助成対象としたところですので、今年度もそのような助成をさせていただいたところです。","id":"exchange-128"},{"speaker":"本多委員","kind":"質問・要望","question":"太陽光発電がついている移動式のトイレということで、これは先月２月１１日に建国記念日の建国祭という行事で私もパレードに参加して、そのパレードの参加者が使う移動式のトイレを実際に使うところを見てきたのですが、たまたま使ったものが、１つの移動トイレで男性用と女性用が隣になっていたので、あれはちょっと、もし今後そういうものを検討する場合は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-129"},{"speaker":"渡部委員","kind":"質問・要望","question":"２９１ページ、本日多く出ておりますが、融資あっ旋のところは確認させていただきたい点を少しお伺いするのと、あと、２９７ページは、中小企業活性化は、毎回お話しさせていただいている品川パビリオンの関係のところのお話、あとはエコバッグのところでお伺いできればと思います。融資あっ旋は、本日質問がたくさん出ていて、区が１.８％補助で、３年間無利子の４年目以降０.２％で５００万円。","respondent":"山崎商業・ものづくり課長","answer":"一般的な融資につきましては、経営者なり、経営のご担当の方が、委員ご紹介のような前捌きをしてご相談に来られるとかというケースが多いかなという気はしております。","id":"exchange-130"},{"speaker":"渡部委員","kind":"質問","question":"そのほかの自治体で完全に区で持ち出すというようなところ、金利１.９％なり、２.０％なり、全部保証しますというところも見受けられたのですけれども、例えば３月６日に都のものが出てきたが、これは金額が大きくて、もうちょっと大きい会社向けなのでしょう、国も今いろいろ考えている中で、個人負担の利息はなし、全額国でやるといった場合は、例えば今もう手続をして、区の緊急融資を受けられた方は。","respondent":"山崎商業・ものづくり課長","answer":"ですから、借り替えも含めて、そこは柔軟に、まずは区の経営相談員がコントロールをして促すというような感じで対応させていただいているというような状況です。","id":"exchange-131"},{"speaker":"渡部委員","kind":"質問・要望","question":"本当に厳しい状況が続いていると思いますので、お問い合わせ等には対応いただいて、何とか乗り切っていただきたいと思うところですが、普通にやっている制度融資のところなのですけれども、金利がある程度決まっていて、区が何％補助しますというような形で、どこの金融機関へ行っても同等の金利だと思うのですが、こういうものは毎年毎年何か代表者なのか、全体なのか、話し合いをされていて。","respondent":"山崎商業・ものづくり課長","answer":"直近では、日銀が金融緩和をした際に金利を一度落としたときに、区の制度融資を何％か引き下げを行ったということで、たしかもう４年ほど前になるかと思います。それから現在まで、来年度もその予定ですけれども、現行の利率でいくということで考えているところです。","id":"exchange-132"},{"speaker":"渡部委員","kind":"確認","question":"承知いたしました。ちょっと確認させていただきたかったので、ありがとうございました。これは、本当に続けてほしいと思うのですけれども、この辺、課長、意気込みをお願いしたいのと、何がいいか、シティプロモーションのほうもよかったのですけれども、このデザインがいいですよね。これはどこかから引っ張ってきたのか、誰かが考えたのか、ちゃんとお金を払ってやってもらったのか教えてください。","respondent":"山崎商業・ものづくり課長","answer":"今年度１０月に行われましたＡＩ・業務自動化展などで、来訪者の方、ブースを訪れた方にＰＲとして配布をしております。","id":"exchange-133"},{"speaker":"渡部委員","kind":"質問・要望","question":"だから、何かこれ、せっかくこんなにいいデザインをつくっていらっしゃるのだったら、ほかのものにも活用できたらいいなというのは要望でございまして、私もこれを持ってうろうろ歩こうと思います。ちなみに、今年もこの品川パビリオンは、環境展と機械要素技術展とＡＩ・業務自動化展の３つでいくのでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"オリンピックの開催の関係で、会場が実は幕張メッセのほうに変わったり、開催日程がというようなことで、来年度の予定につきましては、ＡＩ・業務自動化展と、それから機械要素技術展の２本でいくというような計画になっております。","id":"exchange-134"},{"speaker":"渡部委員","kind":"質問・要望","question":"お話はいろいろ伺っていて、私自身は、エコバッグを配ってはだめとずっと言っているのだけれども、配ってしまうと、子どもも誰もかれも欲しい欲しいと言って、そのまま寝てしまう可能性があるなどという話はよくさせていただいていて、エコバッグを売ればいいのにと言ったのですけれども、今日はちょっとその話は置いておいて、エコバッグを、今回つくられますが、どういうところでお配りになる予定なのか。","respondent":"小林環境課長","answer":"やはり持ってもらって、ふだんから使ってもらえるデザインが、やはり一番望ましい形かというふうに思っているところですので、そういったところも情報収集をしながら、また使いやすさというところも含めて検討をしています。","id":"exchange-135"},{"speaker":"渡部委員","kind":"質問・要望","question":"先ほどちょっと申し上げました、折りたたんでポケットに入れられて、買い物をしたら、ちょっと肩からかけられるというようなものをぜひ検討いただきたいのと、これは、デザインがいいのです。こういうものもありますので、ぜひご検討いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"},{"speaker":"西本委員","kind":"質問","question":"２９３ページの伝統的産業の振興に入るのでしょうか、中小企業センターの中で実演をしていただいております。できればもう少し人通りのあるところ、大型商業施設であったり、あとは駅であったりということで、もう少し配慮があっていいのではないかと思いますが、いかがでしょうか。次に、２９５ページの事業承継支援事業、この成果はどれだけだったのでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"日によって来訪者の方だったり、例えば今日的のようなことがあったりとか、あと、中小企業センターが２年間にわたる大規模な工事をしていたりというようなことで、さまざまありますが、他の、例えば東京都庁の観光のブースで出展をいただいたりとか。","id":"exchange-137"},{"speaker":"西本委員","kind":"提案","question":"伝統工芸の実演ですけれども、やはりもったいないです。なので、そこそこのところは、どこまで踏み込むべきなのかということを考えながら、ただ続けていきたいという思いがあると思うので、それについては別ないろいろな方法がありますよという提案も必要になってくるのかというふうに思います。それから、ビジネスクラブのほうなのですけれども、こういう形式をなぜとらなければいけないのかと思うのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-138"},{"speaker":"須貝委員","kind":"質問","question":"私は、２９２ページ、産業経済費についてお聞きしたいと思います。品川区の区内産業の現状についてお聞きします。その影響で、観光地はもちろん、飲食店では予約キャンセルの急増などにより、売り上げが著しく落ち、通常時の７割から８割減少したお店もあると報道されています。お聞きします。区内産業のうち、中小・零細企業の経営状況の実態を教えてください。教えてください。","respondent":"山崎商業・ものづくり課長","answer":"ただ、例示された商店街の飲食店等の融資などの窓口でいろいろなお声を聞き始めているところですので、そうしたお声に真摯に対応していく必要があるかというところは感じているところです。","id":"exchange-139"},{"speaker":"須貝委員","kind":"質問","question":"この２つが動かなければ、お金が全く動かない。区内産業２万社のうち８５％が中小・零細企業であるならば、新型コロナウイルス感染症の影響で倒産や廃業は激増し、連鎖倒産も起きるのではないかというふうに大変心配されます。経営変化対策資金、これは先手を打つものですごく重要なことですが、これは全ての小規模企業に案内を出していただけるのでしょうか。予算は限度があるはずなので、教えてください。","respondent":"山崎商業・ものづくり課長","answer":"ただ、まだ結論づけて定義をしてというような状況ではありませんので、当面の喫緊の課題について、区としては一生懸命対応していくというようなところで考えているところです。","id":"exchange-140"},{"speaker":"須貝委員","kind":"質問","question":"その登録している企業だけというお話とか、こちらからメールマガジンで連絡している、品川区内の中小・零細企業は、そんなに少ないわけないではないですか。そうしたら、今回、誰が見ても、誰が考えても、みんな大変だというのはわかります。先ほどからいろいろな方から質問がありました。だって、お客さんが来ないのです。政府は不要不急の外出を控えてください。だから、行けないですよね。","respondent":"山崎商業・ものづくり課長","answer":"そういう意味では、製造業の小規模事業者については、区のほうでは先ほどの説明にかぶりますけれども、しっかり捕捉していますので、そこには直接声を届けるということで、一般的なＰＲ手法と、個別にご案内をする手法を織り交ぜながら、でき得る限りのＰＲをさせていただいて。","id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"これで影響を受ける日本の企業は、約２万社といわれています。２万社いるということは、その下請け、また孫請けを含めたらどれだけいるかわかりません。だから、一生懸命やられていることはわかりますが、大変なことはわかりますが、身近な品川区ではないですか。やはり、品川区なのですから、その地域へ行けばわかります。地場産業が完全に崩壊してしまうではないですか。だから言っているのです。","respondent":"山崎商業・ものづくり課長","answer":"うちの銀行から人材を出すので、ぜひ品川区の会議室で特設ブースでもつくって対応したらどうだ、こういうようなことが地域の声として出ておりますので、さまざま、今回のこと、先ほどの事業承継も含めて、地元信金とタッグを組んで。","id":"exchange-142"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、せっかく地元、この品川区の区民のため、企業のため、小規模事業者のため、身近な品川区が、案内状を出すことはいいではないですか。だけど、このようなことも知らない、このようなこともわからないで、その会社が倒産したり廃業するということだけは避けていただきたいと思います。ぜひそういう姿勢で取り組んでいただきたいと思います。もう一度、ご見解をお聞かせください。","respondent":"山崎商業・ものづくり課長","answer":"商店街も含めた産業振興につきましては、さまざまな角度から多様な手法を使って、品川区内の産業の振興を区としては実現させる、あるいは、そのご支援をするということで、事業の組み立てを行っておりますので、もう少し、新型コロナウイルス感染症の関係について言いますと。","id":"exchange-143"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に申し上げます。ぜひ区民の声、それから中小・零細企業、小規模、そういう企業の叫びは、実態はしっかり認識して、舵を少し切っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-144"},{"speaker":"中塚委員","kind":"質問・要望","question":"２９３ページの中小企業経営支援事業費について、新型コロナウイルス感染症に影響しての経営支援について伺いたいと思います。初めに、補正について伺いたいと思います。そういう時期だったのです。そうなってくると、第１回定例会の最終本会議で補正をかけていく、こういう手法もあるのではないかと思います。ぜひ機敏な対応をしていただきたいと思いますが、補正についてのお考えを伺いたいと思います。","respondent":"品川財政課長","answer":"どのぐらいの需要が見込まれるかというところを正確に見据えていきながら、補正予算につきましては、適切な時期にさまざまな手法をとれると思いますので、補正予算をそのようなやり方で計上していきたいと、このように考えております。","id":"exchange-145"},{"speaker":"中塚委員","kind":"質問・要望","question":"今日どういう発表をされたかはまだ私も知りませんけれども、ただ、いずれにしても、自営業の方やフリーランスの方が１日４,１００円というのはどういうことかと。ぜひ品川区としては、国に対して引き上げを要望していただきたいというのが１点。同じことですけれども、正規、非正規と差をつけるという考え方も私はおかしいと思っているのですが、区の考えを伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"区としましては、雇用調整助成金の関係の話かと受けとめていますので、国が方針なり決めた部分、それから、今もおっしゃった、なかなか今も情報が追加されたりとかという状況ですので、今は状況を見極めつつ、区としての産業振興施策を適正に行っていくという考えです。","id":"exchange-146"},{"speaker":"中塚委員","kind":"質問・要望","question":"状況を見てということですけれども、フリーランスと自営業の休業補償が１日４,１００円、最低賃金をさらに下回る、こういう状況でよいのかと私は思います。先ほど伺ったのは、引き上げを国に求めていただきたいと思いますが、改めて伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"区としましては、国の雇用主に向けた雇用調整助成金の部分でありますとか、無利子融資の制度の設計、その他もろもろを勘案して、やはり正しく状況を把握し、品川区としてとるべき産業振興施策などをしっかり適正に実行していくというようなことが必要かと考えるところです。","id":"exchange-147"},{"speaker":"中塚委員","kind":"提案","question":"私も町に出て話を聞いてきました。今日もたくさん出ております。ぜひどういう業態に影響が起きているのか、相談で把握するのではなく、区から状況を把握していただきたいと思いますが、いかがでしょうか。そして改めて、フリーランスや自営業について、１日４,１００円、意見を言う状況ではないとは言わずに、引き上げを求める状況だと思いますので、その点、重ねて伺いますが、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"区としましては、そうした身近な経営ベースのしっかりした景況感をつかみつつ、国の動向にも注意しつつ、最適な産業の振興施策を展開するというふうに考えるところです。","id":"exchange-148"},{"speaker":"中塚委員","kind":"質問・要望","question":"しかも、所得が減っている、日本経済の６割を占める個人消費が落ち込んでいるというリーマンショックにはない影響があると思います。ぜひ状況を把握していただいて、国に対しても、融資は新たな借金をさせるものになりますので、ぜひ自営業やフリーランスに対する給付の引き上げを強く求めていただきたいとお願いして終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-149"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私は、２８５ページのもったいないプロジェクト等について伺いたいと思いますが、その前に、３０３ページのプレミアム付区内共通商品券発行助成について伺います。４億円ずつ、今、予定されているようですけれども、状況を見ながら前倒しで、例えば６億円分を、先に春に発行するとかということも柔軟に検討されることかと思うのですけれども、そこについての見解を教えてください。","respondent":"山崎商業・ものづくり課長、小林環境課長","answer":"予算を編成する際には、商連とちょうど２分の１ずつ、４億円、４億円でというスキームにはなっておりますが、例えばそれを前倒しするようなことも可能ではありますので、そういう変化等、消費の低迷云々ということがありましたら。この時期を捉えまして、区としましても、フードドライブの実施を、品川、大崎、大井、荏原、八潮、各地区において１日ずつフードドライブを実施することとあわせまして。","id":"exchange-150"},{"speaker":"たけうち委員","kind":"提案","question":"そうした中で言いますと、冊子を発行するわけですけれども、その中で、もったいないというのは、ある意味ではＳＤＧｓそのものでありまして、例えば、そうしたものの意義を冊子に掲載していくとか、また、今後身近となるよう、ＳＤＧｓは、我々もそうですけれども、一般の区民にはなかなかまだ認知されていない中で、身近な商店街を通じてそうしたことを周知していくという取り組みを。","respondent":"小林環境課長","answer":"委員ご提案の商店街との連携ですが、区商連の中でもそういった商店街の中にはＳＤＧｓに非常に関心が高い商店街があるということは聞いているところですので、そういったところと意見交換しながら、その周知が広がる取り組みについては。","id":"exchange-151"},{"speaker":"たけうち委員","kind":"質問","question":"もう既に品川区にもＬＥＤの装飾灯をつけている商店街もいっぱいありますし、それ自体がＳＤＧｓにつながっているのだということも、ぜひ商店街の方にもご理解をいただいて、そこに例えばもったいない推進店みたいなシールを貼っていただいて、来た区民の方が、これは何だろうという、そういう会話の中でそういったものが周知されていくのかと、そういう身近な取り組みをぜひ工夫していただいて、今。","respondent":"山崎商業・ものづくり課長","answer":"ＬＥＤ化を例に出していただきまして、そうした考え方が浸透しております。東京都の補助金、それからその上乗せの品川区の制度も含めて、かなり認知度が広がっておりますので、そうした観点から関心を持っていただく必要性も大いにあるかというところで感じた次第です。","id":"exchange-152"},{"speaker":"大沢委員","kind":"質問","question":"２９９ページの商店街活性化事業費をお願いしますが、これに入る前に、先ほど来出ている融資の、今回のこういう事件というか、事象にかかわって、緊急融資ということで出ているのですけれども、先ほど来、「飲食」という言葉、「飲食店」という単語が多く出てきておりますけれども、この中で飲食店も含め融資制度ですけれども、通常融資を行うには手続が煩雑なのが玉にきずのところがあるのですけれども。","respondent":"山崎商業・ものづくり課長","answer":"今回、喫緊の課題ということで、手続の簡素化ということと、１つ１つの標準的にかかる時間を短くするという簡素化、双方でいろいろ検討をしております。一例で申し上げますと、相談は予約制を敷いておりますので、電話なりでその前段のやりとりがあります。","id":"exchange-153"},{"speaker":"大沢委員","kind":"質問","question":"時間の短縮も、それはもちろんですけれども、手続上、ペーパー上の、申請したりとか、もろもろを少なくしながら簡素化を図りながらやられるようなことはお話をされているということでいいのでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"お金をお貸しする契約ですので、省略できるものと、そうではないものがありますけれども、例えば、経営変化を判断する５％という指標がありますが、そこのところについては、数字的なものではないキャンセル台帳を確認するとか。","id":"exchange-154"},{"speaker":"大沢委員","kind":"質問・要望","question":"確かに税理士とか経理士がついていればできますが、そういう方ばかりではないと思いますので、そういうところを簡素化に努めていただきたいと思います。通常であれば融資が出にくいやに私自身の記憶では認識しておるのですけれども、そこのところはどのようにして解消されて、緊急かつ円滑な融資が行われるのか教えてください。","respondent":"山崎商業・ものづくり課長","answer":"ですから、一度戻っていただいてというよりも、いろいろ関係のものを持ってきていただいて、その場で一緒につくるという作成支援も含めてやらせていただいておりますので、それが最大の時間短縮につながっているかという感じがします。","id":"exchange-155"},{"speaker":"大沢委員","kind":"質問・要望","question":"これは私の過去の経験で、昔、某アイスクリーム店をフランチャイズで経営しておりまして、そのときはアイスクリームという１万円ぐらいの在庫を幾つも常に在庫として抱えているものですから、そこのところは融資が比較的おりました。その中で、今のミレニアム世代が中心になるわけですけれども、その動態を読みながら、今後の商業動向、商業特性についてどのようにお考えなのか教えてください。","respondent":"山崎商業・ものづくり課長","answer":"そういう意味では、商店街でありましたら、商店街を代表するような何か工夫のある魅力あるものを、例えば武蔵小山エリアで地ビールを出されたり、そうしたクリエイティブな取り組みといいますか、そういった活動も１つ方向性としてはあるのかなというふうに思うところです。","id":"exchange-156"},{"speaker":"大沢委員","kind":"意見","question":"物からサービスということで、今、サービスで商売が成り立つわけですけれども、そこの中で、今、事業の中で、まさに物からサービスへという消費動向の変化とともに、イベント事業の助成があります。それがまさに商店の物に対してイベントという付加価値をつけた事業ですけれども、これについての目的と現状の課題をお知らせください。","respondent":"山崎商業・ものづくり課長","answer":"課題、問題としましては、そのイベントでは、一定その期間なり、そのときだけは集客が成功しても、なかなか継続的なご商売の販売の促進だとか、売り上げに結びつかない、日常との乖離といいますか、その辺が１つ課題かなという気はしています。","id":"exchange-157"},{"speaker":"大沢委員","kind":"質問","question":"その課題を解決するために、もうちょっと仕掛けが必要であると思いますけれども、その課題解決に向けた、平成２８年ということですから、もう２年余がたっているわけですけれども、その平成２８年以降の取り組みの中で、課題解決に向けてどのような取り組みをされたのか教えてください。","respondent":"山崎商業・ものづくり課長","answer":"大きなイベントに対しての助成と、それから、日ごろの商店街のご商売というか、日ごろの諸活動をご支援する視点が必要だろうということで、非常に補助額、助成額は小さいのですけれども、例えば商店街が毎週土曜日の朝、朝市を行うとか、夕方、夕市を行うとか。","id":"exchange-158"},{"speaker":"大沢委員","kind":"質問","question":"新小岩のルミエールという商店街も歩いてまいりましたけれども、やはり同じような感じでありまして、そもそもの商店街のありよう自体をもう１回、新しい時代に向けた消費動向に向けて、物からサービスへという消費の変化に結びつけた新しい商店街に、これは漠然とし過ぎていて難しいですけれども、そのように考えることを始める必要があると思いますけれども、どのようにお考えでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"物からサービスに変容するといいますのは、商店街が物を売る商売だけの魅力だけではなくて、そこには多様な人が集まり、そこで繰り広げられるにぎわいの創出の部分でありますとか、先ほど来ありました環境に対する取り組みが行われたり。","id":"exchange-159"},{"speaker":"石田（秀）委員","kind":"質問","question":"２８７ページ、集団回収について伺います。２８３ページの（仮称）品川区立環境学習交流施設、それから２８５ページ、ワンウェイ（使い捨て）プラスチック削減推進、エコバッグについて、先ほどからいろいろな議論があるので、少しだけそれを。そこら辺のところをどう考えて、今これを行っていこうとされているのか、ここからお聞かせ願いたいと思います。","respondent":"工藤品川区清掃事務所長","answer":"いずれにいたしましても、やはり集団回収は行政回収に比べましてリサイクル意識が地域の中で高まる、その原資が地域活動に資されるというところで進めてまいりたいというふうに考えておるところです。","id":"exchange-160"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはぜひ、今お話があったように、ルート対策費で対応していこう、私もこれはそれで結構なのだけれども、今のところ、ルート対策費を使ったというのは、私の記憶ではないのだけれども、ここら辺のところは、そういうところをある程度入れてでも、しっかり今の体制を維持していくのだというような答弁に聞こえたのだけれども、そういうつもりでいいでしょうかという確認。","respondent":"工藤品川区清掃事務所長","answer":"なかなか回収量が上がらないという状況がありますので、そういった部分、回収金額も含めまして、例えば頑張った団体にはもう少しインセンティブをつけることができないのかとか、そういった部分の制度設計等は引き続き検討してまいりたいというふうに思ってあります。","id":"exchange-161"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"床は無添加にできるかどうかは微妙だけれども、天壁は漆喰にしてほしい。そういうことも含めると、多目的スペースとか、広いところでやってほしいけれども、これぐらいの大きさなら、そういう１つの勉強施設としてできると思うので、この２点はぜひやっていただきたいと思うのだけれども、それはあとで、これもお願いします。極論を言えば、５０円値段を上げてもいいではないですか。","respondent":"小林環境課長","answer":"もちろん素材もそうです、デザインもそうです、さまざまな観点で広く区民の方から愛されて使っていただける工夫は、しっかりと検討してまいりたいというふうに考えているところです。","id":"exchange-162"},{"speaker":"石田（秀）委員","kind":"意見","question":"１つだけ、先ほど言ったプラスチックの容器の削減ですけれども、これはしつこいようだけれども、私も町会とかでそれはいろいろ見せていただいて、今度はこうだとか、木のスプーンだとか、いろいろなお話があるのは重々わかってあえて言っているのですが、これはやっぱり各町会でそれぐらいの努力はしてくれと、レジ袋もそうだけれども、それは対応するのは難しい部分もあるかもしれないけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-163"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/384106?Template=document&Id=1116#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":125845,"voices":364}}]);
